function secureRandomInt(min, max) {
    return crypto.randomInt(min, max);
}

class SimpleCache {
    constructor(ttl = 300000) { 
        this.cache = new Map();
        this.ttl = ttl;
    }
    
    set(key, value) {
        this.cache.set(key, {
            value,
            expires: Date.now() + this.ttl
        });
    }
    
    get(key) {
        const item = this.cache.get(key);
        if (!item) return null;
        
        if (Date.now() > item.expires) {
            this.cache.delete(key);
            return null;
        }
        
        return item.value;
    }
    
    delete(key) {
        this.cache.delete(key);
    }
    
    clear() {
        this.cache.clear();
    }
    
    size() {
        return this.cache.size;
    }
}

const userCache = new SimpleCache(300000); 
const gameCache = new SimpleCache(60000);  

async function getCachedUserData(userId, dbModel, forceRefresh = false) {
    const key = `user_${userId}`;
    
    if (!forceRefresh) {
        const cached = userCache.get(key);
        if (cached) {
            return cached;
        }
    }
    
    const userData = await dbModel.findOne({ id: userId }).lean();
    
    if (userData) {
        userCache.set(key, userData);
    }
    
    return userData;
}

function invalidateUserCache(userId) {
    userCache.delete(`user_${userId}`);
}

setInterval(() => {
    const now = Date.now();
    let cleaned = 0;
    
    for (const [key, item] of userCache.cache.entries()) {
        if (now > item.expires) {
            userCache.delete(key);
            cleaned++;
        }
    }
    
    if (cleaned > 0) {
        console.log(`🧹 تنظيف Cache: تم حذف ${cleaned} عنصر قديم`);
    }
}, 600000);

