const GAMES_PER_LEVEL = 10;

function calcRealGames(challengesnumber) {
    return Math.max(0, parseInt(challengesnumber) || 0); 
}

function calcLevel(challengesnumber) {
    return Math.floor((challengesnumber || 0) / GAMES_PER_LEVEL);
}

const LEVEL_ROLES = [
    { roleId: '1500921440227299409', level: 5   },
    { roleId: '1500921436968058981', level: 10  },  
    { roleId: '1500921433759551599', level: 20  },  
    { roleId: '1500921428017545236', level: 30  },  
    { roleId: '1500921424452387108', level: 50  },  
    { roleId: '1500921421101011034', level: 70  },  
    { roleId: '1500921414772068516', level: 100 },  
    { roleId: '1500921403577467001', level: 200 },  
];

function getLevelRole(currentLevel) {
    const sorted = [...LEVEL_ROLES].sort((a, b) => b.level - a.level);
    return sorted.find(r => currentLevel >= r.level) || null;
}

async function updateLevelRole(member, currentLevel) {
    try {
        const deservedRole = getLevelRole(currentLevel);

        for (const lr of LEVEL_ROLES) {
            const role = member.guild.roles.cache.get(lr.roleId);
            if (role && member.roles.cache.has(lr.roleId)) {
                await member.roles.remove(role).catch(() => {});
            }
        }

        if (deservedRole) {
            const role = member.guild.roles.cache.get(deservedRole.roleId);
            if (role) {
                await member.roles.add(role).catch(() => {});
                return deservedRole;
            }
        }

        return null;
    } catch (e) {
        console.error('❌ خطأ في updateLevelRole:', e);
        return null;
    }
}

async function checkAndGrantLevelRole(guild, userId, gamesPlayed) {
    try {
        if (!guild) return;

        const member = await guild.members.fetch(userId).catch(() => null);
        if (!member) return;

        const oldLevel = calcLevel(gamesPlayed - 1);
        const newLevel = calcLevel(gamesPlayed);

        const levelChanged = newLevel !== oldLevel;

        
        await updateLevelRole(member, newLevel);

        
        if (!levelChanged) return;

        const realGames = calcRealGames(gamesPlayed);

        
        const levelUpMsg =
            `> 🎮 **${member.user.username}** وصل للمستوى **${newLevel}**! (${realGames} لعبة)`;

        
        const oldRole = getLevelRole(oldLevel);
        const newRole = getLevelRole(newLevel);
        const gotNewRole = newRole && (!oldRole || newRole.roleId !== oldRole.roleId);

        const roleMsg = gotNewRole
            ? `\n> 🏆 **حصلت على رتبة المستوى ${newRole.level}!**`
            : '';

        
        await member.send(levelUpMsg + roleMsg).catch(() => {});

    } catch (e) {
        console.error('❌ خطأ في checkAndGrantLevelRole:', e);
    }
}

class TopListCache {
    constructor() {
        this.cache = new Map();
        this.TTL = 120000; 
        this.buildingCache = new Set(); 
        this.isReady = false; 
    }
    
    async getTopList(type, dbModel, limit = 10) {
        const key = `top_${type}_${limit}`;
        
        
        const cached = this.cache.get(key);
        if (cached && Date.now() < cached.expires) {
            return cached.data;
        }
        
        
        if (this.buildingCache.has(key)) {
            await new Promise(resolve => setTimeout(resolve, 100));
            return this.getTopList(type, dbModel, limit);
        }
        
        this.buildingCache.add(key);
        
        try {
            let sort = {};
            if (type === 'coins') sort = { coins: -1 };
            else if (type === 'level') sort = { level: -1, xp: -1 };
            else if (type === 'rep') sort = { rep: -1 };
            
            
            const topUsers = await dbModel.find({})
                .select('id coins level xp rep') 
                .sort(sort)
                .limit(limit)
                .lean(); 
            
            
            this.cache.set(key, {
                data: topUsers,
                expires: Date.now() + this.TTL
            });
            
            return topUsers;
        } finally {
            this.buildingCache.delete(key);
        }
    }
    
    
    invalidate(type) {
        for (const key of this.cache.keys()) {
            if (key.includes(`top_${type}`)) {
                this.cache.delete(key);
            }
        }
    }
    
    
    cleanup() {
        const now = Date.now();
        for (const [key, value] of this.cache.entries()) {
            if (now > value.expires) {
                this.cache.delete(key);
            }
        }
    }
}

const topCache = new TopListCache();

let autoTopRefreshInterval = null;

async function startAutoTopRefresh(dbModel) {
    if (autoTopRefreshInterval) return; 
    
    
    try {
        await topCache.getTopList('coins', dbModel, 30);
        
        
        const allUsers = await dbModel.find({}).select('id coins').lean();
        let totalCoins = 0;
        for (let userData of allUsers) {
            totalCoins += parseInt(userData.coins || 0);
        }
        topCache.cache.set('total_coins', {
            data: totalCoins,
            expires: Date.now() + 120000
        });
        
        topCache.isReady = true;
        console.log('✅ التوب تم تحميله وجاهز!');
    } catch (error) {
        console.error('❌ خطأ في التحميل الأولي:', error);
    }
    

}

