const messageRateLimit = new Map();
const MESSAGE_RATE_LIMIT = 50; 
const RATE_WINDOW = 60000; 

function checkMessageRateLimit(userId) {
    const now = Date.now();
    const userLimit = messageRateLimit.get(userId);
    
    if (!userLimit) {
        messageRateLimit.set(userId, { count: 1, resetTime: now + RATE_WINDOW });
        return true;
    }
    
    if (now > userLimit.resetTime) {
        messageRateLimit.set(userId, { count: 1, resetTime: now + RATE_WINDOW });
        return true;
    }
    
    if (userLimit.count >= MESSAGE_RATE_LIMIT) {
        return false; 
    }
    
    userLimit.count++;
    return true;
}

setInterval(() => {
    const now = Date.now();
    let cleaned = 0;
    for (const [userId, limit] of messageRateLimit.entries()) {
        if (now > limit.resetTime) {
            messageRateLimit.delete(userId);
            cleaned++;
        }
    }
    if (cleaned > 0) {
        console.log(`🧹 تنظيف Rate Limit: ${cleaned} مستخدم`);
    }
}, 300000);

