const ACCOUNTS_FILE = './accounts.json';
const MAX_ACCOUNT_BALANCE = 50000000;



function loadAccounts() {
    try {
        if (fs.existsSync(ACCOUNTS_FILE)) {
            const data = fs.readFileSync(ACCOUNTS_FILE, 'utf8');
            return JSON.parse(data);
        }
    } catch (error) {
        console.error('Error loading accounts:', error);
    }
    return {};
}

function saveAccounts(accounts) {
    try {
        fs.writeFileSync(ACCOUNTS_FILE, JSON.stringify(accounts, null, 4), 'utf8');
        return true;
    } catch (error) {
        console.error('Error saving accounts:', error);
        return false;
    }
}

function getLowestBalanceAccount() {
    const accounts = loadAccounts();
    let lowestAccount = null;
    let lowestBalance = Infinity;
    
    for (const [id, account] of Object.entries(accounts)) {
        if (account.status === 'invalid') continue;
        
        if (account.balance >= MAX_ACCOUNT_BALANCE) continue;
        
        if (account.balance < lowestBalance) {
            lowestBalance = account.balance;
            lowestAccount = account;
        }
    }
    
    return lowestAccount;
}

function updateAccountBalance(accountId, amount) {
    const accounts = loadAccounts();
    if (accounts[accountId]) {
        accounts[accountId].balance = (accounts[accountId].balance || 0) + parseInt(amount);
        saveAccounts(accounts);
        return accounts[accountId];
    }
    return null;
}

