  if (!messageId) {
    return interaction.reply({ content: '❌ معرف الرسالة غير صالح.', ephemeral: true });
  }

  const pf = await provablyFairSystem.model.findOne({ messageId }).lean().catch(() => null);
  if (!pf) {
    return interaction.reply({ content: '❌ لا توجد بيانات Provably Fair لهذه اللعبة.', ephemeral: true });
  }

  const recomputed = crypto.createHash('sha256').update(String(pf.serverSeed || ''), 'utf8').digest('hex');
  const hashMatch = recomputed === String(pf.serverSeedHash || '');
  const roundsText = (pf.rounds || [])
    .slice(0, 24)
    .map((r) => `\`${r.nonce}\` • **${r.value}** (${r.min}-${r.max}) ${r.forcedByRule ? '`قاعدة`' : ''}`)
    .join('\n');

  const verifyEmbed = new MessageEmbed()
    .setColor(hashMatch ? '#22c55e' : '#ef4444')
    .setTitle('🔐 Provably Fair — التحقق')
    .setDescription(
      hashMatch
        ? 'تم التحقق بنجاح: الهاش يطابق الـ Server Seed.'
        : 'تحذير: يوجد اختلاف بين الهاش المسجل والمحسوب.'
    )
    .addFields(
      { name: 'نوع اللعبة', value: `\`${pf.no3 || 'game'}\` · ${pf.modeLabelAr || '—'}`, inline: false },
      { name: 'Server Seed Hash (قديم)', value: `\`${pf.serverSeedHash || '—'}\``, inline: false },
      { name: 'Server Seed', value: pf.status === 'ended' ? `\`\`\`${pf.serverSeed}\`\`\`` : 'سيتكشف بعد انتهاء اللعبة.', inline: false },
      { name: 'Hash (محسوب)', value: `\`${recomputed}\``, inline: false },
      { name: `Client Seed — <@${pf.user1}>`, value: `\`${pf.clientSeed1 || '—'}\``, inline: false },
      { name: `Client Seed — <@${pf.user2}>`, value: `\`${pf.clientSeed2 || '—'}\``, inline: false },
      { name: 'الدورات', value: roundsText || 'لا توجد دورات.', inline: false }
    )
