function generateRandomCode() {
try {
    const schedule = JSON.parse(fs.readFileSync("./dailyCodesSchedule.json", "utf8"));
    const codeNames = schedule.codeNames || ["happy", "golden", "lucky", "winner"];
    const randomIndex = Math.floor(Math.random() * codeNames.length);
    const baseCode = codeNames[randomIndex];
    const randomNum = Math.floor(Math.random() * 10000);
    return `${baseCode}${randomNum}`;
} catch (error) {
    console.error('Error generating random code:', error);
    return `code${Date.now()}`;
}
}

