async function sendDailyCode() {
try {
    const schedule = JSON.parse(fs.readFileSync("./dailyCodesSchedule.json", "utf8"));
    const channelId = schedule.channelId;
    const codeAmount = schedule.codeAmount || 100000;
    const maxUses = schedule.maxUses || 50;
    
    const code = generateRandomCode();
    
    let codes;
    try {
        codes = JSON.parse(fs.readFileSync("./codes.json", "utf8"));
    } catch (err) {
        codes = {};
    }
    
    const expiryTimestamp = Date.now() + (24 * 60 * 60 * 1000);
    codes[code] = {
        amount: codeAmount,
        usesLeft: maxUses,
        expiry: expiryTimestamp,
        usedBy: []
    };
    
    fs.writeFileSync("./codes.json", JSON.stringify(codes, null, 2));
    
    const now = new Date();
    const iraqTime = new Date(now.toLocaleString("en-US", { timeZone: "Asia/Baghdad" }));
    const timeString = iraqTime.toLocaleTimeString("en-US", { hour12: false, hour: "2-digit", minute: "2-digit" });
    const dateString = iraqTime.toLocaleDateString("en-US", { year: "numeric", month: "2-digit", day: "2-digit" });
    
    schedule.lastSent = {
        code: code,
        timestamp: Date.now(),
        time: timeString,
        date: dateString
    };
    
    if (!schedule.history) {
        schedule.history = [];
    }
    schedule.history.push({
        code: code,
        timestamp: Date.now(),
        time: timeString,
        date: dateString,
        amount: codeAmount,
        maxUses: maxUses
    });
    
    if (schedule.history.length > 30) {
        schedule.history = schedule.history.slice(-30);
    }
    
    fs.writeFileSync("./dailyCodesSchedule.json", JSON.stringify(schedule, null, 2));
    
    const channel = await client.channels.fetch(channelId);
    if (!channel) {
        console.error(`❌ القناة ${channelId} غير موجودة`);
        return;
    }
    
    const embed = new MessageEmbed()
        .setTitle('🎁 كود جديد!')
        .setDescription(`**الكود:** \`${code}\`\n**القيمة:** ${codeAmount.toLocaleString()} عملة \n**عدد الاستخدامات:** ${maxUses}\n**ينتهي بعد:** 24 ساعة`)
        .setColor(serverColor)
        .setFooter({ text: `ملاحظة:ممنوع تستعمل حسابات ثانية علمود ترسل لنفسك الاكواد` })
        .setTimestamp();
    
    await channel.send({ embeds: [embed] });
    console.log(`✅ تم إرسال الكود اليومي: ${code} في القناة ${channelId}`);
    
} catch (error) {
    console.error('❌ خطأ في إرسال الكود اليومي:', error);
}
}

