async function getOrCreateQuestProgress(staffId) {
    let progress = await StaffQuestProgress.findOne({ staffId });
    if (!progress) {
        progress = await StaffQuestProgress.create({ staffId });
    }
    return progress;
}

async function getCurrentQuest() {
    return await Quest.findOne({ active: true });
}

async function updateStaffTicketCount(staffId, increment = true) {
    try {
        const progress = await getOrCreateQuestProgress(staffId);
        if (increment) {
            progress.ticketsCount += 1;
            if (!progress.ticketsCompleted && progress.ticketsCount >= (await getCurrentQuest())?.requiredTickets) {
                progress.ticketsCompleted = true;
                progress.ticketsCompletedDate = new Date();
            }
        } else {
            progress.ticketsCount = Math.max(0, progress.ticketsCount - 1);
            if (progress.ticketsCount < (await getCurrentQuest())?.requiredTickets) {
                progress.ticketsCompleted = false;
                progress.ticketsCompletedDate = null;
            }
        }
        await progress.save();
        return progress;
    } catch (error) {
        console.error('Error updating staff ticket count:', error);
        return null;
    }
}

