client.on('messageCreate', async message => {
    if (message.author.bot || !message.guild) return;
    
    const commandPrefix = "!";
    const cmd = message.content.trim().split(/\s+/)[0].toLowerCase();
    const args = message.content.trim().split(/\s+/);
    
    // !questleaderboard - Show top staff
    if (cmd === commandPrefix + 'questleaderboard') {
        try {
            const { questSystemEnabled, questRoleId } = require('./config.json');
            if (!questSystemEnabled) return;
            
            const quest = await getCurrentQuest();
            if (!quest) {
                return message.reply("❌ لا توجد مهمة نشطة حالياً.");
            }
            
            const allProgress = await StaffQuestProgress.find().lean();
            
            if (allProgress.length === 0) {
                return message.reply("❌ لا توجد بيانات للعرض بعد.");
            }
            
            // Sort by combined progress
            const sorted = allProgress.sort((a, b) => {
                const aTotal = a.messagesCount + a.ticketsCount;
                const bTotal = b.messagesCount + b.ticketsCount;
                return bTotal - aTotal;
            }).slice(0, 10);
            
            let leaderboardText = '';
            for (let i = 0; i < sorted.length; i++) {
                const user = await message.guild.members.fetch(sorted[i].staffId).catch(() => null);
                const name = user?.user.username || sorted[i].staffId;
                
                const msgProg = `${sorted[i].messagesCount}/${quest.requiredMessages}`;
                const tickProg = `${sorted[i].ticketsCount}/${quest.requiredTickets}`;
                const completed = (sorted[i].messagesCompleted ? '✅' : '⏳') + ' ' + (sorted[i].ticketsCompleted ? '✅' : '⏳');
                
                leaderboardText += `**${i + 1}.** ${name}\n  ✉️ \`${msgProg}\` | 🎫 \`${tickProg}\` | ${completed}\n\n`;
            }
            
            const embed = new MessageEmbed()
                .setTitle("🏆 لوحة المتصدرين - المهام")
                .setDescription(leaderboardText)
                .setColor("#FFD700")
                .setFooter({ text: "التحديث فوري" })
                .setTimestamp();
            
            return message.reply({ embeds: [embed] });
        } catch (error) {
            console.error('Error showing leaderboard:', error);
            return message.reply("❌ حدث خطأ أثناء عرض لوحة المتصدرين.");
        }
    }
    
    // !resetquests - Reset all progress (admin only)
    if (cmd === commandPrefix + 'resetquests') {
        try {
            const hasQuestRole = questRoleId && message.member?.roles.cache.has(questRoleId);
            const isOwner = isOwnerOrGranted(message.author.id, '!resetquests');
            
            if (!hasQuestRole && !isOwner) {
                return message.reply("❌ أنت لا تملك الصلاحيات الكافية.");
            }
            
            const { questSystemEnabled, questLogChannelId } = require('./config.json');
            if (!questSystemEnabled) return;
            
            // Confirm action
            if (args[1]?.toLowerCase() !== 'confirm') {
                return message.reply("⚠️ هذا سيحذف كل بيانات التقدم! استخدم `!resetquests confirm` للتأكيد.");
            }
            
            const deletedCount = await StaffQuestProgress.deleteMany({});
            
            const embed = new MessageEmbed()
                .setTitle("✅ تم إعادة تعيين المهام")
                .setDescription(`تم حذف بيانات **${deletedCount.deletedCount}** عضو.`)
                .setColor("#FF0000");
            
            await message.reply({ embeds: [embed] });
            
            // Log to quest channel
            if (questLogChannelId) {
                const logChannel = await message.guild.channels.fetch(questLogChannelId).catch(() => null);
                if (logChannel) {
                    const logEmbed = new MessageEmbed()
                        .setTitle("🔄 تم إعادة تعيين المهام")
                        .addFields(
                            { name: "الفاعل", value: `<@${message.author.id}>`, inline: true },
                            { name: "عدد الأعضاء المتأثرين", value: `${deletedCount.deletedCount}`, inline: true }
                        )
                        .setColor("#FF0000")
                        .setTimestamp();
                    
                    logChannel.send({ embeds: [logEmbed] }).catch(() => {});
                }
            }
        } catch (error) {
            console.error('Error resetting quests:', error);
            return message.reply("❌ حدث خطأ أثناء إعادة التعيين.");
        }
    }
    
    // !queststats - Show quest statistics
    if (cmd === commandPrefix + 'queststats') {
        try {
            const { questSystemEnabled } = require('./config.json');
            if (!questSystemEnabled) return;
            
            const quest = await getCurrentQuest();
            if (!quest) {
                return message.reply("❌ لا توجد مهمة نشطة حالياً.");
            }
            
            const allProgress = await StaffQuestProgress.find().lean();
            const messagesCompleted = allProgress.filter(p => p.messagesCompleted).length;
            const ticketsCompleted = allProgress.filter(p => p.ticketsCompleted).length;
            const bothCompleted = allProgress.filter(p => p.messagesCompleted && p.ticketsCompleted).length;
            
            const avgMessages = allProgress.length > 0 ? 
                Math.round(allProgress.reduce((sum, p) => sum + p.messagesCount, 0) / allProgress.length) : 0;
            const avgTickets = allProgress.length > 0 ? 
                Math.round(allProgress.reduce((sum, p) => sum + p.ticketsCount, 0) / allProgress.length) : 0;
            
            const embed = new MessageEmbed()
                .setTitle("📊 إحصائيات المهام")
                .setColor(serverColor)
                .addFields(
                    { name: "🎫 المهمة النشطة", value: quest.description || "بدون وصف", inline: false },
                    { name: "👥 إجمالي المشاركين", value: `${allProgress.length}`, inline: true },
                    { name: "✉️ أكملوا الرسائل", value: `${messagesCompleted} (${allProgress.length > 0 ? Math.round(messagesCompleted/allProgress.length*100) : 0}%)`, inline: true },
                    { name: "🎫 أكملوا التذاكر", value: `${ticketsCompleted} (${allProgress.length > 0 ? Math.round(ticketsCompleted/allProgress.length*100) : 0}%)`, inline: true },
                    { name: "⭐ أكملوا الاثنين", value: `${bothCompleted} (${allProgress.length > 0 ? Math.round(bothCompleted/allProgress.length*100) : 0}%)`, inline: true },
                    { name: "📈 متوسط الرسائل", value: `${avgMessages}/${quest.requiredMessages}`, inline: true },
                    { name: "📈 متوسط التذاكر", value: `${avgTickets}/${quest.requiredTickets}`, inline: true }
                )
                .setFooter({ text: "البيانات مباشرة" })
                .setTimestamp();
            
            return message.reply({ embeds: [embed] });
        } catch (error) {
            console.error('Error showing stats:', error);
            return message.reply("❌ حدث خطأ أثناء عرض الإحصائيات.");
        }
    }
});

