client.on('interactionCreate', async (interaction) => {
    if (!interaction.isSelectMenu()) return;

    if (interaction.customId !== 'role_select') return;

    const member = interaction.member;
    const selectedValue = interaction.values[0];

    if (selectedValue === 'reset_menu') {
        await interaction.deferUpdate();
        client.emit('messageCreate', interaction.message);
        return;
    }

    if (selectedValue === 'select_all') {
        let addedRoles = [];
        for (const roleKey in roles) {
            const role = interaction.guild.roles.cache.get(roles[roleKey]);
            if (role && !member.roles.cache.has(role.id)) {
                await member.roles.add(role);
                addedRoles.push(role.name);
            }
        }
        if (addedRoles.length > 0) {
            return interaction.reply({ content: `✅ تم إضافة الرتب التالية: \`${addedRoles.join(', ')}\``, ephemeral: true });
        } else {
            return interaction.reply({ content: `❌ كل الرتب عندك بالفعل!`, ephemeral: true });
        }
    }

    if (selectedValue === 'remove_all') {
        let removedRoles = [];
        for (const roleKey in roles) {
            const role = interaction.guild.roles.cache.get(roles[roleKey]);
            if (role && member.roles.cache.has(role.id)) {
                await member.roles.remove(role);
                removedRoles.push(role.name);
            }
        }
        if (removedRoles.length > 0) {
            return interaction.reply({ content: `❌ تم إزالة الرتب التالية: \`${removedRoles.join(', ')}\``, ephemeral: true });
        } else {
            return interaction.reply({ content: `⚠️ لا توجد لديك أي من هذه الرتب!`, ephemeral: true });
        }
    }

    const roleId = roles[selectedValue];
    const role = interaction.guild.roles.cache.get(roleId);

    if (!role) {
        return interaction.reply({ content: '❌ اممم.. الرتبة دي مش موجودة؟ جرب تاني.', ephemeral: true });
    }

    let messages;
    if (member.roles.cache.has(roleId)) {
        await member.roles.remove(role);
        messages = [
            `👌 رتبة \`${role.name}\` اتشالت منك.`,
        ];
    } else {
        await member.roles.add(role);
        messages = [
            `✅ تمام، رتبة \`${role.name}\` بقت عندك! 😉`,
        ];
    }

    const randomMessage = messages[Math.floor(Math.random() * messages.length)];
    await interaction.reply({ content: randomMessage, ephemeral: true });
});

