function getHandsDisplay(game) {
    if (game.playerHands) {
        let handsDisplay = "";
        for (let i = 0; i < game.playerHands.length; i++) {
            const hand = game.playerHands[i];
            const handValue = calculateHandValue(hand);
            const displayValue = getHandDisplayValue(hand);
            
            let status = "";
            if (handValue > 21) {
                status = " - **تخطي**";
            } else {
                status = " - **انتهى**";
            }
            
            handsDisplay += `> ${hand.map(card => getCardEmoji(card)).join(' ')} (${displayValue})${status}\n`;
        }
        return handsDisplay;
    } else {
        return `> ${game.playerHand.map(card => getCardEmoji(card)).join(' ')} (${getHandDisplayValue(game.playerHand)})`;
    }
}

async function finishGameWithSplits(gameMessage, userId, game) {
    const botValue = calculateHandValue(game.botHand);
    let totalWinnings = 0;
    let totalLoss = 0;
    let handsResults = [];
    
    const playerHands = game.playerHands || [game.playerHand];
    const splitBets = game.splitBets || [game.betAmount];
    
    for (let i = 0; i < playerHands.length; i++) {
        const hand = playerHands[i];
        const bet = splitBets[i];
        const playerValue = calculateHandValue(hand);
        
        let result = "";
        let winAmount = 0;
        
        if (playerValue > 21) {
            result = "تخطي";
            totalLoss += bet;
        } else if (playerValue === 21 && hand.length === 2 && (!game.splitBets || game.splitBets.length === 1)) {
            result = "بلاك جاك";
            winAmount = Math.floor(bet * 1.5);
            totalWinnings += winAmount;
        } else if (botValue > 21) {
            result = "ربح (البوت تخطي)";
            winAmount = bet * 2;
            totalWinnings += winAmount;
        } else if (playerValue > botValue) {
            result = "ربح";
            winAmount = bet * 2;
            totalWinnings += winAmount;
        } else if (playerValue < botValue) {
            result = "خسارة";
            totalLoss += bet;
        } else {
            result = "تعادل";
            totalWinnings += bet;
        }
        
        handsResults.push({
            handIndex: i + 1,
            cards: hand.map(card => getCardEmoji(card)).join(' '),
            value: getHandDisplayValue(hand),
            result: result,
            bet: bet,
            winAmount: winAmount
        });
    }
    
    const netResult = totalWinnings;
    const originalBet = splitBets[0];
    const actualNetResult = totalWinnings - originalBet;
    
    const playerData = await db.findOne({ id: userId });
    playerData.coins += netResult;
    playerData.status_playing = "no";
    await playerData.save();
    
    if (actualNetResult > 0) {
        await updatePlayerWin(userId, originalBet, actualNetResult);
    } else if (actualNetResult < 0) {
        await updatePlayerLoss(userId, Math.abs(actualNetResult));
    } else {
        await updatePlayerDraw(userId);
    }
    
    let resultsText = "";
    for (const handResult of handsResults) {
        resultsText += `> ${handResult.cards} (${handResult.value}) - ${handResult.result}\n`;
    }
    
    let description = `**النتيجة النهائية:** ${actualNetResult > 0 ? `ربحت ${actualNetResult}` : actualNetResult < 0 ? `خسرت ${Math.abs(actualNetResult)}` : 'تعادل'} قولد`;
    
    const resultEmbed = new MessageEmbed()
        .setTitle("بلاك جاك ضد البوت")
        .setColor(actualNetResult > 0 ? "GREEN" : actualNetResult < 0 ? "RED" : "YELLOW")
        .setDescription(description)
        .addFields(
            { name: `النتائج`, value: resultsText },
            { name: `🤖 البوت`, value: `> ${game.botHand.map(card => getCardEmoji(card)).join(' ')} (${getHandDisplayValue(game.botHand)})` },
        );
    
    await gameMessage.edit({
        content: `<@${userId}> انتهت اللعبة!`,
        embeds: [resultEmbed],
        components: []
    });
    
    await blackjackbot.findOneAndDelete({ messageId: gameMessage.id });
    await provablyFairSystem.endProvablyFairSession(client, gameMessage.id);
}

