client.on("ready", async () => {
	setInterval(async () => {
		try {
			const guild = client.guilds.cache.get(bettingserverid);
			
			
			if (!guild) {
				console.error('Guild not found!');
				return;
			}
			
			const money = await db.find({}).sort({ coins: -1 }).select("id coins").limit(1).lean();
			const topMember = money[0];
			
			if (!topMember) {
				return;
			}
			
			if(topMember.id == "bot") {
				topMember.coins = 0;
				await topMember.save();
			} else {
				const topMoneyRole = guild.roles.cache.find(role => role.name === topmoneyrolename);
				if(!topMoneyRole) {
					console.error(`Role ${topmoneyrolename} not found.`);
					return;
				}
				guild.members.cache.forEach(member => {
					if(member.roles.cache.has(topMoneyRole.id) && member.id !== topMember.id) {
						member.roles.remove(topMoneyRole);
					}
				});
				const topMemberObject = guild.members.cache.get(topMember.id);
				if(topMemberObject) {
					topMemberObject.roles.add(topMoneyRole);
				} else {}
			}
			loadBlacklistedUsers();
			const blacklistPath = path.resolve(__dirname, 'blacklist.json');
			let blacklist = [];
			if(fs.existsSync(blacklistPath)) {
				blacklist = JSON.parse(fs.readFileSync(blacklistPath, 'utf8'));
			} else {
				console.error('Blacklist file not found.');
				return;
			}
			const blacklistRole = guild.roles.cache.find(role => role.name === blacklistrolename);
			if(!blacklistRole) {
				console.error(`Role ${blacklistrolename} not found.`);
				return;
			}
			guild.members.cache.forEach(async member => {
				if(blacklist.some(user => user.id === member.id)) {
					if(!member.roles.cache.has(blacklistRole.id)) {
						await member.roles.add(blacklistRole);
					}
				} else {
					if(member.roles.cache.has(blacklistRole.id)) {
						await member.roles.remove(blacklistRole);
					}
				}
			});
			loadpremiumedUsers();
			checkPremium();
			const premiumPath = path.resolve(__dirname, 'premium.json');
			let premium = [];
			if(fs.existsSync(premiumPath)) {
				premium = JSON.parse(fs.readFileSync(premiumPath, 'utf8'));
			} else {
				console.error('premium file not found.');
				return;
			}
			const premiumRole = guild.roles.cache.find(role => role.name === premiumrolename);
			if(!premiumRole) {
				console.error(`Role ${premiumrolename} not found.`);
				return;
			}
			guild.members.cache.forEach(async member => {
				if(premium.some(user => user.id === member.id)) {
					if(!member.roles.cache.has(premiumRole.id)) {
						await member.roles.add(premiumRole);
					}
				} else {
					if(member.roles.cache.has(premiumRole.id)) {
						await member.roles.remove(premiumRole);
					}
				}
			});
		} catch (err) {
			console.error(err);
		}
	}, 20000);
})

