client.on("messageCreate", async message => {
    if (message.channel.parentId === "1478722657661747220") return;
	if(message.author.bot || message.channel.id == GAME_CHANNEL_ID) return;
	if(!message.channel.guild) return;
	if(message.content.startsWith('say')) {
		if (!isOwnerOrGranted(message.author.id, 'say')) {
			return message.reply("** 😕 You don't have permissions **");
		}
		if(!message.guild.me.permissions.has('ADMINISTRATOR')) {
			return message.reply(`** 😕 I couldn't edit the channel permissions. Please check my permissions and role position. **`);
		}
		let args = message.content.split(' ').slice(2).join(' ')
		let argss = message.content.split(' ')
		let channel = message.mentions.channels.first() || message.guild.channels.cache.get(argss[1])
		let attach = message.attachments.first()
		if(!channel) return message.channel.send('** 😕 Please mention channel or id **');
		if(!args) return message.channel.send('** ❌ Please select a message **');
		message.delete()
		if(!attach) {
			channel.send({
				content: `${args}`
			});
		} else {
			channel.send({
				content: `${args}`,
				files: [attach]
			});
		}
	}
});
const blockedCategories = ["1378839847569068062"];

client.on("messageCreate", async (message) => {
    if (!betcateg.includes(message.channel.parentId)) return;
    if (blockedCategories.includes(message.channel.parentId)) return;
    if (!message.guild || message.author.bot) return;
    if (isBlacklisted(message.author.id)) return;

    let args = message.content.split(" ");
    if (!["تحويل", "transfer"].includes(args[0].toLowerCase())) return;
    
    if (args[0] === "تحويل" && args[1] === "متجر") return;
    const userId = message.author.id;
    
    if (cooldowns.has(userId)) {
        const lastUsed = cooldowns.get(userId);
        const cooldownAmount = 30 * 1000;
        if (Date.now() - lastUsed < cooldownAmount) {
            const remaining = (cooldownAmount - (Date.now() - lastUsed)) / 1000;
            return message.reply(`⏳ يرجى الانتظار ${Math.ceil(remaining)} ثانية قبل استخدام التحويل مرة أخرى!`);
        }
    }
    cooldowns.set(userId, Date.now());
    
    let senderData = await db.findOne({ id: message.author.id });
    if (!senderData) {
        senderData = await db.create({
            id: message.author.id,
            coins: 0,
            status_playing: "no",
            isontransfersure: "no",
            outcomingtransactions: 0
        });
    }

    const pendingWithdrawal = await S7b.findOne({ 
        user: userId,
        status: 'pending'
    });
    
    if (pendingWithdrawal) {
        return message.reply("❌ لديك طلب سحب قيد المعالجة. يرجى الانتظار.");
    }

    if (senderData.isontransfersure === "yes") {
        return message.reply("⚠️ لديك عملية تحويل قيد التأكيد. يرجى انتظار انتهاءها قبل بدء عملية جديدة.");
    }

    if (activeWithdrawals.has(message.author.id) || (isProcessing && currentWithdrawalUser === message.author.id) || senderData.isOnWithdrawal === "yes" || senderData.withdrawing === true) {
        return message.reply({ content: '**> لديك عملية سحب قيد الاختيار**' });
    }

    if (senderData.status_playing === "yes") {
        return message.reply("> لا يمكنك التحويل أثناء التحدي!");
    }
    

    
    if (activeBankOperations.has(userId)) {
        return message.reply("⚠️ لديك عملية بنك نشطة! لا يمكنك التحويل أثناء استخدام البنك.");
    }

    if (activeOperations.has(userId)) {
        return message.reply("⚠️ لديك عملية ترقية بريميوم قيد التنفيذ! لا يمكنك التحويل حالياً.");
    }

    if (!args[1]) return message.reply("> لم تقم بتحديد العضو!");
    let user = message.mentions.users.first() || message.guild.members.cache.get(args[1]);
    if (!user) return message.reply("❎ **لم أستطع العثور على هذا الشخص**");
    if (user.id === message.author.id) return message.reply("❎ لا يمكنك التحويل لنفسك!");

    
    if (user.id === client.user.id) {
        if (!args[2]) return message.reply("> لم تقم بتحديد المبلغ!");

        
        const fullInput = args.slice(2).join(" ").trim().toLowerCase();
        const wheelMatch = fullInput.match(/^(عجل[هة]\s+حظ)\s+(1m484|1048m)$/i);
        if (wheelMatch) {
            const tier = wheelMatch[2].toLowerCase();

            
            const WHEEL_CONFIG = {
                "130m": {
                    cost: 1_000_000,
                    displayCost: "1M",
                    prizes: [
                        { label: "حظاً أوفر 🍀", value: 0,           weight: 40 },
                        { label: "500K 💸",       value: 500_000,     weight: 28 },
                        { label: "2M 💰",         value: 2_000_000,   weight: 17 },
                        { label: "3M 💎",         value: 3_000_000,   weight: 9  },
                        { label: "5M 🌟",         value: 5_000_000,   weight: 4  },
                        { label: "10M 👑",        value: 10_000_000,  weight: 2  },
                    ]
                },
                "19390m": {
                    cost: 10_000_000,
                    displayCost: "10M",
                    prizes: [
                        { label: "1M 💸",  value: 1_000_000,  weight: 600 },
                        { label: "5M 💰",  value: 5_000_000,  weight: 280 },
                        { label: "10M 💎", value: 10_000_000, weight: 90  },
                        { label: "20M 🌟", value: 20_000_000, weight: 27  },
                        { label: "30M 👑", value: 30_000_000, weight: 3   },
                    ]
                }
            };

            const config = WHEEL_CONFIG[tier];

            
            if (senderData.coins < config.cost)
                return message.reply(`❎ ما عندك رصيد كافٍ! تحتاج **${config.cost.toLocaleString()}** كوين للعب.`);
            if (hiddenUsers.has(message.author.id))
                return message.reply('> ❌ **لا يمكنك اللعب وأنت مخفي!**\nاكتب `unhideme` أولاً.');
            if (senderData.isontransfersure === "yes")
                return message.reply("⚠️ لديك عملية تحويل قيد التأكيد.");
            if (senderData.status_playing === "yes")
                return message.reply("> لا يمكنك استخدام عجلة الحظ أثناء التحدي!");
            if (activeBankOperations.has(userId))
                return message.reply("⚠️ لديك عملية بنك نشطة!");

            
            
            if (!global.wheelSpinCount)    global.wheelSpinCount    = new Map();
            if (!global.wheelLastJackpot)  global.wheelLastJackpot  = new Map();
            const JACKPOT_MIN_SPINS = 10; 

            function pickPrize(prizes) {
                const spins       = global.wheelSpinCount.get(message.author.id)  || 0;
                const lastJackpot = global.wheelLastJackpot.get(message.author.id) || -999;
                const spinsSince  = spins - lastJackpot;

                
                
                let activePrizes;
                if (spinsSince < JACKPOT_MIN_SPINS) {
                    activePrizes = prizes.filter(p => p.value < 30_000_000);
                } else {
                    
                    const othersTotal = prizes
                        .filter(p => p.value < 30_000_000)
                        .reduce((s, p) => s + p.weight, 0);
                    
                    const jackpotWeight = Math.round(othersTotal * 5 / 95);
                    activePrizes = [
                        ...prizes.filter(p => p.value < 30_000_000),
                        { ...prizes.find(p => p.value === 30_000_000), weight: jackpotWeight }
                    ];
                }

                const total = activePrizes.reduce((s, p) => s + p.weight, 0);
                let rand = crypto.randomInt(0, total);
                for (const p of activePrizes) { rand -= p.weight; if (rand < 0) return p; }
                return activePrizes[activePrizes.length - 1];
            }

            
            async function buildWheelFrame(prizes, currentAngle, highlightIdx, isFinished) {
                const SIZE   = 660;
                const CX     = SIZE / 2;
                const CY     = SIZE / 2 + 20;
                const RADIUS = 245;
                const n      = prizes.length;
                const slice  = (Math.PI * 2) / n;
                const PALETTE = ["#c0392b","#16a085","#d35400","#1a5276","#7d3c98","#1f618d","#b7950b","#196f3d"];

                const canvas = Canvas.createCanvas(SIZE, SIZE);
                const ctx    = canvas.getContext("2d");

                
                const bgGrad = ctx.createRadialGradient(CX, CY, 60, CX, CY, SIZE * 0.72);
                bgGrad.addColorStop(0, "#1c1c3a");
                bgGrad.addColorStop(1, "#0a0a18");
                ctx.fillStyle = bgGrad;
                ctx.fillRect(0, 0, SIZE, SIZE);

                
                const starPositions = [
                    [45,30],[120,80],[200,15],[310,60],[450,25],[560,90],[600,40],[80,150],
                    [170,200],[380,120],[510,170],[620,130],[30,250],[140,300],[260,280],
                    [420,240],[580,260],[650,200],[90,380],[220,420],[350,370],[490,400],
                    [610,350],[20,480],[160,500],[300,460],[440,510],[570,480],[640,430]
                ];
                for (const [sx, sy] of starPositions) {
                    ctx.fillStyle = `rgba(255,255,255,${0.3 + (sx % 5) * 0.07})`;
                    ctx.beginPath();
                    ctx.arc(sx, sy, 0.8 + (sy % 4) * 0.35, 0, Math.PI * 2);
                    ctx.fill();
                }

                
                for (let t = 16; t >= 1; t--) {
                    ctx.beginPath();
                    ctx.arc(CX, CY, RADIUS + t, 0, Math.PI * 2);
                    ctx.strokeStyle = `rgba(255,215,0,${t * 0.038})`;
                    ctx.lineWidth = 1;
                    ctx.stroke();
                }
                ctx.beginPath();
                ctx.arc(CX, CY, RADIUS + 16, 0, Math.PI * 2);
                ctx.strokeStyle = "#ffd700";
                ctx.lineWidth = 5;
                ctx.stroke();

                
                for (let i = 0; i < n; i++) {
                    const sa    = currentAngle + i * slice;
                    const ea    = sa + slice;
                    const isWin = isFinished && (i === highlightIdx);

                    ctx.beginPath();
                    ctx.moveTo(CX, CY);
                    ctx.arc(CX, CY, RADIUS, sa, ea);
                    ctx.closePath();

                    if (isWin) {
                        const mid = sa + slice / 2;
                        const gx  = CX + Math.cos(mid) * RADIUS * 0.55;
                        const gy  = CY + Math.sin(mid) * RADIUS * 0.55;
                        const wg  = ctx.createRadialGradient(gx, gy, 0, gx, gy, RADIUS * 0.85);
                        wg.addColorStop(0, "#fffde7");
                        wg.addColorStop(1, "#f9a825");
                        ctx.fillStyle = wg;
                    } else {
                        ctx.fillStyle = PALETTE[i % PALETTE.length];
                    }
                    ctx.fill();
                    ctx.strokeStyle = "rgba(255,255,255,0.2)";
                    ctx.lineWidth   = 1.5;
                    ctx.stroke();
                }

                
                for (let i = 0; i < n; i++) {
                    const sa    = currentAngle + i * slice;
                    const mid   = sa + slice / 2;
                    const isWin = isFinished && (i === highlightIdx);
                    const textR = RADIUS * 0.67;

                    ctx.save();
                    ctx.translate(CX + Math.cos(mid) * textR, CY + Math.sin(mid) * textR);
                    ctx.rotate(mid + Math.PI / 2);
                    ctx.textAlign    = "center";
                    ctx.textBaseline = "middle";
                    ctx.font         = `bold ${n > 5 ? 15 : 17}px Arial`;
                    ctx.shadowColor  = "rgba(0,0,0,0.9)";
                    ctx.shadowBlur   = 5;
                    ctx.fillStyle    = isWin ? "#1a1a2e" : "#ffffff";
                    ctx.fillText(prizes[i].label, 0, 0);
                    ctx.restore();
                }

                
                for (let i = 0; i < n; i++) {
                    const angle = currentAngle + i * slice;
                    ctx.beginPath();
                    ctx.moveTo(CX, CY);
                    ctx.lineTo(CX + Math.cos(angle) * RADIUS, CY + Math.sin(angle) * RADIUS);
                    ctx.strokeStyle = "rgba(255,255,255,0.12)";
                    ctx.lineWidth   = 1;
                    ctx.stroke();
                }

                
                const cg = ctx.createRadialGradient(CX - 5, CY - 5, 2, CX, CY, 30);
                cg.addColorStop(0, "#fff9c4");
                cg.addColorStop(1, "#b8860b");
                ctx.beginPath();
                ctx.arc(CX, CY, 30, 0, Math.PI * 2);
                ctx.fillStyle   = cg;
                ctx.fill();
                ctx.strokeStyle = "#ffffff";
                ctx.lineWidth   = 3;
                ctx.stroke();

                
                
                const arrowBaseY = CY - RADIUS - 28; 
                const arrowTipY  = CY - RADIUS - 2;  
                ctx.save();
                ctx.shadowColor = "rgba(255,200,0,0.7)";
                ctx.shadowBlur  = 14;
                ctx.beginPath();
                ctx.moveTo(CX,       arrowTipY);           
                ctx.lineTo(CX - 18,  arrowBaseY);          
                ctx.lineTo(CX + 18,  arrowBaseY);          
                ctx.closePath();
                const ag = ctx.createLinearGradient(CX, arrowBaseY, CX, arrowTipY);
                ag.addColorStop(0, "#fff176");
                ag.addColorStop(1, "#ffa000");
                ctx.fillStyle   = ag;
                ctx.fill();
                ctx.strokeStyle = "#fff";
                ctx.lineWidth   = 2;
                ctx.stroke();
                ctx.restore();

                
                ctx.font         = "bold 27px Arial";
                ctx.textAlign    = "center";
                ctx.textBaseline = "top";
                ctx.shadowColor  = "rgba(0,0,0,0.95)";
                ctx.shadowBlur   = 10;
                ctx.fillStyle    = "#ffd700";
                ctx.fillText(`🎡 عجلة الحظ — ${config.displayCost}`, CX, 8);

                return canvas.toBuffer("image/png");
            }

            
            const confirmEmbed = new Discord.MessageEmbed()
                .setColor(serverColor)
                .setTitle("🎡 تأكيد عجلة الحظ")
                .setDescription(`هل أنت متأكد أنك تريد اللعب بعجلة الحظ **${config.displayCost}**؟`)
                .addFields(
                    { name: "التكلفة",   value: `> **${config.cost.toLocaleString()}** كوين` },
                    { name: "أعلى جائزة", value: `> **${config.prizes[config.prizes.length-1].label}**` }
                )
                .setFooter(message.guild.name)
                .setTimestamp();

            const confirmButtons = new Discord.MessageActionRow().addComponents(
                new Discord.MessageButton().setCustomId("wheel_confirm").setLabel("✅ تأكيد").setStyle("SUCCESS"),
                new Discord.MessageButton().setCustomId("wheel_cancel").setLabel("❌ إلغاء").setStyle("DANGER")
            );

            senderData.isontransfersure = "yes";
            await senderData.save();

            const confirmMsg = await message.channel.send({
                content: `${message.author}`,
                embeds: [confirmEmbed],
                components: [confirmButtons]
            });

            const wheelFilter    = i => i.user.id === message.author.id;
            const wheelCollector = confirmMsg.createMessageComponentCollector({ filter: wheelFilter, time: 15000, max: 1 });

            wheelCollector.on("collect", async (interaction) => {
                await interaction.deferUpdate();
                wheelCollector.stop();

                if (interaction.customId === "wheel_cancel") {
                    senderData.isontransfersure = "no";
                    await senderData.save();
                    return confirmMsg.edit({ content: "❌ تم إلغاء عجلة الحظ.", embeds: [], components: [] });
                }

                if (interaction.customId === "wheel_confirm") {
                    
                    const disabledRow = new Discord.MessageActionRow().addComponents(
                        new Discord.MessageButton().setCustomId("wheel_confirm").setLabel("✅ تأكيد").setStyle("SUCCESS").setDisabled(true),
                        new Discord.MessageButton().setCustomId("wheel_cancel").setLabel("❌ إلغاء").setStyle("DANGER").setDisabled(true)
                    );
                    await confirmMsg.edit({ content: "⏳ جارٍ تدوير العجلة...", embeds: [], components: [disabledRow] });

                    
                    const deducted = await db.findOneAndUpdate(
                        { id: message.author.id, coins: { $gte: config.cost }, isontransfersure: "yes" },
                        { $inc: { coins: -config.cost }, $set: { isontransfersure: "processing", isProcessingTransfer: true } },
                        { new: true }
                    );
                    if (!deducted) {
                        senderData.isontransfersure = "no";
                        await senderData.save();
                        return confirmMsg.edit({ content: "❌ فشل الخصم. تحقق من رصيدك.", embeds: [], components: [] });
                    }

                    
                    const won    = pickPrize(config.prizes);
                    const wonIdx = config.prizes.indexOf(won);

                    
                    const currentSpins = (global.wheelSpinCount.get(message.author.id) || 0) + 1;
                    global.wheelSpinCount.set(message.author.id, currentSpins);
                    if (won.value === 30_000_000) {
                        global.wheelLastJackpot.set(message.author.id, currentSpins);
                    }
                    const n      = config.prizes.length;
                    const slice  = (Math.PI * 2) / n;

                    
                    
                    const finalAngle = -Math.PI / 2 - wonIdx * slice - slice / 2;
                    
                    const totalSpin  = Math.PI * 2 * 8 + finalAngle;

                    
                    const FRAME_COUNT = 18;
                    const frames = [];
                    for (let f = 0; f < FRAME_COUNT; f++) {
                        const t = f / (FRAME_COUNT - 1);
                        
                        const eased = t < 0.5
                            ? 4 * t * t * t
                            : 1 - Math.pow(-2 * t + 2, 3) / 2;
                        frames.push(totalSpin * eased);
                    }

                    
                    const firstFrameBuf = await buildWheelFrame(config.prizes, frames[0], wonIdx, false);
                    const firstAttach   = new Discord.MessageAttachment(firstFrameBuf, "wheel.png");
                    const spinEmbed     = new Discord.MessageEmbed()
                        .setColor("#f39c12")
                        .setTitle("🎡 عجلة الحظ تدور...")
                        .setImage("attachment://wheel.png")
                        .setFooter(message.guild.name);

                    const spinMsg = await message.channel.send({ embeds: [spinEmbed], files: [firstAttach] });

                    
                    const delays = [120, 130, 140, 155, 170, 190, 210, 235, 260, 285, 310, 340, 370, 400, 430, 460, 500, 550];
                    for (let f = 1; f < FRAME_COUNT; f++) {
                        await new Promise(res => setTimeout(res, delays[f] || 400));
                        const isLast   = (f === FRAME_COUNT - 1);
                        const frameBuf = await buildWheelFrame(config.prizes, frames[f], wonIdx, isLast);
                        const attach   = new Discord.MessageAttachment(frameBuf, "wheel.png");
                        const fEmbed   = new Discord.MessageEmbed()
                            .setColor(isLast ? (won.value > 0 ? "#ffd700" : "#e74c3c") : "#f39c12")
                            .setTitle(isLast ? "🎡 توقفت العجلة!" : "🎡 عجلة الحظ تدور...")
                            .setImage("attachment://wheel.png")
                            .setFooter(message.guild.name);
                        await spinMsg.edit({ embeds: [fEmbed], files: [attach] }).catch(() => {});
                    }

                    
                    if (won.value > 0) {
                        await db.updateOne({ id: message.author.id }, { $inc: { coins: won.value } });
                    }
                    await db.updateOne({ id: message.author.id }, { $set: { isontransfersure: "no", isProcessingTransfer: false } });
                    invalidateUserCache(message.author.id);

                    
                    const resultLine = won.value > 0
                        ? `🎉 **مبروك ${message.author}!** ربحت **${won.value.toLocaleString()}** كوين!`
                        : `😔 **حظاً أوفر ${message.author}!** المرة القادمة إن شاء الله 🍀`;

                    const resultEmbed = new Discord.MessageEmbed()
                        .setColor(won.value > 0 ? "#ffd700" : "#e74c3c")
                        .setTitle("🎡 نتيجة عجلة الحظ")
                        .setDescription(`🎯 **${won.label}**\n\n${resultLine}`)
                        .addFields(
                            { name: "دفعت",   value: `> ${config.cost.toLocaleString()} كوين` },
                            { name: "ربحت",   value: `> ${won.value.toLocaleString()} كوين`   }
                        )
                        .setFooter(message.guild.name)
                        .setTimestamp();

                    await message.channel.send({ content: `${message.author}`, embeds: [resultEmbed] });
                }
            });

            wheelCollector.on("end", async (_, reason) => {
                if (reason === "time") {
                    await db.updateOne(
                        { id: message.author.id, isontransfersure: "yes" },
                        { $set: { isontransfersure: "no", isProcessingTransfer: false } }
                    );
                    await confirmMsg.edit({ content: "⌛ **انتهى الوقت! تم إلغاء عجلة الحظ.**", embeds: [], components: [] }).catch(() => {});
                }
            });

            return;
        }
        

        return message.reply("❌ تم حذف نظام شحن الرصيد.");
    }

    if (user.bot) return message.reply("❎ لا يمكنك التحويل للبوتات!");

    let receiverData = await db.findOne({ id: user.id });
    if (!receiverData) {
        receiverData = await db.create({
            id: user.id,
            coins: 0,
            status_playing: "no",
            incomingtransactions: 0
        });
    }

    if (receiverData.status_playing === "yes") {
        return message.reply("> لا يمكنك التحويل لهذا الشخص أثناء التحدي!");
    }
    

    
    
    if (activeWithdrawals.has(user.id) || (isProcessing && currentWithdrawalUser === user.id)) {
        return message.reply({ content: '**> الشخص المستقبل لديه عملية سحب قيد الاختيار**' });
    }
    
    if (receiverData.isOnWithdrawal === "yes" || receiverData.withdrawing === true) {
        return message.reply({ content: '**> الشخص المستقبل لديه عملية سحب قيد الاختيار**' });
    }
    
    
    if (activeLinkOperations.has(user.id)) {
        return message.reply({ content: '**> الشخص المستقبل لديه عملية سحب أو إيداع قيد الاختيار**' });
    }

    if (!args[2]) return message.reply("> لم تقم بتحديد المبلغ!");
    let coinAmount = args[2].toLowerCase();

    let coinAmountInt;

    if (coinAmount === "فكه" || coinAmount === "فكة") {
        const balance = parseInt(senderData.coins || 0);
        if (balance <= 0) return message.reply("❎ **رصيدك صفر! ما عندك فكه 😅**");

        const magnitude = Math.pow(10, Math.floor(Math.log10(balance)));
        const roundedDown = Math.floor(balance / magnitude) * magnitude;
        coinAmountInt = balance - roundedDown;

        if (coinAmountInt <= 0) {
            return message.reply(`> ❌ **رصيدك \`${balance.toLocaleString()}\` رقم نظيف — ما عندك فكه!**`);
        }
    } else {
        if (coinAmount.includes("-")) return message.reply("❎ لا يمكنك التحويل بمبلغ سلبي!");
        if (coinAmount.includes(".") || coinAmount.includes(",")) return message.reply("❎ لا يمكنك استخدام أرقام عشرية!");

        coinAmount = coinAmount.replace("k", "000").replace("m", "000000");
        if (isNaN(coinAmount)) return message.reply("❎ برجاء وضع أرقام صحيحة!");

        coinAmountInt = parseInt(coinAmount);
        if (coinAmountInt <= 0) return message.reply("❎ يجب أن يكون المبلغ أكبر من صفر!");
    }

    if (senderData.coins < coinAmountInt) {
        return message.reply("❎ ليس لديك أموال كافية لهذا التحويل!");
    }

    
    if (hiddenUsers.has(message.author.id)) {
        return message.reply('> ❌ **لا يمكنك التحويل وأنت مخفي!**\nاكتب `unhideme` أولاً لإظهار رصيدك.');
    }
    if (hiddenUsers.has(user.id)) {
        return message.reply('> ❌ **لا يمكنك التحويل لهذا الشخص لأن رصيده مخفي.**');
    }

    let embedConfirm = new Discord.MessageEmbed()
        .setColor(serverColor)
        .setThumbnail(user.displayAvatarURL({ dynamic: true }))
        .setTitle("تأكيد عملية التحويل")
        .setDescription("هل أنت متأكد أنك تريد تحويل الأموال لهذا الشخص؟")
        .addFields(
            { name: 'المبلغ', value: `> ${coinAmountInt.toLocaleString()}` },
            { name: 'المستلم', value: `> ${user} (${user.tag})` },
            { name: 'ايدي المستلم', value: `> ${user.id}` }
        )
        .setFooter(message.guild.name)
        .setTimestamp();

    let buttons = new Discord.MessageActionRow().addComponents(
        new Discord.MessageButton()
            .setCustomId("confirm_transfer")
            .setLabel("✅ تأكيد")
            .setStyle("SUCCESS"),
        new Discord.MessageButton()
            .setCustomId("cancel_transfer")
            .setLabel("❌ إلغاء")
            .setStyle("DANGER")
    );

    senderData.isontransfersure = "yes";
    await senderData.save();

    let confirmMessage = await message.channel.send({ embeds: [embedConfirm], components: [buttons], content: `${message.author}` });

    const filter = (interaction) => interaction.user.id === message.author.id;
    const collector = confirmMessage.createMessageComponentCollector({ 
        filter, 
        time: 7000,
        max: 1 
    });

    collector.on("collect", async (interaction) => {
        await interaction.deferUpdate();
        const currentCheck = await db.findOne({ id: message.author.id });
        if (currentCheck.isProcessingTransfer) {
            return collector.stop();
        }
        if (currentCheck.status_playing === "yes") {
            senderData.isontransfersure = "no";
            await senderData.save();
            collector.stop();
            return confirmMessage.edit({ content: "❌ تم إلغاء التحويل لأنك داخل في تحدي!", embeds: [], components: [] }).catch(() => {});
        }

        if (interaction.customId === "cancel_transfer") {
            await confirmMessage.edit({ content: "❌ تم إلغاء عملية التحويل.", embeds: [], components: [] });
            senderData.isontransfersure = "no";
            await senderData.save();
            return collector.stop();
        }

        if (interaction.customId === "confirm_transfer") {
            collector.stop();
            let disabledButtons = new Discord.MessageActionRow().addComponents(
                new Discord.MessageButton()
                    .setCustomId("confirm_transfer")
                    .setLabel("✅ تأكيد")
                    .setStyle("SUCCESS")
                    .setDisabled(true),
                new Discord.MessageButton()
                    .setCustomId("cancel_transfer")
                    .setLabel("❌ إلغاء")
                    .setStyle("DANGER")
                    .setDisabled(true)
            );
            
            await confirmMessage.edit({ 
                content: "✅ تم تأكيد التحويل، جارٍ التحويل...", 
                embeds: [embedConfirm], 
                components: [disabledButtons] 
            }).catch(() => {});
            
            const updatedSender = await db.findOneAndUpdate(
                { 
                    id: message.author.id, 
                    coins: { $gte: coinAmountInt },
                    isProcessingTransfer: { $ne: true },
                    isontransfersure: "yes"
                },
                { 
                    $inc: { coins: -coinAmountInt },
                    $set: { 
                        isProcessingTransfer: true,
                        isontransfersure: "processing"
                    }
                },
                { new: true }
            );
            
            if (!updatedSender) {
                await db.updateOne(
                    { id: message.author.id },
                    { $set: { isontransfersure: "no", isProcessingTransfer: false } }
                );
                return confirmMessage.edit({ 
                    content: "❌ لا يمكن إتمام التحويل. إما أن رصيدك غير كافٍ أو أن هناك عملية تحويل أخرى قيد التنفيذ.", 
                    embeds: [], 
                    components: [] 
                }).catch(() => {});
            }
            
            setTimeout(async () => {
                try {
                    const currentSenderData = await db.findOne({ id: userId });
                    
                    if (!currentSenderData || currentSenderData.isontransfersure !== "processing") {
                        console.log(`Transfer cancelled or already processed for user ${userId}`);
                        return;
                    }

                  
                    if (currentSenderData.status_playing === "yes") {
                        await db.updateOne(
                            { id: userId, isontransfersure: "processing" },
                            { 
                                $inc: { coins: coinAmountInt },
                                $set: { 
                                    isontransfersure: "no",
                                    isProcessingTransfer: false
                                }
                            }
                        );
                        
                        return confirmMessage.edit({
                            content: "❌ تم إلغاء التحويل لأنك دخلت في تحدي. تم استرجاع أموالك.",
                            embeds: [],
                            components: []
                        }).catch(() => {});
                    }
                    
                    const transferCompleted = await db.findOneAndUpdate(
                        { 
                            id: userId, 
                            isontransfersure: "processing"
                        },
                        { 
                            $inc: { outcomingtransactions: coinAmountInt },
                            $set: { 
                                isontransfersure: "completed",
                                isProcessingTransfer: false
                            }
                        },
                        { new: true }
                    );
                    
                    if (!transferCompleted) {
                        console.log(`Transfer already cancelled for user ${userId}`);
                        return;
                    }
                    
                    await db.updateOne(
                        { id: user.id },
                        { 
                            $inc: { 
                                coins: coinAmountInt,
                                incomingtransactions: coinAmountInt
                            }
                        }
                    );
                    
                    await db.updateOne(
                        { id: userId },
                        { $set: { isontransfersure: "no" } }
                    );
                    
                    let embedSuccess = new Discord.MessageEmbed()
                        .setColor(serverColor)
                        .setThumbnail(user.displayAvatarURL({ dynamic: true }))
                        .setDescription("**تم التحويل بنجاح!**")
                        .addFields(
                            { name: 'المبلغ', value: `> ${coinAmountInt.toLocaleString()}` },
                            { name: 'المستلم', value: `> ${user}` }
                        )
                        .setFooter(message.guild.name)
                        .setTimestamp();
                    
                    confirmMessage.edit({ 
                        embeds: [embedSuccess], 
                        content: `${message.author}`, 
                        components: [] 
                    }).catch(() => {});
                    
                    const targetChannel = client.channels.cache.get(logPlayerTransferChannelId);
                    if (targetChannel) {
                        await targetChannel.send({ 
                            embeds: [embedSuccess], 
                            content: `> <@!${message.author.id}> | <@!${user.id}>\n<#${message.channel.id}> | https://discord.com/channels/${message.guild.id}/${message.channel.id}/${message.id}` 
                        }).catch(() => {});
                    }
                } catch (error) {
                    console.error("Transfer completion error:", error);
                    
                    const refundResult = await db.findOneAndUpdate(
                        { 
                            id: userId,
                            isontransfersure: "processing"
                        },
                        { 
                            $inc: { coins: coinAmountInt },
                            $set: { 
                                isontransfersure: "no",
                                isProcessingTransfer: false
                            }
                        }
                    );
                    
                    if (refundResult) {
                        await confirmMessage.edit({ 
                            content: "❌ حدث خطأ أثناء إكمال التحويل. تم استرجاع أموالك.", 
                            embeds: [], 
                            components: [] 
                        }).catch(() => {});
                    }
                }
            }, 7000);
            
            return collector.stop();
        }
    });

    collector.on("end", async (_, reason) => {
        if (reason === "time") {
            const refundResult = await db.findOneAndUpdate(
                { 
                    id: message.author.id,
                    isontransfersure: "yes"
                },
                { 
                    $set: { 
                        isontransfersure: "no", 
                        isProcessingTransfer: false 
                    }
                }
            );
            
            await confirmMessage.edit({ 
                content: "⌛ **انتهى الوقت! لم يتم تنفيذ عملية التحويل.**", 
                embeds: [], 
                components: [] 
            }).catch(() => {});
        }
    });
});

client.on("messageCreate", async (message) => {
    if (message.channel.parentId === "1478722657661747220") return;
    if (!message.guild || message.author.bot) return;

    let args = message.content.split(" ");
    if (args[0].toLowerCase() !== "rst") return;

   if (!isOwnerOrGranted(message.author.id, 'rst')) {
        return message.reply("❌ **ليس لديك الصلاحيات لاستخدام هذا الأمر!**");
    }

    if (!args[1]) return message.reply("> **يجب عليك تحديد الشخص لإعادة ضبط حالته!**");

    let user = message.mentions.users.first() || message.guild.members.cache.get(args[1]);
    if (!user) return message.reply("❎ **لم أتمكن من العثور على هذا الشخص!**");

    let userData = await db.findOne({ id: user.id });
    if (!userData) return message.reply("❎ **هذا الشخص ليس لديه بيانات في النظام!**");

    if (userData.isontransfersure === "no") {
        return message.reply("ℹ️ **هذا الشخص لم يكن لديه تحويل معلق بالفعل!**");
    }

    userData.isontransfersure = "no";
    await userData.save();

    message.reply(`✅ **تم إعادة ضبط حالة التحويل لـ ${user} بنجاح!**`);
});
