client.on("messageCreate", async message => {
    if (message.channel.parentId === "1478722657661747220") return;
    if (message.channel.id == GAME_CHANNEL_ID) return;
    if (isBlacklisted(message.author.id)) return;
    
    if (message.content.split(" ")[0] == "balance" || message.content.split(" ")[0] == "فلوس" || message.content.split(" ")[0] == "Money" || message.content.split(" ")[0] == "money") {
        
        
        const requesterId = message.author.id;
        const cooldownKey = `money_${requesterId}`;
        if (userCache.get(cooldownKey)) {
            return message.reply('⏳ انتظر ثانية واحدة!');
        }
        userCache.set(cooldownKey, true);
        setTimeout(() => userCache.delete(cooldownKey), 1000);

        let user = message.mentions.users.first() || message.author;
        
        
        let data = await getCachedMoneyData(user.id, db);
        
        if (!data) {
            data = await db.create({
                id: user.id,
                coins: 0,
                status_playing: "no"
            });
            
            userMoneyCache.set(user.id, {
                data: data,
                expires: Date.now() + USER_MONEY_TTL
            });
        }

        const isHidden = hiddenUsers.has(user.id);
        const isOwner = isOwnerOrGranted(message.author.id, '!stat');
        const isSelfCheck = user.id === message.author.id;
        
        
        let isUserLinked = false;
        let linkedPartnersData = []; 
        
        if (isSelfCheck) {
            try {
                const allPartnerIds = await getLinkedPartners(user.id);
                isUserLinked = allPartnerIds.length > 0;
                
                if (isUserLinked) {
                    for (const pid of allPartnerIds) {
                        try {
                            const pData = await getCachedMoneyData(pid, db);
                            const pUser = await client.users.fetch(pid);
                            if (pData && pUser) {
                                linkedPartnersData.push({ user: pUser, data: pData });
                            }
                        } catch (e) {}
                    }
                }
            } catch (e) {
                console.error('Error checking link status:', e);
                isUserLinked = false;
                linkedPartnersData = [];
            }
        }

        
        const sendBalanceLog = async () => {
            try {
                const logChannel = client.channels.cache.get(logBalanceCheckChannelId);
                if (logChannel) {
                    const hiddenIndicator = isHidden ? " 🔒" : "";
                    
                    const logEmbed = new Discord.MessageEmbed()
                        .setColor(serverColor)
                        .setThumbnail(user.avatarURL({ dynamic: true }))
                        .setTitle(`رصيد ${user.username}${hiddenIndicator}`)
                        .setDescription(
                            isSelfCheck 
                                ? `**الرصيد الحالي:** \`${parseInt(data.coins).toLocaleString()}\`` 
                                : `**رصيد ${user.username}:** \`${parseInt(data.coins).toLocaleString()}\``
                        )
                        .setFooter({ 
                            text: `طلب بواسطة ${message.author.username}`, 
                            iconURL: message.author.avatarURL({ dynamic: true }) 
                        })
                        .setTimestamp();
                    
                    logEmbed.addField(
                        "📋 Command Info", 
                        `**Requester:** ${message.author.tag} (${message.author.id})\n**Target:** ${user.tag} (${user.id})\n**Channel:** <#${message.channel.id}>\n**Self Check:** ${isSelfCheck ? "Yes" : "No"}`, 
                        false
                    );
                    
                    await logChannel.send({ embeds: [logEmbed] });
                }
            } catch (error) {
                console.error("Error sending balance log:", error);
            }
        };

        if (isHidden && isSelfCheck) {
            
            const embed = new Discord.MessageEmbed()
                .setColor(serverColor)
                .setThumbnail(user.avatarURL({ dynamic: true }))
                .setTitle(`رصيد ${user.username}`)
                .setDescription(`**الرصيد الحالي:** \`0\``)
                .setFooter({ text: `طلب بواسطة ${message.author.username}`, iconURL: message.author.avatarURL({ dynamic: true }) })
                .setTimestamp();
            await message.reply({ embeds: [embed] });
            sendBalanceLog();
            return;
        }

        if (isHidden && !isOwner && !isSelfCheck) {
            
            const embed = new Discord.MessageEmbed()
                .setColor(serverColor)
                .setThumbnail(user.avatarURL({ dynamic: true }))
                .setTitle(`رصيد ${user.username}`)
                .setDescription(`**رصيد ${user.username}:** \`0\``)
                .setFooter({ text: `طلب بواسطة ${message.author.username}`, iconURL: message.author.avatarURL({ dynamic: true }) })
                .setTimestamp();
            await message.reply({ embeds: [embed] });
            sendBalanceLog();
            return;
        }

        
        if (isUserLinked && linkedPartnersData.length > 0) {
            
            if (linkedPartnersData.length >= 2) {
                const currentIndex = 0;
                const currentPartner = linkedPartnersData[currentIndex];
                const total = linkedPartnersData.length;

                
                const prevDisabled = currentIndex === 0;
                const nextDisabled = currentIndex === total - 1;

                let embed = new Discord.MessageEmbed()
                    .setColor('#FFD700')
                    .setThumbnail(user.avatarURL({ dynamic: true }))
                    .setTitle(`الرصيد الحالي لـ ${user.username}`)
                    .addField(`💰 رصيدك`, `${parseInt(data.coins).toLocaleString()} كوين`, false)
                    .addField(`💳 ${currentPartner.user.username} (${currentIndex + 1}/${total})`, `${parseInt(currentPartner.data.coins).toLocaleString()} كوين`, false)
                    .setFooter({ 
                        text: `# Vip Casino | استخدم الأزرار لعرض باقي الأشخاص المرتبطين`, 
                        iconURL: message.author.avatarURL({ dynamic: true }) 
                    })
                    .setTimestamp();

                const row = new Discord.MessageActionRow().addComponents(
                    new Discord.MessageButton()
                        .setCustomId(`money_prev_${user.id}_0_${Date.now()}`)
                        .setLabel('⬅️')
                        .setStyle('PRIMARY')
                        .setDisabled(prevDisabled),
                    new Discord.MessageButton()
                        .setCustomId(`money_next_${user.id}_0_${Date.now()}`)
                        .setLabel('➡️')
                        .setStyle('PRIMARY')
                        .setDisabled(nextDisabled)
                );

                const sentMsg = await message.reply({ embeds: [embed], components: [row] });

                moneyPaginationCache.set(sentMsg.id, {
                    userId: user.id,
                    partners: linkedPartnersData,
                    currentIndex: 0,
                    userCoins: data.coins,
                    userAvatar: user.avatarURL({ dynamic: true }),
                    userName: user.username,
                    requesterAvatar: message.author.avatarURL({ dynamic: true }),
                    expires: Date.now() + 120000
                });

                sendBalanceLog();
                return;
            }

            
            let embed = new Discord.MessageEmbed()
                .setColor('#FFD700')
                .setThumbnail(user.avatarURL({ dynamic: true }))
                .setTitle(`الرصيد الحالي لـ ${user.username}`)
                .addField(`💰 ${user.username}`, `${parseInt(data.coins).toLocaleString()} كوين`, false);

            for (const p of linkedPartnersData) {
                embed.addField(`💳 ${p.user.username}`, `${parseInt(p.data.coins).toLocaleString()} كوين`, false);
            }

            embed.setFooter({ 
                text: `# Vip Casino. | ${new Date().toLocaleString('ar-EG', { 
                    year: 'numeric', 
                    month: '2-digit', 
                    day: '2-digit',
                    hour: '2-digit',
                    minute: '2-digit',
                    second: '2-digit',
                    hour12: false
                })}`, 
                iconURL: message.author.avatarURL({ dynamic: true }) 
            })
            .setTimestamp();

            await message.reply({ embeds: [embed] });
            sendBalanceLog();
            return;
        }

        
        let embed = new Discord.MessageEmbed()
            .setColor(serverColor)
            .setThumbnail(user.avatarURL({ dynamic: true }))
            .setTitle(`رصيد ${user.username}`)
            .setDescription(`**الرصيد الحالي:** \`${parseInt(data.coins).toLocaleString()}\``)
            .setFooter({ 
                text: `طلب بواسطة ${message.author.username}`, 
                iconURL: message.author.avatarURL({ dynamic: true }) 
            })
            .setTimestamp();

        if (user.id !== message.author.id) {
            embed.setDescription(`**رصيد ${user.username}:** \`${parseInt(data.coins).toLocaleString()}\``);
        }

        await message.reply({ embeds: [embed] });
        sendBalanceLog();
    }
});

