const rolepremiumid = '1505176499836424305'; 
const repsPath = path.join(__dirname, 'reps.json'); 

if (!fs.existsSync(repsPath)) {
    fs.writeFileSync(repsPath, JSON.stringify({}));
}

client.on('messageCreate', async (message) => {
    if (message.channel.parentId === "1478722657661747220") return;
    if (message.content.startsWith('ريب')) {
        if (message.author.bot) return;
        if (isBlacklisted(message.author.id)) return;

        const args = message.content.split(' ');
        const targetUser = message.mentions.users.first();

        if (!message.member.roles.cache.has(rolepremiumid)) {
            return message.reply('**> هذا الأمر خاص فقط بالأشخاص ذوي رتبة بريميوم.**');
        }

        if (!targetUser) {
            return message.reply('**> يجب الإشارة إلى المستخدم الذي تريد منحه ريب.**');
        }
        
        if (targetUser.id === message.author.id) {
            return message.reply('**> لا يمكنك منح ريب لنفسك!**');
        }

        let repsData = JSON.parse(fs.readFileSync(repsPath, 'utf8'));

        if (!repsData[message.author.id]) {
            repsData[message.author.id] = { lastRep: 0 };
        }

        const now = Date.now();
        const lastRepTime = repsData[message.author.id].lastRep || 0;
        const diff = now - lastRepTime;

        if (diff < 24 * 60 * 60 * 1000) {
            const hoursLeft = Math.ceil((24 * 60 * 60 * 1000 - diff) / (60 * 60 * 1000));
            return message.reply(`**> لا يمكنك منح ريب الآن. الرجاء الانتظار ${hoursLeft} ساعة.**`);
        }

        let targetData = await db.findOne({ id: targetUser.id });
        if (!targetData) {
            targetData = new User({
                id: targetUser.id,
                coins: 0,
                reps: 1, 
            });
            await targetData.save();
            return message.reply(`**> تم تسجيل المستخدم <@${targetUser.id}> في النظام ومنحه أول ريب! 🎉**`);
        }

        targetData.reps += 1;
        await targetData.save();

        repsData[message.author.id].lastRep = now;
        fs.writeFileSync(repsPath, JSON.stringify(repsData, null, 4));

        return message.reply(`**> تم منح ريب للمستخدم <@${targetUser.id}>! 🎉**`);
    }
});

const cooldowns15 = new Map(); 

client.on('messageCreate', async (message) => {
    
    if (message.channel.parentId === "1478722657661747220") return;
    
    
    if (message.content.startsWith('اقتراح')) {
        const userId = message.author.id;
        
        
        if (typeof isBlacklisted === 'function' && isBlacklisted(userId)) return;
        
        
        const suggestionText = message.content.slice(7).trim();

        
        if (!suggestionText) {
            return message.reply('⚠️ الرجاء كتابة اقتراح بعد كلمة "اقتراح".');
        }

        
        const now = Date.now();
        const cooldownAmount = 10 * 60 * 1000; 

        
        if (typeof cooldowns15 !== 'undefined' && cooldowns15.has(userId)) {
            const expirationTime = cooldowns15.get(userId) + cooldownAmount;
            if (now < expirationTime) {
                const timeLeft = Math.ceil((expirationTime - now) / 1000);
                return message.reply(
                    `⏳ يمكنك إرسال اقتراح آخر بعد **${Math.floor(timeLeft / 60)} دقيقة و ${timeLeft % 60} ثانية**.`
                );
            }
        }

        
        if (typeof cooldowns15 !== 'undefined') {
            cooldowns15.set(userId, now);
            setTimeout(() => cooldowns15.delete(userId), cooldownAmount);
        }

        
        message.react('✅');
        
        
        const suggestionChannelId = '1504204169991426341';
        const suggestionChannel = message.guild.channels.cache.get(suggestionChannelId);

        if (!suggestionChannel) {
            return message.reply('⚠️ لم يتم العثور على قناة الاقتراحات.');
        }

        
        const suggestionEmbed = new MessageEmbed()
            .setColor(typeof serverColor !== 'undefined' ? serverColor : '#0099ff')
            .setTitle('📢 اقتراح جديد')
            .setDescription(suggestionText)
            .addField('👤 المرسل', `<@${message.author.id}>`, true)
            .addField('📅 التاريخ', `<t:${Math.floor(Date.now() / 1000)}:F>`, true)
            .setFooter({ text: 'يرجى الضغط على قبول أو رفض من قبل الإدارة.' });

        
        const buttons = new MessageActionRow().addComponents(
            new MessageButton()
                .setCustomId('accept_suggestion')
                .setLabel('✅ قبول')
                .setStyle('SUCCESS'),
            new MessageButton()
                .setCustomId('reject_suggestion')
                .setLabel('❌ رفض')
                .setStyle('DANGER')
        );

        
        await suggestionChannel.send({
            embeds: [suggestionEmbed],
            components: [buttons],
        });
    }
});

client.on('interactionCreate', async (interaction) => {
    
    if (!interaction.isButton()) return;

    const { customId, user: interactionUser } = interaction;

    
    if (['accept_suggestion', 'reject_suggestion'].includes(customId)) {
        
        
        if (typeof owners !== 'undefined' && !owners.includes(interactionUser.id)) {
            return interaction.reply({
                content: '❌ هذا الزر مخصص للملاك فقط.',
                ephemeral: true,
            });
        }

        const message = interaction.message;
        const embed = message.embeds[0]; 

        if (customId === 'accept_suggestion') {
            const acceptEmbed = new MessageEmbed()
                .setColor(typeof serverColor !== 'undefined' ? serverColor : '#00ff00')
                .setTitle('✅ تم قبول الاقتراح')
                .setDescription(embed.description)
                .setFooter({ text: 'شكراً لمساهمتك في تطوير السيرفر!' });

            await message.edit({ embeds: [acceptEmbed], components: [] });
            await interaction.reply({ content: '✅ تم قبول الاقتراح بنجاح.', ephemeral: true });

            try {
                const userIdField = embed.fields.find((field) => field.name === '👤 المرسل');
                if (userIdField) {
                    const userId = userIdField.value.match(/\d+/)[0];
                    const targetUser = await interaction.client.users.fetch(userId);
                    if (targetUser) {
                        await targetUser.send({ embeds: [acceptEmbed] }).catch(() => null);
                    }
                }
            } catch (error) {
                console.error('خطأ في إرسال رسالة للمستخدم:', error);
            }
        } else if (customId === 'reject_suggestion') {
            const rejectEmbed = new MessageEmbed()
                .setColor(typeof serverColor !== 'undefined' ? serverColor : '#ff0000')
                .setTitle('❌ تم رفض الاقتراح')
                .setDescription(embed.description)
                .setFooter({ text: 'شكراً لمساهمتك، يمكنك التواصل مع الإدارة لمزيد من التفاصيل.' });

            await message.edit({ embeds: [rejectEmbed], components: [] });
            await interaction.reply({ content: '❌ تم رفض الاقتراح بنجاح.', ephemeral: true });

            try {
                const userIdField = embed.fields.find((field) => field.name === '👤 المرسل');
                if (userIdField) {
                    const userId = userIdField.value.match(/\d+/)[0];
                    const targetUser = await interaction.client.users.fetch(userId);
                    if (targetUser) {
                        await targetUser.send({ embeds: [rejectEmbed] }).catch(() => null);
                    }
                }
            } catch (error) {
                console.error('خطأ في إرسال رسالة للمستخدم:', error);
            }
        }
    }
});

    

client.on("messageCreate", async (message) => {
    
    if (message.channel.parentId === "1478722657661747220") return;

    
    if (message.content === "معلومات") {
        const premiumId = '1505176499836424305';
        const userId = message.author.id;

        
        if (typeof isBlacklisted === 'function' && isBlacklisted(userId)) return;

        
        if (!message.member.roles.cache.has(premiumId)) {
            return message.reply('**> هذا الامر للاشخاص ذوي رتبة بريميوم فقط للشراء اكتب بري أو بريميوم.**');
        }

        try {
            let user = message.author;
            
            let data = await db.findOne({ id: user.id });

            
            if (!data) {
                data = await db.create({ id: user.id, coins: 0, status_playing: "no", blocked: [] });
            }

            
            const allPartnerIds = await getLinkedPartners(user.id);
            let linkedAccountsText = 'لا يوجد';

            if (allPartnerIds.length > 0) {
                const partnerLines = [];
                for (const pid of allPartnerIds) {
                    try {
                        const pData = await db.findOne({ id: pid });
                        const pUser = await client.users.fetch(pid);
                        const balance = pData ? parseInt(pData.coins).toLocaleString() : '0';
                        partnerLines.push(`<@${pid}> — **${balance}** كوين`);
                    } catch (e) {
                        partnerLines.push(`<@${pid}>`);
                    }
                }
                linkedAccountsText = partnerLines.join('\n');
            }

            const infoEmbed = new Discord.MessageEmbed()
                .setColor(typeof serverColor !== 'undefined' ? serverColor : '#0099ff')
                .setTitle(`💼 **معلومات الحساب الشخصي**`)
                .setDescription(`🔍 **تفاصيل الحساب الخاص بـ ${user.tag}**`)
                .setThumbnail(user.displayAvatarURL({ dynamic: true }))
                .addField("💰 **رصيدك الحالي**", `${parseInt(data.coins).toLocaleString()} كوين`, true)
                .addField(`🏦 **الحسابات البنكية المرتبطة** (${allPartnerIds.length}/${MAX_LINKS})`, linkedAccountsText, false)
                .addField("🔒 **اللاعبون المحظورون**", 
                    (data.blocked && data.blocked.length > 0) 
                    ? data.blocked.map(blockedUserId => `<@${blockedUserId}>`).join(", ") 
                    : "لا يوجد", true)
                .setFooter({ 
                    text: `تم الطلب بواسطة ${user.username}`, 
                    iconURL: user.displayAvatarURL({ dynamic: true }) 
                })
                .setTimestamp();

            
            return message.reply({ embeds: [infoEmbed] });

        } catch (error) {
            console.error("خطأ في أمر معلومات:", error);
            return message.reply("⚠️ حدث خطأ أثناء جلب معلومات حسابك.");
        }
    }
});

const dailyPoolPath = path.join(__dirname, 'databasew.json');

let dailyPool = {
    globalAmount: 0 
};

if (fs.existsSync(dailyPoolPath)) {
    try {
        const loadedData = JSON.parse(fs.readFileSync(dailyPoolPath, 'utf8'));
        if (loadedData.globalAmount !== undefined) {
            dailyPool = loadedData;
        }
    } catch (error) {
        console.error('Error loading daily pool data:', error);
    }
}

function saveDailyPool() {
    try {
        fs.writeFileSync(dailyPoolPath, JSON.stringify(dailyPool, null, 4));
    } catch (error) {
        console.error('Error saving daily pool data:', error);
    }
}

const dailyProcessing = new Set();
const activeDailyMessages = []; 

async function disableAllDailyButtons() {
    for (const msgData of activeDailyMessages) {
        try {
            const channel = client.channels.cache.get(msgData.channelId);
            if (channel) {
                const msg = await channel.messages.fetch(msgData.messageId);
                if (msg) {
                    await msg.edit({ components: [] });
                }
            }
        } catch (error) {
            console.error('Error disabling buttons:', error);
        }
    }
    activeDailyMessages.length = 0; 
}

client.on("messageCreate", async message => {
    if (message.content.startsWith("rstcooldown")) {
        
        if (!isOwnerOrGranted(message.author.id, 'rstcooldown')) {
            return message.reply("❌ ليس لديك صلاحية لاستخدام هذا الأمر!");
        }

        const mentionedUser = message.mentions.users.first();
        if (!mentionedUser) {
            return message.reply("❌ يجب عليك منشن الشخص! مثال: `rstcooldown @user`");
        }

        const targetUserId = mentionedUser.id;
        
        
        if (dailyData[targetUserId]) {
            delete dailyData[targetUserId];
            fs.writeFileSync(dailyFilePath, JSON.stringify(dailyData, null, 4));
            
            return message.reply(`✅ تم إعادة تعيين الكول داون لـ ${mentionedUser}!`);
        } else {
            return message.reply(`❌ ${mentionedUser} ليس لديه كول داون حالياً!`);
        }
    }
});

