client.on("interactionCreate", async (interaction) => {
    if (!interaction.isButton()) return;

    if (interaction.customId === "withdraw_cashback") {
        let user = interaction.user;

        let data = await db.findOne({ id: user.id });

        if (!data || data.cashback <= 0) {
            return interaction.reply({ content: "ليس لديك أي رصيد في الكاش باك لسحبه.", ephemeral: true });
        }

        // 1. الفحص والتحقق هل اشتراك البرايم ساري وصالح حالياً؟
        const isUserPrimed = data.primeExpires && moment(data.primeExpires).isAfter(moment());

        let cashbackToWithdraw = data.cashback;
        let isMultiplierApplied = false;

        // 2. إذا كان عنده برايم، يتم مضاعفة الكاش باك المكتسب
        if (isUserPrimed) {
            cashbackToWithdraw = data.cashback * 2;
            isMultiplierApplied = true;
        }

        // تصفير الكاش باك في الداتابيز وإضافة القيمة الجديدة للعملات
        data.cashback = 0;
        data.coins += cashbackToWithdraw;

        await data.save();

        // تعديل نص الرسالة للتوضيح في حال تم تفعيل المضاعف
        let descriptionText = `> 💰 **تم سحب مبلغ:** ${parseInt(cashbackToWithdraw).toLocaleString()} إلى رصيدك .`;
        if (isMultiplierApplied) {
            descriptionText = `> 👑 **سحب الكاش باك لمشتركي البرايم** ${parseInt(cashbackToWithdraw).toLocaleString()} إلى رصيدك!`;
        }

        const embed = new Discord.MessageEmbed()
            .setColor(serverColor)
            .setThumbnail(client.user.avatarURL({ dynamic: true }))
            .setTitle("تم السحب بنجاح!")
            .setDescription(descriptionText)
            .setFooter({ text: interaction.guild.name })
            .setTimestamp();

        return interaction.update({
            embeds: [embed],
            components: [],
        });
    }
});

const boostsPath = path.resolve(__dirname, 'boosts.json');

let boostsData = {};
if (fs.existsSync(boostsPath)) {
  boostsData = JSON.parse(fs.readFileSync(boostsPath, 'utf8'));
}

client.on("messageCreate", async (message) => {
  if (message.channel.parentId === "1478722657661747220") return;
  
  if (message.content.toLowerCase() === 'بوست') {
    if (!message.guild) return;
    if (isBlacklisted(message.author.id)) return;
    
    if (!message.member.premiumSince) {
      return message.reply('> **يجب ان تعمل بوست للسيرفر للحصول علي المكافآة .**');
    }

    const userId = message.author.id;
    const now = new Date();

    if (!boostsData[userId]) {
      boostsData[userId] = {
        lastBoost: null,
        boostStart: message.member.premiumSince.toISOString(),
      };
      fs.writeFileSync(boostsPath, JSON.stringify(boostsData, null, 2));
    }

    const lastBoost = boostsData[userId].lastBoost ? new Date(boostsData[userId].lastBoost) : null;
    if (lastBoost && (now - lastBoost) < 7 * 24 * 60 * 60 * 1000) {
      const nextAvailable = new Date(lastBoost.getTime() + 7 * 24 * 60 * 60 * 1000);
      return message.reply(`> **يمكنك استخدام الأمر مرة أخرى في ${nextAvailable.toLocaleDateString()} .**`);
    }

    const boostStart = new Date(boostsData[userId].boostStart);
    const daysBoosted = Math.floor((now - boostStart) / (24 * 60 * 60 * 1000));
    
    console.log(`User ${userId} has boosted for ${daysBoosted} days`);
    console.log(`Boost start: ${boostStart}`);
    console.log(`Current date: ${now}`);

    let reward = 0;
    if (daysBoosted >= 28) {
      reward = 200000;
    } else if (daysBoosted >= 14) {
      reward = 140000;
    } else if (daysBoosted >= 7) {
      reward = 120000;
    } else if (daysBoosted >= 0) {
      reward = 100000;
    } else {
      return message.reply('> **حدث خطأ في حساب أيام البوست.**');
    }

    console.log(`Calculated reward: ${reward}`);

    boostsData[userId].lastBoost = now.toISOString();
    fs.writeFileSync(boostsPath, JSON.stringify(boostsData, null, 2));

    try {
      let userData = await db.findOne({ id: userId });

      if (!userData) {
        userData = await db.create({ id: userId, coins: reward });
      } else {
        userData.coins += reward;
        await userData.save();
      }
        
      const currentCoins = userData.coins;
      
      console.log(`User coins after reward: ${currentCoins}`);

      const embed = new MessageEmbed()
        .setColor(serverColor)
        .setTitle('🎉 مكافأة البوست 🎉')
        .addFields(
          { name: '> المستخدم', value: `${message.author}`, inline: true },
          { name: '> قيمة المكافأة', value: `$${reward.toLocaleString()}`, inline: true },
          { name: '> أيام البوست', value: `${daysBoosted} يوم`, inline: true },
          { name: '> تاريخ المكافأة', value: `${now.toLocaleDateString()}`, inline: true },
          { name: '> الرصيد الحالي', value: `$${currentCoins.toLocaleString()}`, inline: true }
        )
        .setThumbnail(message.author.displayAvatarURL())
        .setFooter(`Server: ${message.guild.name}`, message.guild.iconURL())
        .setTimestamp();

      message.reply({ embeds: [embed], allowedMentions: { repliedUser: false } });
      
      const logChannel = client.channels.cache.get(logStaffEconomyChannelId);
      if (logChannel) {
        const logEmbed = new MessageEmbed()
          .setColor(serverColor)
          .setTitle('📜 سجل مكافأة البوست')
          .addFields(
            { name: '> المستخدم', value: `<@!${message.author.id}>`, inline: true },
            { name: '> قيمة المكافأة', value: `$${reward.toLocaleString()}`, inline: true },
            { name: '> أيام البوست', value: `${daysBoosted} يوم`, inline: true },
            { name: '> الرصيد الحالي', value: `$${currentCoins.toLocaleString()}`, inline: true },
            { name: '> وقت التنفيذ', value: `${now.toLocaleString()}`, inline: true }
          )
          .setFooter(`${message.guild.name}`, message.guild.iconURL())
          .setTimestamp();

        logChannel.send({ embeds: [logEmbed], content: `> <@!${message.author.id}>\n|| <#${message.channel.id}> || || ${message.url} ||` });
      }
    } catch (error) {
      console.error(`Error while handling boost rewards: ${error.message}`);
      message.reply('> **حدث خطأ أثناء محاولة منح المكافأة. حاول مرة أخرى لاحقًا.**');
    }
  }
});
async function clearDatabase(user) {
	try {
		let data = await db.findOne({
			id: user
		});
		if(!data) {
			let data = await db.create({
				id: user
			})
		}
		data.status_playing = "no";
		await data.save();
	} catch (err) {}
}
async function clearAllDatabase() {
	try {
		await db.updateMany({}, { $set: { status_playing: "no" } });
	} catch (err) {}
}

