            await bal.save();
            invalidateMoneyCache(message.author.id);
            await message
                .reply(
                    `✅ تم تحويل \`${amount.toLocaleString()}\` كوينز من رصيدك إلى **ميزانية المنظم**.\n` +
                        `**المتبقي في الميزانية:** \`${founderBudget.remainingBudget.toLocaleString()}\` كوينز.`
                )
