function getChoiceEmoji(choice) {
    const emojis = {
        'حجرة': '🪨',
        'ورقة': '📄',
        'مقص': '✂️'
    };
    return emojis[choice] || '❓';
}

function buildPlayerHistory(roundHistory, playerId, player1Id) {
    if (!roundHistory || roundHistory.length === 0) return '';
    
    let historyStr = '';
    roundHistory.forEach((round, index) => {
        const choice = playerId === player1Id ? round.player1Choice : round.player2Choice;
        const emoji = getChoiceEmoji(choice);
        
        if (index > 0) historyStr += ' + ';
        historyStr += emoji;
    });
    
    return historyStr ? historyStr + ' = ' : '';
}

function determineRPSWinner(choice1, choice2) {
    if (choice1 === choice2) return 'tie';
    
    const winConditions = {
        'حجرة': 'مقص',
        'ورقة': 'حجرة', 
        'مقص': 'ورقة'
    };
    
    return winConditions[choice1] === choice2 ? 'player1' : 'player2';
}

async function processRPSRound(rpsGame, messageId, channel) {
    try {
        const choice1 = rpsGame.player1Choice;
        const choice2 = rpsGame.player2Choice;
        
        const roundResult = determineRPSWinner(choice1, choice2);
        
        let stusrgame = client.users.cache.get(rpsGame.player1);
        let wthusrgame = client.users.cache.get(rpsGame.player2);
        
        const firstUser = client.users.cache.get(rpsGame.displayOrder[0]);
        const secondUser = client.users.cache.get(rpsGame.displayOrder[1]);
        const firstUserChoice = rpsGame.displayOrder[0] === rpsGame.player1 ? choice1 : choice2;
        const secondUserChoice = rpsGame.displayOrder[1] === rpsGame.player1 ? choice1 : choice2;
        
        const firstUserHistory = buildPlayerHistory(rpsGame.roundHistory, rpsGame.displayOrder[0], rpsGame.player1);
        const secondUserHistory = buildPlayerHistory(rpsGame.roundHistory, rpsGame.displayOrder[1], rpsGame.player1);
        const firstUserWins = rpsGame.displayOrder[0] === rpsGame.player1 ? rpsGame.player1Wins : rpsGame.player2Wins;
        const secondUserWins = rpsGame.displayOrder[1] === rpsGame.player1 ? rpsGame.player1Wins : rpsGame.player2Wins;
        
        const boxEmbed = new MessageEmbed()
            .setTitle('🎮 حجرة ورقة مقص')
            .setDescription(`💰 **المبلغ:** ${rpsGame.betAmount.toLocaleString()} عملة`)
            .setColor(serverColor)
            .addFields(
                {
                    name: `${firstUser.tag}`,
                    value: `> Done\n> ${firstUserHistory}<a:spongewildin:1389078494566285422> = **${firstUserWins}** فوز`,
                    inline: false
                },
                {
                    name: `${secondUser.tag}`,
                    value: `> Done\n> ${secondUserHistory}<a:spongewildin:1389078494566285422> = **${secondUserWins}** فوز`,
                    inline: false
                }
            );

        await channel.messages.fetch(messageId).then(msg => msg.edit({
            embeds: [boxEmbed],
            components: []
        }));

        setTimeout(async () => {
            const resultEmbed = new MessageEmbed()
                .setTitle('🎮 حجرة ورقة مقص')
                .setDescription(`💰 **المبلغ:** ${rpsGame.betAmount.toLocaleString()} عملة`)
                .setColor(serverColor)
                .addFields(
                    {
                        name: `${firstUser.tag}`,
                        value: `> Done\n> ${firstUserHistory}${getChoiceEmoji(firstUserChoice)} = **${firstUserWins}** فوز`,
                        inline: false
                    },
                    {
                        name: `${secondUser.tag}`,
                        value: `> Done\n> ${secondUserHistory}${getChoiceEmoji(secondUserChoice)} = **${secondUserWins}** فوز`,
                        inline: false
                    }
                );

            await channel.messages.fetch(messageId).then(msg => msg.edit({
                embeds: [resultEmbed],
                components: []
            }));

            rpsGame.roundHistory.push({
                player1Choice: choice1,
                player2Choice: choice2,
                result: roundResult
            });

            setTimeout(async () => {
                if (roundResult === 'tie') {
                    rpsGame.player1Choice = null;
                    rpsGame.player2Choice = null;
                    rpsGame.currentTurn = rpsGame.player1;
                    rpsGame.roundPhase = 'player1_turn';
                    await rpsGame.save();
                    
                    const newFirstUserHistory = buildPlayerHistory(rpsGame.roundHistory, rpsGame.displayOrder[0], rpsGame.player1);
                    const newSecondUserHistory = buildPlayerHistory(rpsGame.roundHistory, rpsGame.displayOrder[1], rpsGame.player1);
                    
                    const tieEmbed = new MessageEmbed()
                        .setTitle('🎮 حجرة ورقة مقص')
                        .setDescription(`💰 **المبلغ:** ${rpsGame.betAmount.toLocaleString()} عملة\n\n🤝 **تعادل! إعادة الجولة**`)
                        .setColor('#ffeb3b')
                        .addFields(
                            {
                                name: `${firstUser.tag}`,
                                value: `> ${newFirstUserHistory}**${firstUserWins}** فوز`,
                                inline: false
                            },
                            {
                                name: `${secondUser.tag}`,
                                value: `> ${newSecondUserHistory}**${secondUserWins}** فوز`,
                                inline: false
                            }
                        );

                    await channel.messages.fetch(messageId).then(msg => msg.edit({
                        embeds: [tieEmbed],
                        components: []
                    }));

                    setTimeout(async () => {
                        await startNextRPSRound(rpsGame, messageId, channel);
                    }, 2000);
                    
                    return;
                }
                
                if (roundResult === 'player1') {
                    rpsGame.player1Wins++;
                } else if (roundResult === 'player2') {
                    rpsGame.player2Wins++;
                }
                
                const newFirstUserWins = rpsGame.displayOrder[0] === rpsGame.player1 ? rpsGame.player1Wins : rpsGame.player2Wins;
                const newSecondUserWins = rpsGame.displayOrder[1] === rpsGame.player1 ? rpsGame.player1Wins : rpsGame.player2Wins;
                const newFirstUserHistory = buildPlayerHistory(rpsGame.roundHistory, rpsGame.displayOrder[0], rpsGame.player1);
                const newSecondUserHistory = buildPlayerHistory(rpsGame.roundHistory, rpsGame.displayOrder[1], rpsGame.player1);
                
                const winEmbed = new MessageEmbed()
                    .setTitle('🎮 حجرة ورقة مقص')
                    .setDescription(`💰 **المبلغ:** ${rpsGame.betAmount.toLocaleString()} عملة`)
                    .setColor(serverColor)
                    .addFields(
                        {
                            name: `${firstUser.tag}`,
                            value: `> ${newFirstUserHistory}**${newFirstUserWins}** فوز`,
                            inline: false
                        },
                        {
                            name: `${secondUser.tag}`,
                            value: `> ${newSecondUserHistory}**${newSecondUserWins}** فوز`,
                            inline: false
                        }
                    );

                await channel.messages.fetch(messageId).then(msg => msg.edit({
                    embeds: [winEmbed],
                    components: []
                }));

                await rpsGame.save();

                if (rpsGame.player1Wins >= 2 || rpsGame.player2Wins >= 2) {
                    setTimeout(async () => {
                        await finishRPSGame(rpsGame, messageId, channel);
                    }, 3000);
                } else {
                    setTimeout(async () => {
                        await startNextRPSRound(rpsGame, messageId, channel);
                    }, 3000);
                }

            }, 1500);
        }, 1000);
        
    } catch (error) {
        console.error('Error processing RPS round:', error);
    }
}

