function setTurnTimeout(bjGame, channel) {
    const timeout = setTimeout(async () => {
        const playerData = await blackjackusr.findOne({ id: bjGame.role });
        if (playerData && !playerData.stand) {
            playerData.stand = true;
            await playerData.save();

            const tempRole = bjGame.role;
            bjGame.role = bjGame.notrole;
            bjGame.notrole = tempRole;
            await bjGame.save();

            await updateBlackjackGame(channel, bjGame);

            const player1Data = await blackjackusr.findOne({ id: bjGame.idstusr });
            const player2Data = await blackjackusr.findOne({ id: bjGame.idwhusr });

            if (player1Data.stand && player2Data.stand) {
                await endBlackjackGame(channel, bjGame);
            }
        }
        timeouts.delete(bjGame.msgID); 
    }, 30000); 

    timeouts.set(bjGame.msgID, timeout); 
}

function clearTurnTimeout(msgID) {
    const timeout = timeouts.get(msgID);
    if (timeout) {
        clearTimeout(timeout);
        timeouts.delete(msgID);
    }
}

async function endBlackjackGame(channel, bjGame) {
    const player1 = client.users.cache.get(bjGame.idstusr);
    const player2 = client.users.cache.get(bjGame.idwhusr);

    const player1Data = await blackjackusr.findOne({ id: bjGame.idstusr });
    const player2Data = await blackjackusr.findOne({ id: bjGame.idwhusr });

    if (!player1Data || !player2Data) return;

    let winner = null;
    if (player1Data.result > 21 && player2Data.result > 21) {
        winner = "tie";
    } else if (player1Data.result > 21) {
        winner = player2.id;
    } else if (player2Data.result > 21) {
        winner = player1.id;
    } else if (player1Data.result > player2Data.result) {
        winner = player1.id;
    } else if (player2Data.result > player1Data.result) {
        winner = player2.id;
    } else {
        winner = "tie";
    }

    const gameEmbed = new MessageEmbed()
        .setTitle("بيانات التحدي")
        .setColor(serverColor)
        .addFields(
            { name: player1.tag, value: `> ${player1Data.hand.map(card => getCardEmoji(card)).join(' ')} = **${player1Data.result}**` },
            { name: player2.tag, value: `> ${player2Data.hand.map(card => getCardEmoji(card)).join(' ')} = **${player2Data.result}**` }
        );

    let content = "";
    
    
    if (winner === "tie") {
        content = `${player1} / ${player2} تعادل !\n اللعبة: بلاك جاك, المبلغ: **${bjGame.coins}**`;

        
        const p1Data = await db.findOne({ id: player1.id });
        const p2Data = await db.findOne({ id: player2.id });

        if (p1Data) {
            await p1Data.save();
        }

        if (p2Data) {
            await p2Data.save();
        }
    } else if (winner === player1.id) {
        content = `**${player1}** فائززززز !!! ب مجموع **${player1Data.result}** نقطة!\n\n**${player2}** خاسر ب مجموع **${player2Data.result}** نقطة!\n> اللعبة: **بلاك جاك**, المبلغ: **${bjGame.coins}**`;

        const p1Data = await db.findOne({ id: player1.id });
        const p2Data = await db.findOne({ id: player2.id });

        if (p1Data && p2Data) {
            
            p1Data.coins += Math.floor(bjGame.coins * 0.93);
            
            p2Data.coins -= bjGame.coins;
            
            await p1Data.save();
            await p2Data.save();
        }
    } else {
        content = `**${player2}** فائززززز !!! ب مجموع **${player2Data.result}** نقطة!\n\n**${player1}** خاسر ب مجموع **${player1Data.result}** نقطة!\n> اللعبة: **بلاك جاك**, المبلغ: **${bjGame.coins}**`;

        const p1Data = await db.findOne({ id: player1.id });
        const p2Data = await db.findOne({ id: player2.id });

        if (p2Data && p1Data) {
            
            p2Data.coins += Math.floor(bjGame.coins * 0.93);
            
            p1Data.coins -= bjGame.coins;
            
            await p2Data.save();
            await p1Data.save();
        }
    }

    await channel.messages.fetch(bjGame.msgID).then(msg => msg.edit({
        content: content,
        embeds: [gameEmbed],
        components: []
    })).catch(console.error);

    client.channels.cache.get(allbetschannelid).send({
        embeds: [gameEmbed]
    });

    client.channels.cache.get(allbetschannelid).send({
        files: [linelineline]
    });

    await blackjack.findOneAndDelete({ msgID: bjGame.msgID });
    await blackjackusr.findOneAndDelete({ id: player1.id });
    await blackjackusr.findOneAndDelete({ id: player2.id });
    await game.findOneAndDelete({ msgID: bjGame.msgID });

    const p1Data = await db.findOne({ id: player1.id });
    const p2Data = await db.findOne({ id: player2.id });
    if (p1Data) {
        p1Data.status_playing = "no";
        await p1Data.save();
    }
    if (p2Data) {
        p2Data.status_playing = "no";
        await p2Data.save();
    }
    
    
    stopBalanceMonitor(player1.id);
    stopBalanceMonitor(player2.id);
}

async function updateBlackjackGame(channel, bjGame) {
    try {
        const player1 = client.users.cache.get(bjGame.idstusr);
        const player2 = client.users.cache.get(bjGame.idwhusr);

        const player1Data = await blackjackusr.findOne({ id: bjGame.idstusr });
        const player2Data = await blackjackusr.findOne({ id: bjGame.idwhusr });

        if (!player1Data || !player2Data) return;

        if (player1Data.stand && player2Data.stand) {
            clearTurnTimeout(bjGame.msgID); 
            await endBlackjackGame(channel, bjGame); 
            return;
        }

        const gameEmbed = new MessageEmbed()
            .setTitle("بيانات التحدي")
            .setColor(serverColor)
            .addFields(
                { name: player1.tag, value: `> ${getCardEmoji(player1Data.hand[0])} ${player1Data.hand.slice(1).map(() => '<:closed:1317965004624101376>').join(' ')} ${player1Data.stand ? '(وقوف)' : ''}` },
                { name: player2.tag, value: `> ${getCardEmoji(player2Data.hand[0])} ${player2Data.hand.slice(1).map(() => '<:closed:1317965004624101376>').join(' ')} ${player2Data.stand ? '(وقوف)' : ''}` }
            );

        const hitButton = new MessageButton()
            .setCustomId(`bjhit_${bjGame.msgID}`)
            .setLabel("سحب ورقة")
            .setStyle("PRIMARY");

        const standButton = new MessageButton()
            .setCustomId(`bjstand_${bjGame.msgID}`)
            .setLabel("وقوف")
            .setStyle("SECONDARY");

        const eyeButton = new MessageButton()
            .setCustomId(`bjeye_${bjGame.msgID}`)
            .setLabel("عرض أوراقي")
            .setStyle("SUCCESS");

        const row = new MessageActionRow().addComponents(hitButton, standButton, eyeButton);

        await channel.messages.fetch(bjGame.msgID).then(msg => msg.edit({
            content: `<@${bjGame.role}>\n دورك للعب`,
            embeds: [gameEmbed],
            components: [row]
        })).catch(console.error);

        setTurnTimeout(bjGame, channel);
    } catch (error) {
        console.error("Error updating blackjack game:", error);
    }
}

if (interaction.customId.startsWith('bjhit_')) {
    const msgID = interaction.customId.split('_')[1];
    let bjGame = await blackjack.findOne({ msgID: msgID });

    if (!bjGame) return interaction.reply({ content: "**لم يتم العثور على بيانات اللعبة!**", ephemeral: true });

    if (bjGame.role !== interaction.user.id) {
        return interaction.reply({ content: "**ليس دورك للعب!**", ephemeral: true });
    }

    await interaction.deferReply({ ephemeral: true });

    let playerData = await blackjackusr.findOne({ id: interaction.user.id });
    if (!playerData) return interaction.editReply({ content: "**حدث خطأ في بيانات اللاعب!**" });

    const newCard = bjGame.deck.pop();
    playerData.hand.push(newCard);

    playerData.result = calculateHandValue(playerData.hand);
    await playerData.save();
    await bjGame.save();

    if (playerData.result > 21) {
        playerData.stand = true;
        await playerData.save();

        const tempRole = bjGame.role;
        bjGame.role = bjGame.notrole;
        bjGame.notrole = tempRole;
        await bjGame.save();

        interaction.editReply({ content: `**سحبت ورقة ${getCardEmoji(newCard)}! مجموع يدك الآن ${playerData.result} - تجاوزت 21 وخسرت الدور!**` });
    } else {
        interaction.editReply({ content: `**سحبت ورقة ${getCardEmoji(newCard)}! مجموع يدك الآن ${playerData.result}**` });
    }

    clearTurnTimeout(msgID); 
    await updateBlackjackGame(interaction.channel, bjGame);
}

