if(interaction.customId.startsWith(`arkam1tk_`) || interaction.customId.startsWith(`arkam2tk_`)) {
    const messageId = interaction.customId.split('_')[1];
    const userId = interaction.user.id;
    
    
    if (isDoubleClick(interaction.message.id, userId, interaction.customId)) {
        return; 
    }
    
    
    if (isProcessing(messageId, userId)) {
        return; 
    }
    
    
    const cooldownCheck = checkCooldown(messageId, userId);
    if (!cooldownCheck.allowed) {
        if (!interaction.deferred && !interaction.replied) {
            await interaction.deferUpdate().catch(() => {});
        }
        return interaction.followUp({ 
            content: `⏳ انتظر ${cooldownCheck.remaining} ثانية`, 
            ephemeral: true 
        }).catch(() => {});
    }
    
    const globalLockKey = `normal_button_${messageId}_${userId}`;
    if (activeLocks.has(globalLockKey)) {
        return; 
    }
    
    activeLocks.set(globalLockKey, true);
    
    
    await interaction.deferReply({
        ephemeral: true
    }).catch(err => {
        console.error("Defer reply error:", err);
        activeLocks.delete(globalLockKey);
        return;
    });
    
    try {
        let data = await takribi.findOne({
          msgID: messageId
        });
        
        if(!data) {
            activeLocks.delete(globalLockKey);
            return interaction.editReply({
                content: "❌ لم يتم العثور على بيانات اللعبة",
                ephemeral: true
            });
        }
        
        if(data.role !== userId && data.controllingPlayer !== userId) {
            activeLocks.delete(globalLockKey);
            return interaction.editReply({
                content: `**ليس دورك!** يرجى الانتظار حتى ينتهي اللاعب الآخر.`,
                ephemeral: true
            });
        }
        
        let targetUserId = userId;
        if (data.controllingPlayer === userId) {
            targetUserId = data.role;
        }
        
        let datausr = await tkusr.findOne({
          id: targetUserId,
          msgID: messageId
        });
        
        if(!datausr) {
            activeLocks.delete(globalLockKey);
            return;
        }
        
        let gdata = await game.findOne({
          id: data.idstusr,
          msgID: messageId
        });
        
        if(!gdata) {
            activeLocks.delete(globalLockKey);
            return;
        }
        
        let stusrgame = client.users.cache.get(data.idstusr);
        let wthusrgame = client.users.cache.get(gdata.with);
        
        if(!stusrgame || !wthusrgame) {
            activeLocks.delete(globalLockKey);
            return;
        }
        
        gdata.time = timestamp(moment(ms("90s")) + Date.now());
        await gdata.save();
        
        
        let urnum;
        
        
        let nextNum = nextNumbersQueue.get(userId);
        if (nextNum && nextNum.length > 0) {
            urnum = nextNum.shift();
            if (nextNum.length === 0) {
                nextNumbersQueue.delete(userId);
            }
        } else {
            
            if(interaction.customId.startsWith(`arkam1tk_`)) {
                urnum = getRandomNumbertakribi(parseInt(data.number_smaller1), parseInt(data.number_smaller2));
            } else {
                urnum = getRandomNumbertakribi(parseInt(data.number_greater1), parseInt(data.number_greater2));
            }
        }
        
        
        const currentResult = parseInt(datausr.result || 0) + urnum;
        const maxNumber = parseInt(data.max_number);
        
        
        if(maxNumber <= currentResult) {
            lockProcessing(messageId, targetUserId);
        }
        
        
        let resultMessage = `لقد حصلت على **${urnum}**\nأصبح مجموعك: **${currentResult}**\n`;
        
        
        datausr.numbers.push(urnum);
        datausr.result = currentResult;
        await datausr.save();
        
        if(parseInt(data.max_number) < currentResult) {
            
            data.number_players_done = parseInt(data.number_players_done) + 1;
            
            if(targetUserId === stusrgame.id) {
                data.player1Done = true;
            } else if(targetUserId === wthusrgame.id) {
                data.player2Done = true;
            }
            
            await data.save();
            
            resultMessage += "> ⚠️ **تخطي!** لقد تجاوزت الرقم المطلوب (**" + data.max_number + "**) وقد تم إنهاء دورك.";
            
            if(parseInt(data.number_players_done) < 2) {
                await switchTurnNormalMode(data, interaction.channel.id, gdata.msgID, stusrgame, wthusrgame);
                
                resetClickCount(messageId, targetUserId);
                unlockProcessing(messageId, targetUserId);
            } else {
                await endGameNormalMode(data, interaction.channel.id, gdata.msgID, stusrgame, wthusrgame);
                
                setTimeout(async () => {
                    await processGameResults(data, gdata, interaction);
                    
                    resetClickCount(messageId, targetUserId);
                    unlockProcessing(messageId, targetUserId);
                }, 1500);
            }
        }
        else if(parseInt(data.max_number) == currentResult) {
            
            data.number_players_done = parseInt(data.number_players_done) + 1;
            
            if(targetUserId === stusrgame.id) {
                data.player1Done = true;
            } else if(targetUserId === wthusrgame.id) {
                data.player2Done = true;
            }
            
            await data.save();
            
            resultMessage += "> 🎉 **تهانينا!** لقد حصلت على الرقم المطلوب تماماً وتم إنهاء دورك.";
            
            if(parseInt(data.number_players_done) < 2) {
                await switchTurnNormalMode(data, interaction.channel.id, gdata.msgID, stusrgame, wthusrgame);
                
                resetClickCount(messageId, targetUserId);
                unlockProcessing(messageId, targetUserId);
            } else {
                await endGameNormalMode(data, interaction.channel.id, gdata.msgID, stusrgame, wthusrgame);
                
                setTimeout(async () => {
                    await processGameResults(data, gdata, interaction);
                    
                    resetClickCount(messageId, targetUserId);
                    unlockProcessing(messageId, targetUserId);
                }, 1500);
            }
        }
        else {
            resultMessage += "> يمكنك الاستمرار في اللعب للوصول لرقم أعلى، أو الضغط على زر 'Finish' لإنهاء دورك.";
        }
        
        interaction.editReply({
            content: resultMessage,
            ephemeral: true
        }).then(async () => {
            try {
                const userToNotify = interaction.guild.members.cache.get(userId);
                if(userToNotify) {
                    let dmMsg = await userToNotify.send(resultMessage).catch(() => null);
                    if(dmMsg) {
                        setTimeout(() => {
                            dmMsg.delete().catch(() => {});
                        }, 90000);
                    }
                }
            } catch (error) {
            }
        });
    } catch (error) {
        console.error("Error in normal mode button click:", error);
    } finally {
        setTimeout(() => {
            activeLocks.delete(globalLockKey);
        }, 500);
    }
}

