async function switchTurnNormalMode(data, channelId, messageId, stusrgame, wthusrgame) {
    try {
        const nextPlayer = data.notrole;
        const prevPlayer = data.role;
        
        data.role = nextPlayer;
        data.notrole = prevPlayer;
        await data.save();
        
        const embed = new Discord.MessageEmbed()
            .setColor(serverColor)
            .setTitle("بيانات التحدي")
            .setDescription(`اقصى رقم : **${data.max_number}**`);
        
        let p1Status;
        if (data.player1Done) {
            p1Status = "Done";
        } else if (nextPlayer === stusrgame.id) {
            p1Status = "**Playing...**";
        } else {
            p1Status = "Waiting...";
        }
        
        let p2Status;
        if (data.player2Done) {
            p2Status = "Done";
        } else if (nextPlayer === wthusrgame.id) {
            p2Status = "**Playing...**";
        } else {
            p1Status = "Waiting...";
        }
        
        embed.addFields(
            { name: `${stusrgame.tag}`, value: `> ${p1Status}` },
            { name: `${wthusrgame.tag}`, value: `> ${p2Status}` }
        );
        
        
        const buttons = createGameButtons(
            messageId, 
            data.number_smaller1, 
            data.number_smaller2, 
            data.number_greater1, 
            data.number_greater2, 
            "normal", 
            false,  
            false,  
            false   
        );
        
        
        await safeUpdateMessage(channelId, messageId, {
            embeds: [embed],
            content: `<@!${nextPlayer}>\nدورك الآن!`,
            components: [buttons]
        }, "switchTurnNormalMode");
        
    } catch (error) {
        console.error("Error switching turns in normal mode:", error);
    }
}

async function endGameNormalMode(data, channelId, messageId, stusrgame, wthusrgame) {
    try {
        const embed = new Discord.MessageEmbed()
            .setColor(serverColor)
            .setTitle("بيانات التحدي")
            .setDescription(`اقصى رقم : **${data.max_number}**`)
            .addFields({
                name: `${stusrgame.tag}`,
                value: `> Done`
            }, {
                name: `${wthusrgame.tag}`,
                value: `> Done`
            });
        
        const channel = client.channels.cache.get(data.channelID);
        if (!channel) {
            console.error(`Channel not found: ${data.channelID}`);
            return;
        }
        
        let retryCount = 0;
        const maxRetries = 3;
        const fetchAndEditEndGameMessage = async () => {
            try {
                const abortController = new AbortController();
                const timeoutId = setTimeout(() => abortController.abort(), 15000);
                
                const msg = await channel.messages.fetch(messageId, { signal: abortController.signal });
                clearTimeout(timeoutId);
                
                const editController = new AbortController();
                const editTimeoutId = setTimeout(() => editController.abort(), 15000);
                
                await msg.edit({
                    embeds: [embed],
                    content: `> جاري احتساب النتائج... ⏳`,
                    components: [] 
                });
                
                clearTimeout(editTimeoutId);
            } catch (err) {
                if (err.name === 'AbortError' || err.code === 'ECONNRESET' || (err.message && err.message.includes('socket hang up'))) {
                    retryCount++;
                    if (retryCount <= maxRetries) {
                        console.log(`Retrying end game message edit (attempt ${retryCount}/${maxRetries}) after error: ${err.message}`);
                        const delay = Math.min(1000 * Math.pow(1.5, retryCount) + Math.random() * 1000, 10000);
                        setTimeout(fetchAndEditEndGameMessage, delay);
                        return;
                    }
                }
                console.error("Error updating end game message after retries:", err);
            }
        };
        
        fetchAndEditEndGameMessage();
    } catch (error) {
        console.error("Error ending game in normal mode:", error);
    }
}

