function createGameButtons(msgID, num_smaller1, num_smaller2, num_greater1, num_greater2, mode, disabled, leftDisabled = false, rightDisabled = false) {
    const prefix = mode === "normal" ? "tk" : (mode === "limit" ? "tkl" : "tkk");
    
    let button_arkam1 = new MessageButton()
        .setCustomId(`arkam1${prefix}_${msgID}`)
        .setLabel(`${num_smaller1} - ${num_smaller2}`)
        .setStyle("PRIMARY");
    
    let button_finish = new MessageButton()
        .setCustomId(`finish${prefix}_${msgID}`)
        .setLabel("Finish")
        .setStyle("SUCCESS");
    
    let button_arkam2 = new MessageButton()
        .setCustomId(`arkam2${prefix}_${msgID}`)
        .setLabel(`${num_greater1} - ${num_greater2}`)
        .setStyle("PRIMARY");
    
    let button_info = new MessageButton()
        .setCustomId(`info${prefix}_${msgID}`)
        .setLabel("ℹ️")
        .setStyle("SECONDARY");
    
    if(disabled) {
        button_arkam1.setDisabled(true);
        button_finish.setDisabled(true);
        button_arkam2.setDisabled(true);
        button_info.setDisabled(true);
    } else {
        
        button_info.setDisabled(false);
        
        if(leftDisabled) {
            button_arkam1.setDisabled(true).setStyle("DANGER").setLabel(`${num_smaller1}-${num_smaller2} `);
        }
        
        if(rightDisabled) {
            button_arkam2.setDisabled(true).setStyle("DANGER").setLabel(`${num_greater1}-${num_greater2} `);
        }
        
        if(mode === "condition") {
            if(leftDisabled && rightDisabled) {
                button_finish.setDisabled(false);
            } else {
                button_finish.setDisabled(true);
            }
        }
    }
    
    return new MessageActionRow().setComponents(button_arkam1, button_finish, button_arkam2, button_info);
}

