async function processGameResultsLimit(data, gdata, interaction) {
    try {
        
        try {
            const channel = client.channels.cache.get(data.channelID);
            if (channel) {
                const msg = await channel.messages.fetch(data.msgID);
                await msg.edit({
                    content: `> جاري احتساب النتائج... ⏳`,
                    components: []
                });
            }
        } catch (err) {
            console.error("Error removing buttons:", err);
        }
        
        let datausrtk1 = await tkusr.findOne({ 
            id: data.user1,
            msgID: data.msgID
        });
        
        let datausrtk2 = await tkusr.findOne({ 
            id: data.user2,
            msgID: data.msgID
        });
        
        if(!datausrtk1 || !datausrtk2) return;
        
        let stusrgame = client.users.cache.get(data.user1);
        let wthusrgame = client.users.cache.get(data.user2);
        
        if(!stusrgame || !wthusrgame) return;
        
        let embed_finish_tk_game = new Discord.MessageEmbed()
            .setColor(serverColor)
            .setTitle("نتائج التحدي")
            .setDescription(`اقصى رقم : **${data.max_number}**`)
            .addFields({
                name: `${stusrgame.tag}`,
                value: `> ${datausrtk1.numbers.join(" + ") || ""} = **${datausrtk1.result || 0}**`
            }, {
                name: `${wthusrgame.tag}`,
                value: `> ${datausrtk2.numbers.join(" + ") || ""} = **${datausrtk2.result || 0}**`
            });
        
        
        let gameTypeText = data.gameType === 'limshow' ? 
            'الحد التقريبي (اظهار ارقام) 🔢' : 
            'الحد التقريبي الطبيعي 🏁';
        
        const player1Result = parseInt(datausrtk1.result || 0);
        const player2Result = parseInt(datausrtk2.result || 0);
        const maxNumber = parseInt(data.max_number);
        
        const player1Distance = Math.abs(player1Result - maxNumber);
        const player2Distance = Math.abs(player2Result - maxNumber);
        
        let resultMessage = "";
        let winner, loser, isDraw = false;
        
        if(player1Distance < player2Distance) {
            winner = stusrgame;
            loser = wthusrgame;
            resultMessage = `** نتيجة اللعبة :**\n\n الـ ** فـآئز ** : <@${winner.id}> \`-\` بـ ** مجموع ** : \`${player1Result}\`\n\nالـ ** خـآسر ** : <@${loser.id}> \`-\` بـ ** مجموع ** : \`${player2Result}\`\n\nالـ ** لعبة ** : الـ\`${gameTypeText}\` .! \`-\` الـ **💰 - مبلغ** : \`${parseInt(gdata.coins).toLocaleString()}\` .!`;
        } else if(player2Distance < player1Distance) {
            winner = wthusrgame;
            loser = stusrgame;
            resultMessage = `** نتيجة اللعبة :**\n\n الـ ** فـآئز ** : <@${winner.id}> \`-\` بـ ** مجموع ** : \`${player2Result}\`\n\nالـ ** خـآسر ** : <@${loser.id}> \`-\` بـ ** مجموع ** : \`${player1Result}\`\n\nالـ ** لعبة ** : الـ\`${gameTypeText}\` .! \`-\` الـ **💰 - مبلغ** : \`${parseInt(gdata.coins).toLocaleString()}\` .!`;
        } else {
            isDraw = true;
            resultMessage = `** نتيجة اللعبة :**\n\n الـ ** تعادل ** : <@${stusrgame.id}> & <@${wthusrgame.id}>\n\nالـ ** لعبة ** : الـ\`${gameTypeText}\` .! \`-\` الـ **💰 - مبلغ** : \`${parseInt(gdata.coins).toLocaleString()}\` .!`;
        }
        
        const channel = client.channels.cache.get(data.channelID);
        if (!channel) {
            console.error(`Channel not found: ${data.channelID}`);
            return;
        }
        
        let retryCount = 0;
        const maxRetries = 3;
        const fetchAndEditFinalMessage = async () => {
            try {
                const abortController = new AbortController();
                const timeoutId = setTimeout(() => abortController.abort(), 15000);
                
                const msg1 = await channel.messages.fetch(data.msgID, { signal: abortController.signal });
                clearTimeout(timeoutId);
                
                const editController = new AbortController();
                const editTimeoutId = setTimeout(() => editController.abort(), 15000);
                
                await msg1.edit({
                    embeds: [embed_finish_tk_game],
                    content: resultMessage,
                    components: []
                });
                
                clearTimeout(editTimeoutId);
            } catch (err) {
                if (err.name === 'AbortError' || err.code === 'ECONNRESET' || (err.message && err.message.includes('socket hang up'))) {
                    retryCount++;
                    if (retryCount <= maxRetries) {
                        console.log(`Retrying final message edit (attempt ${retryCount}/${maxRetries}) after error: ${err.message}`);
                        const delay = Math.min(1000 * Math.pow(1.5, retryCount) + Math.random() * 1000, 10000);
                        setTimeout(fetchAndEditFinalMessage, delay);
                        return;
                    }
                }
                console.error("Error displaying final result after retries:", err);
            }
        };
        
        fetchAndEditFinalMessage();
        
        if (typeof allbetssend === 'function' && typeof allbetschannelid !== 'undefined') {
            try {
                allbetssend(gameTypeText, winner || stusrgame, loser || wthusrgame, isDraw ? 1 : 0, gdata.coins);
                
                if (allbetschannelid) {
                    const allBetsChannel = client.channels.cache.get(allbetschannelid);
                    if (allBetsChannel) {
                        let retryCount = 0;
                        const maxRetries = 3;
                        
                        const sendWithRetry = async (content) => {
                            try {
                                const abortController = new AbortController();
                                const timeoutId = setTimeout(() => abortController.abort(), 15000);
                                
                                await allBetsChannel.send(content);
                                clearTimeout(timeoutId);
                            } catch (err) {
                                if ((err.name === 'AbortError' || err.code === 'ECONNRESET' || 
                                    (err.message && err.message.includes('socket hang up'))) && retryCount < maxRetries) {
                                    retryCount++;
                                    console.log(`Retrying all bets channel send (attempt ${retryCount}/${maxRetries})`);
                                    const delay = Math.min(1000 * Math.pow(1.5, retryCount) + Math.random() * 1000, 10000);
                                    setTimeout(() => sendWithRetry(content), delay);
                                } else {
                                    console.error("Failed to send message to all bets channel:", err);
                                }
                            }
                        };
                        
                        sendWithRetry({ embeds: [embed_finish_tk_game] });
                        
                        if (typeof linelineline !== 'undefined') {
                            setTimeout(() => {
                                sendWithRetry({ files: [linelineline] });
                            }, 1000);
                        }
                    } else {
                        console.error(`All bets channel not found: ${allbetschannelid}`);
                    }
                }
            } catch (error) {
                console.error("Error recording to all bets channel:", error);
            }
        }
        
        if (isDraw) {
            await updatePlayerStatsForTie(stusrgame.id, wthusrgame.id);
        } else {
            const winnerId = winner.id;
            const loserId = loser.id;
            await updatePlayerStats(loserId, winnerId, gdata.coins);
        }
        
        await cleanupGameData(data.msgID, gdata.msgID, stusrgame.id, wthusrgame.id);
    } catch (error) {
        console.error("Error processing game results in limit mode:", error);
    }
}

async function updateConditionModeDisplayFast(data, channelId, messageId, stusrgame, wthusrgame, updatedPlayerId, newResult, newNumbers) {
    try {
        
        const otherPlayerId = updatedPlayerId === stusrgame.id ? wthusrgame.id : stusrgame.id;
        let otherPlayerData = await tkusr.findOne({ 
            id: otherPlayerId,
            msgID: messageId
        });
        
        if(!otherPlayerData) return;
        
        const maxNumber = parseInt(data.max_number);
        
        
        const updatedNumbers = newNumbers.join(" + ") || "";
        const updatedRemaining = Math.max(0, maxNumber - newResult);
        
        
        const otherNumbers = otherPlayerData.numbers.join(" + ") || "";
        const otherResult = parseInt(otherPlayerData.result || 0);
        const otherRemaining = Math.max(0, maxNumber - otherResult);
        
        
        let player1Numbers, player1Result, player1Remaining;
        let player2Numbers, player2Result, player2Remaining;
        
        if(updatedPlayerId === stusrgame.id) {
            player1Numbers = updatedNumbers;
            player1Result = newResult;
            player1Remaining = updatedRemaining;
            player2Numbers = otherNumbers;
            player2Result = otherResult;
            player2Remaining = otherRemaining;
        } else {
            player1Numbers = otherNumbers;
            player1Result = otherResult;
            player1Remaining = otherRemaining;
            player2Numbers = updatedNumbers;
            player2Result = newResult;
            player2Remaining = updatedRemaining;
        }
        
        const embed = new Discord.MessageEmbed()
            .setColor(serverColor)
            .setTitle("بيانات التحدي")
            .setDescription(`اقصى رقم : **${data.max_number}**`);
        
        const hasController = data.controllingPlayer !== null;
        
        let player1Status, player2Status;
        
        if(stusrgame.id === data.role && !hasController) {
            player1Status = "**Playing...**";
        } else if(stusrgame.id === data.role && data.controllingPlayer === wthusrgame.id) {
            player1Status = "**يتم التحكم به...**";
        } else if(stusrgame.id === data.controllingPlayer) {
            player1Status = "**يتحكم...**";
        } else if(parseInt(data.number_players_done) > 0 && stusrgame.id !== data.role) {
            player1Status = "Done";
        } else {
            player1Status = "Waiting...";
        }
        
        if(wthusrgame.id === data.role && !hasController) {
            player2Status = "**Playing...**";
        } else if(wthusrgame.id === data.role && data.controllingPlayer === stusrgame.id) {
            player2Status = "**يتم التحكم به...**";
        } else if(wthusrgame.id === data.controllingPlayer) {
            player2Status = "**يتحكم...**";
        } else if(parseInt(data.number_players_done) > 0 && wthusrgame.id !== data.role) {
            player2Status = "Done";
        } else {
            player2Status = "Waiting...";
        }
        
        embed.addFields({
            name: `${stusrgame.tag}`,
            value: `> ${player1Status}\n> ${player1Numbers ? player1Numbers + " = " : ""}**${player1Result}**${player1Result < maxNumber ? ` (متبقي **${player1Remaining}**)` : ""}`
        }, {
            name: `${wthusrgame.tag}`,
            value: `> ${player2Status}\n> ${player2Numbers ? player2Numbers + " = " : ""}**${player2Result}**${player2Result < maxNumber ? ` (متبقي **${player2Remaining}**)` : ""}`
        });
        
        let row;
        if(parseInt(data.number_players_done) >= 2) {
            row = createGameButtons(messageId, data.number_smaller1, data.number_smaller2, 
                                 data.number_greater1, data.number_greater2, "condition", true);
        } else {
            const currentScore = updatedPlayerId === data.role ? newResult : otherResult;
            const minLeft = parseInt(data.number_smaller1);
            const minRight = parseInt(data.number_greater1);
            
            const leftGuaranteesLoss = (currentScore + minLeft) > maxNumber;
            const rightGuaranteesLoss = (currentScore + minRight) > maxNumber;
            
            row = createGameButtons(messageId, data.number_smaller1, data.number_smaller2, 
                                 data.number_greater1, data.number_greater2, "condition", false,
                                 leftGuaranteesLoss, rightGuaranteesLoss);
        }
        
        let content;
        if(parseInt(data.number_players_done) >= 2) {
            content = `> انتهى التحدي... سيتم إعلان النتائج قريباً`;
        } else if(hasController) {
            const controlledPlayerId = data.role;
            const controllingPlayerId = data.controllingPlayer;
            content = `اللاعب <@!${controllingPlayerId}> يتحكم في اختيارات <@!${controlledPlayerId}>!`;
        } else {
            content = `<@!${data.role}>\nدورك الآن!`;
        }
        
        client.channels.cache.get(data.channelID).messages.fetch(messageId)
            .then(msg => msg.edit({
                embeds: [embed],
                content: content,
                components: row ? [row] : msg.components
            }))
            .catch(err => console.error("⚡ Error updating fast display:", err));
    } catch (error) {
        console.error("⚡ Error in fast display update:", error);
    }
}

