if(interaction.customId.startsWith(`arkam1tklimit_`) || interaction.customId.startsWith(`arkam2tklimit_`)) {
    const messageId = interaction.customId.split('_')[1];
    const userId = interaction.user.id;
    
    
    if (isDoubleClick(interaction.message.id, userId, interaction.customId)) {
        return; 
    }
    
    
    if (isProcessing(messageId, userId)) {
        return; 
    }
    
    
    const cooldownCheck = checkCooldown(messageId, userId);
    if (!cooldownCheck.allowed) {
        if (!interaction.deferred && !interaction.replied) {
            await interaction.deferUpdate().catch(() => {});
        }
        return interaction.followUp({ 
            content: `⏳ انتظر ${cooldownCheck.remaining} ثانية`, 
            ephemeral: true 
        }).catch(() => {});
    }
    
    const globalLockKey = `limit_button_${messageId}`;
    if (activeLocks.has(globalLockKey)) {
        return; 
    }
    
    activeLocks.set(globalLockKey, true);
    
    try {
        
        if (!interaction.deferred && !interaction.replied) {
            await interaction.deferReply({ ephemeral: true });
        }
        
        let data = await takribi.findOne({
          msgID: messageId
        });
        
        if(!data) {
            activeLocks.delete(globalLockKey);
            return;
        }
        
        if(data.role !== userId) {
            activeLocks.delete(globalLockKey);
            return interaction.editReply({
                content: `**ليس دورك!** يرجى الانتظار حتى ينتهي اللاعب الآخر.`
            }).catch(() => {});
        }
        
        let datausr = await tkusr.findOne({
          id: userId,
          msgID: messageId
        });
        
        if(!datausr) {
            activeLocks.delete(globalLockKey);
            return;
        }
        
        let gdata = await game.findOne({
          id: data.idstusr,
          msgID: messageId
        });
        
        if(!gdata) {
            activeLocks.delete(globalLockKey);
            return;
        }
        
        let stusrgame = client.users.cache.get(data.idstusr);
        let wthusrgame = client.users.cache.get(gdata.with);
        
        if(!stusrgame || !wthusrgame) {
            activeLocks.delete(globalLockKey);
            return;
        }
        
        gdata.time = timestamp(moment(ms("90s")) + Date.now());
        await gdata.save();
        
        
        let urnum;
        
        
        let nextNum = nextNumbersQueue.get(userId);
        if (nextNum && nextNum.length > 0) {
            urnum = nextNum.shift();
            if (nextNum.length === 0) {
                nextNumbersQueue.delete(userId);
            }
        } else {
            
            if(interaction.customId.startsWith(`arkam1tklimit_`)) {
                urnum = getRandomNumbertakribi(parseInt(data.number_smaller1), parseInt(data.number_smaller2));
            } else {
                urnum = getRandomNumbertakribi(parseInt(data.number_greater1), parseInt(data.number_greater2));
            }
        }
        
        
        const currentResult = parseInt(datausr.result || 0) + urnum;
        const maxNumber = parseInt(data.max_number);
        
        
        if(currentResult >= maxNumber) {
            lockProcessing(messageId, userId);
        }
        
        
        datausr.numbers.push(urnum);
        datausr.result = currentResult;
        await datausr.save();
        
        
        await new Promise(resolve => setTimeout(resolve, 200));
        
        
        let resultMessage = `لقد حصلت على **${urnum}**\nأصبح مجموعك: **${currentResult}**\n`;
        
        
        if(currentResult >= maxNumber) {
            
            data.number_players_done = parseInt(data.number_players_done) + 1;
            
            if(userId === stusrgame.id) {
                data.player1Done = true;
            } else if(userId === wthusrgame.id) {
                data.player2Done = true;
            }
            
            await data.save();
            
            if(currentResult == maxNumber) {
                resultMessage += `> 🎉 **تهانينا!** لقد حصلت على الرقم المطلوب تماماً! وتم إنهاء دورك تلقائياً.`;
            } else {
                resultMessage += `> ⚠️ **تخطي!** تجاوزت الرقم المطلوب (**${maxNumber}**). الفرق: **${currentResult - maxNumber}**\nتم إنهاء دورك تلقائياً.`;
            }
            
            interaction.editReply({
                content: resultMessage
            }).catch(() => {}).then(async () => {
                try {
                    const userToNotify = interaction.guild.members.cache.get(userId);
                    if(userToNotify) {
                        let dmMsg = await userToNotify.send(resultMessage).catch(() => null);
                        if(dmMsg) {
                            setTimeout(() => {
                                dmMsg.delete().catch(() => {});
                            }, 90000);
                        }
                    }
                } catch (error) {}
            });
            
            
            if(parseInt(data.number_players_done) < 2) {
                await switchTurnLimitMode(data, interaction.channel.id, gdata.msgID, stusrgame, wthusrgame);
                
                resetClickCount(messageId, userId);
                unlockProcessing(messageId, userId);
                
                
                setTimeout(async () => {
                    try {
                        const confirmMsg = await client.channels.cache.get(interaction.channel.id).messages.fetch(messageId).catch(() => null);
                        if(!confirmMsg) return;
                        const confirmComponents = confirmMsg.components;
                        if(!confirmComponents || !confirmComponents[0]) return;
                        const isDisabled = confirmComponents[0].components.some(c => c.disabled);
                        if(!isDisabled) return;
                        
                        const confirmData = await takribi.findOne({ msgID: messageId }).catch(() => null);
                        if(!confirmData || parseInt(confirmData.number_players_done) >= 2) return;
                        let btn1 = new MessageButton().setCustomId(`arkam1tklimitshow_${messageId}`).setLabel(`${data.number_smaller1} - ${data.number_smaller2}`).setStyle("PRIMARY").setDisabled(false);
                        let btnF = new MessageButton().setCustomId(`finishtklimitshow_${messageId}`).setLabel("Finish").setStyle("SUCCESS").setDisabled(false);
                        let btn2 = new MessageButton().setCustomId(`arkam2tklimitshow_${messageId}`).setLabel(`${data.number_greater1} - ${data.number_greater2}`).setStyle("PRIMARY").setDisabled(false);
                        await confirmMsg.edit({ components: [new MessageActionRow().setComponents(btn1, btnF, btn2)] }).catch(() => {});
                    } catch(e) {}
                }, 2000);
            } else {
                await endGameLimitMode(data, interaction.channel.id, gdata.msgID, stusrgame, wthusrgame);
                
                
                setTimeout(async () => {
                    await processGameResultsLimit(data, gdata, interaction);
                    
                    unlockProcessing(messageId, userId);
                    resetClickCount(messageId, userId);
                }, 300);
            }
        } else {
            const remaining = maxNumber - currentResult;
            resultMessage += `> لا زلت بحاجة إلى **${remaining}** للوصول للرقم المطلوب.\nيمكنك الاستمرار أو إنهاء دورك.`;
            
            interaction.editReply({
                content: resultMessage
            }).catch(() => {}).then(async () => {
                try {
                    const userToNotify = interaction.guild.members.cache.get(userId);
                    if(userToNotify) {
                        let dmMsg = await userToNotify.send(resultMessage).catch(() => null);
                        if(dmMsg) {
                            setTimeout(() => {
                                dmMsg.delete().catch(() => {});
                            }, 90000);
                        }
                    }
                } catch (error) {}
            });
        }
    } catch (error) {
        console.error("Error in limit mode button click:", error);
    } finally {
        setTimeout(() => {
            activeLocks.delete(globalLockKey);
        }, 500);
    }
}

