if(interaction.customId.startsWith(`arkam1tklimitshow_`) || interaction.customId.startsWith(`arkam2tklimitshow_`)) {
    const messageId = interaction.customId.split('_')[1];
    const userId = interaction.user.id;
    
    if (isDoubleClick(interaction.message.id, userId, interaction.customId)) {
        return;
    }
    
    if (isProcessing(messageId, userId)) {
        return;
    }
    
    const cooldownCheck = checkCooldown(messageId, userId);
    if (!cooldownCheck.allowed) {
        return interaction.reply({ 
            content: `⏳ انتظر ${cooldownCheck.remaining} ثانية`, 
            ephemeral: true 
        }).catch(() => {});
    }
    
    const globalLockKey = `limitshow_button_${userId}_${messageId}`;
    if (activeLocks.has(globalLockKey)) {
        return;
    }
    
    activeLocks.set(globalLockKey, true);
    
    try {
        await interaction.deferUpdate();
        
        let data = await takribi.findOne({ msgID: messageId });
        if(!data) { activeLocks.delete(globalLockKey); return; }
        
        if(data.role !== userId) {
            activeLocks.delete(globalLockKey);
            return interaction.followUp({
                content: `**ليس دورك!** يرجى الانتظار حتى ينتهي اللاعب الآخر.`,
                ephemeral: true
            });
        }
        
        let datausr = await tkusr.findOne({ id: userId, msgID: messageId });
        if(!datausr) { activeLocks.delete(globalLockKey); return; }
        
        let gdata = await game.findOne({ id: data.idstusr, msgID: messageId });
        if(!gdata) { activeLocks.delete(globalLockKey); return; }
        
        let stusrgame = client.users.cache.get(data.idstusr);
        let wthusrgame = client.users.cache.get(gdata.with);
        if(!stusrgame || !wthusrgame) { activeLocks.delete(globalLockKey); return; }
        
        gdata.time = timestamp(moment(ms("90s")) + Date.now());
        await gdata.save();
        
        let urnum;
        if(interaction.customId.startsWith(`arkam1tklimitshow_`)) {
            let nextNum = nextNumbersQueue.get(userId); if (nextNum && nextNum.length > 0) { urnum = nextNum.shift(); if (nextNum.length === 0) nextNumbersQueue.delete(userId); } else { urnum = getRandomNumbertakribi(parseInt(data.number_smaller1), parseInt(data.number_smaller2)); }
        } else {
            let nextNum = nextNumbersQueue.get(userId); if (nextNum && nextNum.length > 0) { urnum = nextNum.shift(); if (nextNum.length === 0) nextNumbersQueue.delete(userId); } else { urnum = getRandomNumbertakribi(parseInt(data.number_greater1), parseInt(data.number_greater2)); }
        }
        
        const currentResult = parseInt(datausr.result || 0) + urnum;
        const maxNumber = parseInt(data.max_number);
        
        if(currentResult >= maxNumber) {
            lockProcessing(messageId, userId);
        }
        
        
        if(currentResult < maxNumber) {
            try {
                const gameMsg = await client.channels.cache.get(interaction.channel.id).messages.fetch(messageId).catch(() => null);
                if(gameMsg) {
                    const currentEmbed = gameMsg.embeds[0];
                    if(currentEmbed) {
                        const quickEmbed = new Discord.MessageEmbed(currentEmbed);
                        const playerFieldIndex = userId === stusrgame.id ? 0 : 1;
                        const fields = [...currentEmbed.fields];
                        
                        const tempNumbers = [...(datausr.numbers || []), urnum];
                        const tempNumbersText = tempNumbers.join(" + ");
                        const tempRemaining = Math.max(0, maxNumber - currentResult);
                        
                        fields[playerFieldIndex] = {
                            name: fields[playerFieldIndex].name,
                            value: `> **Playing...**\n> ${tempNumbersText} = **${currentResult}** (متبقي **${tempRemaining}**)`,
                            inline: fields[playerFieldIndex].inline
                        };
                        
                        quickEmbed.fields = fields;
                        
                        let btn1 = new MessageButton().setCustomId(`arkam1tklimitshow_${messageId}`).setLabel(`${data.number_smaller1} - ${data.number_smaller2}`).setStyle("PRIMARY").setDisabled(false);
                        let btnF = new MessageButton().setCustomId(`finishtklimitshow_${messageId}`).setLabel("Finish").setStyle("SUCCESS").setDisabled(false);
                        let btn2 = new MessageButton().setCustomId(`arkam2tklimitshow_${messageId}`).setLabel(`${data.number_greater1} - ${data.number_greater2}`).setStyle("PRIMARY").setDisabled(false);
                        
                        await gameMsg.edit({ embeds: [quickEmbed], components: [new MessageActionRow().setComponents(btn1, btnF, btn2)] }).catch(() => {});
                    }
                }
            } catch(e) {}
        }
        
        
        datausr.numbers.push(urnum);
        datausr.result = currentResult;
        await datausr.save();
        
        if(currentResult >= maxNumber) {
            data.number_players_done = parseInt(data.number_players_done) + 1;
            if(userId === stusrgame.id) data.player1Done = true;
            else if(userId === wthusrgame.id) data.player2Done = true;
            await data.save();
            
            if(parseInt(data.number_players_done) < 2) {
                
                const nextPlayer = data.notrole;
                const prevPlayer = data.role;
                data.role = nextPlayer;
                data.notrole = prevPlayer;
                await data.save();
                
                
                try {
                    const switchMsg = await client.channels.cache.get(interaction.channel.id).messages.fetch(messageId).catch(() => null);
                    if(switchMsg) {
                        const switchEmbed = switchMsg.embeds[0];
                        if(switchEmbed) {
                            const newSwitchEmbed = new Discord.MessageEmbed(switchEmbed);
                            const fields2 = [...switchEmbed.fields];
                            const nextFieldIdx = nextPlayer === stusrgame.id ? 0 : 1;
                            const doneFieldIdx = userId === stusrgame.id ? 0 : 1;
                            
                            const nextDatausr = await tkusr.findOne({ id: nextPlayer, msgID: messageId });
                            const nextNumbers = nextDatausr?.numbers || [];
                            const nextResult = parseInt(nextDatausr?.result || 0);
                            const nextRemaining = Math.max(0, maxNumber - nextResult);
                            
                            
                            fields2[doneFieldIdx] = {
                                name: fields2[doneFieldIdx].name,
                                value: `> Done\n> ${datausr.numbers.join(" + ") || "0"} = **${datausr.result}**`,
                                inline: fields2[doneFieldIdx].inline
                            };
                            
                            
                            const nextNumbersText = nextNumbers.length > 0 
                                ? nextNumbers.join(" + ")
                                : "0";
                            fields2[nextFieldIdx] = {
                                name: fields2[nextFieldIdx].name,
                                value: `> **Playing...**\n> ${nextNumbersText} = **${nextResult}** (متبقي **${nextRemaining}**)`,
                                inline: fields2[nextFieldIdx].inline
                            };
                            
                            newSwitchEmbed.fields = fields2;
                            
                            
                            let btn1 = new MessageButton().setCustomId(`arkam1tklimitshow_${messageId}`).setLabel(`${data.number_smaller1} - ${data.number_smaller2}`).setStyle("PRIMARY").setDisabled(false);
                            let btnF = new MessageButton().setCustomId(`finishtklimitshow_${messageId}`).setLabel("Finish").setStyle("SUCCESS").setDisabled(false);
                            let btn2 = new MessageButton().setCustomId(`arkam2tklimitshow_${messageId}`).setLabel(`${data.number_greater1} - ${data.number_greater2}`).setStyle("PRIMARY").setDisabled(false);
                            
                            await switchMsg.edit({
                                embeds: [newSwitchEmbed],
                                content: `<@!${nextPlayer}>\nدورك الآن!`,
                                components: [new MessageActionRow().setComponents(btn1, btnF, btn2)]
                            });
                        }
                    }
                } catch(e) {
                    console.error("❌ خطأ في تحديث تبديل الدور (limitshow):", e);
                }
                
                resetClickCount(messageId, userId);
                unlockProcessing(messageId, userId);
            } else {
                await endGameLimitMode(data, interaction.channel.id, gdata.msgID, stusrgame, wthusrgame);
                setTimeout(async () => {
                    await processGameResultsLimit(data, gdata, interaction);
                    unlockProcessing(messageId, userId);
                    resetClickCount(messageId, userId);
                }, 300);
            }
        }
    } catch (error) {
        console.error("Error in limit show mode button click:", error);
    } finally {
        setTimeout(() => {
            activeLocks.delete(globalLockKey);
        }, 500);
    }
}

