if(interaction.customId.startsWith(`arkam1tklimitdesc_`) || interaction.customId.startsWith(`arkam2tklimitdesc_`)) {
    const messageId = interaction.customId.split('_')[1];
    const userId = interaction.user.id;
    
    if (isDoubleClick(interaction.message.id, userId, interaction.customId)) {
        return;
    }
    
    if (isProcessing(messageId, userId)) {
        return;
    }
    
    const cooldownCheck = checkCooldown(messageId, userId);
    if (!cooldownCheck.allowed) {
        if (!interaction.deferred && !interaction.replied) {
            await interaction.deferUpdate().catch(() => {});
        }
        return interaction.followUp({ 
            content: `⏳ انتظر ${cooldownCheck.remaining} ثانية`, 
            ephemeral: true 
        }).catch(() => {});
    }
    
    const globalLockKey = `limitdesc_button_${userId}_${messageId}`;
    if (activeLocks.has(globalLockKey)) {
        return;
    }
    
    activeLocks.set(globalLockKey, true);
    
    try {
        await interaction.deferUpdate().catch(() => {});
        
        let data = await takribi.findOne({
          msgID: messageId
        });
        
        if(!data) {
            activeLocks.delete(globalLockKey);
            return;
        }
        
        if(data.role !== userId) {
            activeLocks.delete(globalLockKey);
            return interaction.followUp({
                content: `**ليس دورك!** يرجى الانتظار حتى ينتهي اللاعب الآخر.`,
                ephemeral: true
            }).catch(() => {});
        }
        
        let datausr = await tkusr.findOne({
          id: userId,
          msgID: messageId
        });
        
        if(!datausr) {
            activeLocks.delete(globalLockKey);
            return;
        }
        
        let gdata = await game.findOne({
          id: data.idstusr,
          msgID: messageId
        });
        
        if(!gdata) {
            activeLocks.delete(globalLockKey);
            return;
        }
        
        let stusrgame = client.users.cache.get(data.idstusr);
        let wthusrgame = client.users.cache.get(gdata.with);
        
        if(!stusrgame || !wthusrgame) {
            activeLocks.delete(globalLockKey);
            return;
        }
        
        gdata.time = timestamp(moment(ms("90s")) + Date.now());
        await gdata.save();
        
        
        let urnum;
        if(interaction.customId.startsWith(`arkam1tklimitdesc_`)) {
            let nextNum = nextNumbersQueue.get(userId); if (nextNum && nextNum.length > 0) { urnum = nextNum.shift(); if (nextNum.length === 0) nextNumbersQueue.delete(userId); } else { urnum = getRandomNumbertakribi(parseInt(data.number_smaller1), parseInt(data.number_smaller2)); }
        } else {
            let nextNum = nextNumbersQueue.get(userId); if (nextNum && nextNum.length > 0) { urnum = nextNum.shift(); if (nextNum.length === 0) nextNumbersQueue.delete(userId); } else { urnum = getRandomNumbertakribi(parseInt(data.number_greater1), parseInt(data.number_greater2)); }
        }
        
        
        const currentResult = parseInt(datausr.result) - urnum;
        const maxNumber = parseInt(data.max_number);
        
        
        if(currentResult <= 0) {
            lockProcessing(messageId, userId);
        }
        
        
        if(currentResult > 0) {
            try {
                const gameMsg = await client.channels.cache.get(interaction.channel.id).messages.fetch(messageId).catch(() => null);
                if(gameMsg) {
                    const currentEmbed = gameMsg.embeds[0];
                    if(currentEmbed) {
                        const quickEmbed = new Discord.MessageEmbed(currentEmbed);
                        const playerFieldIndex = userId === stusrgame.id ? 0 : 1;
                        const fields = [...currentEmbed.fields];
                        fields[playerFieldIndex] = {
                            name: fields[playerFieldIndex].name,
                            value: `**Playing...**`,
                            inline: fields[playerFieldIndex].inline
                        };
                        quickEmbed.fields = fields;
                        await gameMsg.edit({ embeds: [quickEmbed] }).catch(() => {});
                    }
                }
            } catch(e) {}
        }
        
        datausr.numbers.push(urnum);
        datausr.result = currentResult;
        await datausr.save();
        
        await new Promise(resolve => setTimeout(resolve, 200));
        
        let resultMessage = `لقد طرحت **${urnum}**\nالمتبقي لديك: **${currentResult}**\n`;
        
        if(currentResult <= 0) {
            data.number_players_done = parseInt(data.number_players_done) + 1;
            
            if(userId === stusrgame.id) {
                data.player1Done = true;
            } else if(userId === wthusrgame.id) {
                data.player2Done = true;
            }
            
            await data.save();
            
            if(currentResult == 0) {
                resultMessage += `> 🎉 **تهانينا!** وصلت للصفر تماماً! وتم إنهاء دورك تلقائياً.`;
            } else {
                resultMessage += `> ⚠️ **تخطي!** تجاوزت الصفر (**${currentResult}**). الفرق: **${Math.abs(currentResult)}**\nتم إنهاء دورك تلقائياً.`;
            }
            
            interaction.followUp({
                content: resultMessage,
                ephemeral: true
            }).catch(() => {});
            
            if(parseInt(data.number_players_done) < 2) {
                await switchTurnLimitDescMode(data, interaction.channel.id, gdata.msgID, stusrgame, wthusrgame);
                resetClickCount(messageId, userId);
                unlockProcessing(messageId, userId);
                

            } else {
                await endGameLimitDescMode(data, interaction.channel.id, gdata.msgID, stusrgame, wthusrgame);
                setTimeout(async () => {
                    await processGameResultsLimitDesc(data, gdata, interaction);
                    unlockProcessing(messageId, userId);
                    resetClickCount(messageId, userId);
                }, 300);
            }
        } else {
            const remaining = currentResult;
            resultMessage += `> لا زلت بحاجة إلى طرح **${remaining}** للوصول للصفر.\nيمكنك الاستمرار أو إنهاء دورك.`;
            
            interaction.followUp({
                content: resultMessage,
                ephemeral: true
            }).catch(() => {});
        }
    } catch (error) {
        console.error("Error in limitdesc mode button click:", error);
    } finally {
        setTimeout(() => {
            activeLocks.delete(globalLockKey);
        }, 500);
    }
}

if(interaction.customId.startsWith(`finishtklimitdesc_`)) {
    const messageId = interaction.customId.split('_')[1];
    const userId = interaction.user.id;
    
    if (isDoubleClick(interaction.message.id, userId, interaction.customId)) {
        return interaction.reply({ content: "⏳ انتظر قليلاً...", ephemeral: true });
    }
    
    const globalLockKey = `limitdesc_finish_${userId}_${messageId}`;
    if (activeLocks.has(globalLockKey)) {
        return interaction.reply({ 
            content: "الرجاء الانتظار، جاري معالجة طلبك السابق", 
            ephemeral: true 
        });
    }

    const gameFinishKey = `game_finish_desc_${messageId}`;
    if (gameFinishLocks.has(gameFinishKey)) {
        return interaction.reply({ content: '⏳ جاري معالجة إنهاء اللعبة...', ephemeral: true });
    }
    gameFinishLocks.set(gameFinishKey, true);
    setTimeout(() => gameFinishLocks.delete(gameFinishKey), 5000);
    
    activeLocks.set(globalLockKey, true);
    
    try {
        await interaction.deferUpdate();
        
        let data = await takribi.findOne({
          msgID: messageId
        });
        
        if(!data) {
            activeLocks.delete(globalLockKey);
            return;
        }
        
        await interaction.followUp({
            content: "جاري إنهاء دورك...",
            ephemeral: true
        });
        
        if(data.role !== userId) {
            return interaction.followUp({
                content: `**ليس دورك!** يرجى الانتظار حتى ينتهي اللاعب الآخر.`,
                ephemeral: true
            });
        }

        
        const alreadyDoneDesc = (userId === data.user1 && data.player1Done) ||
                                (userId === data.user2 && data.player2Done);
        if (alreadyDoneDesc) {
            activeLocks.delete(globalLockKey);
            gameFinishLocks.delete(gameFinishKey);
            return interaction.followUp({ content: '> ⚠️ **أنهيت دورك مسبقاً!**', ephemeral: true });
        }
        
        let datausr = await tkusr.findOne({
          id: userId,
          msgID: messageId
        });
        
        if(!datausr) {
            activeLocks.delete(globalLockKey);
            return;
        }
        
        let gdata = await game.findOne({
          id: data.idstusr,
          msgID: messageId
        });
        
        if(!gdata) {
            activeLocks.delete(globalLockKey);
            return;
        }
        
        let stusrgame = client.users.cache.get(data.idstusr);
        let wthusrgame = client.users.cache.get(gdata.with);
        
        if(!stusrgame || !wthusrgame) {
            activeLocks.delete(globalLockKey);
            return;
        }
        
        data.number_players_done = parseInt(data.number_players_done) + 1;

        if(userId === stusrgame.id) {
            data.player1Done = true;
        } else if(userId === wthusrgame.id) {
            data.player2Done = true;
        }

        await data.save();
        
        gdata.time = timestamp(moment(ms("90s")) + Date.now());
        await gdata.save();
        
        interaction.followUp({
            content: `> تم إنهاء دورك بنجاح. المتبقي لديك هو: ${datausr.result}`,
            ephemeral: true
        });
        
        if(parseInt(data.number_players_done) < 2) {
            const player2Data = await tkusr.findOne({
                id: data.notrole,
                msgID: messageId
            });
            
            if (player2Data && parseInt(player2Data.result || 0) <= 0) {
                data.number_players_done = 2;
                if(data.notrole === stusrgame.id) {
                    data.player1Done = true;
                } else {
                    data.player2Done = true;
                }
                await data.save();
                
                await endGameLimitDescMode(data, interaction.channel.id, messageId, stusrgame, wthusrgame);
                
                setTimeout(async () => {
                    await processGameResultsLimitDesc(data, gdata, interaction);
                }, 300);
            } else {
                
                const disBtnsDesc = createGameButtons(messageId, data.number_smaller1, data.number_smaller2,
                                                 data.number_greater1, data.number_greater2, "limit", true);
                await client.channels.cache.get(interaction.channel.id).messages.fetch(messageId)
                    .then(msg => msg.edit({ components: [disBtnsDesc] })).catch(() => {});

                await switchTurnLimitDescMode(data, interaction.channel.id, messageId, stusrgame, wthusrgame);
            }
        } else {
            await endGameLimitDescMode(data, interaction.channel.id, messageId, stusrgame, wthusrgame);
            
            setTimeout(async () => {
                await processGameResultsLimitDesc(data, gdata, interaction);
            }, 300);
        }
    } catch (error) {
        console.error("Error in limitdesc finish:", error);
    } finally {
        setTimeout(() => {
            activeLocks.delete(globalLockKey);
        }, 1000);
    }
}

