if(interaction.customId.startsWith(`notklimitdesc_`)) {
    if (isDoubleClick(interaction.message.id, interaction.user.id, interaction.customId)) {
        return interaction.reply({ content: "⏳ انتظر قليلاً...", ephemeral: true });
    }
    
    const messageId = interaction.customId.split('_')[1];
    const userId = interaction.user.id;
    
    const globalLockKey = `limitdesc_decline_${userId}_${messageId}`;
    if (activeLocks.has(globalLockKey)) {
        if (!interaction.deferred && !interaction.replied) {
            await interaction.deferUpdate().catch(() => {});
        }
        return interaction.followUp({ 
            content: "الرجاء الانتظار، جاري معالجة طلبك السابق", 
            ephemeral: true 
        }).catch(() => {});
    }
    
    activeLocks.set(globalLockKey, true);
    
    try {
        let gdata = await game.findOne({
          msgID: messageId
        });
        
        if(!gdata) {
            activeLocks.delete(globalLockKey);
            return;
        }
        
        let stusrgame = client.users.cache.get(gdata.id);
        let wthusrgame = client.users.cache.get(gdata.with);
        
        if(stusrgame.id !== userId && wthusrgame.id !== userId) {
            activeLocks.delete(globalLockKey);
            return interaction.reply({ 
                content: "هذا التحدي ليس لك!", 
                ephemeral: true 
            });
        }
        
        if (!interaction.deferred && !interaction.replied) {
            await interaction.deferUpdate();
        }
        
        let message = "";
        if(stusrgame.id == userId) {
          message = `>  تم إلغاء التحدي بنجاح ${interaction.user} ! \n> || ${stusrgame} | ${wthusrgame} || `;
        } else {
          message = `>  تم رفض التحدي بنجاح ${interaction.user} ! \n> || ${stusrgame} | ${wthusrgame} || `;
        }
        
        clearChallengeTracking(stusrgame.id, wthusrgame.id);
        
        client.channels.cache.get(interaction.channel.id).messages.fetch(messageId).then(msg1 => msg1.edit({
          embeds: [],
          content: message,
          components: []
        })).catch(err => console.error(err));
        
        await game.findOneAndDelete({
          id: stusrgame.id,
          with: wthusrgame.id,
          msgID: messageId
        });
        
        await updatePlayerStatus(stusrgame.id, "no");
        await updatePlayerStatus(wthusrgame.id, "no");
    } catch (error) {
        console.error("Error in limitdesc decline:", error);
    } finally {
        setTimeout(() => {
            activeLocks.delete(globalLockKey);
        }, 1000);
    }
}

