if(interaction.customId.startsWith(`arkam1tklimitfarshow_`) || interaction.customId.startsWith(`arkam2tklimitfarshow_`)) {
    const messageId = interaction.customId.split('_')[1];
    const userId = interaction.user.id;
    
    if (isDoubleClick(interaction.message.id, userId, interaction.customId)) { return; }
    if (isProcessing(messageId, userId)) { return; }
    
    const cooldownCheck = checkCooldown(messageId, userId);
    if (!cooldownCheck.allowed) {
        return interaction.reply({ content: `⏳ انتظر ${cooldownCheck.remaining} ثانية`, ephemeral: true }).catch(() => {});
    }
    
    const globalLockKey = `limitfarshow_button_${userId}_${messageId}`;
    if (activeLocks.has(globalLockKey)) { return; }
    activeLocks.set(globalLockKey, true);
    
    try {
        await interaction.deferUpdate();
        
        let data = await takribi.findOne({ msgID: messageId });
        if(!data) { activeLocks.delete(globalLockKey); return; }
        
        if(data.role !== userId) {
            activeLocks.delete(globalLockKey);
            return interaction.followUp({ content: `**ليس دورك!** يرجى الانتظار حتى ينتهي اللاعب الآخر.`, ephemeral: true });
        }
        
        let datausr = await tkusr.findOne({ id: userId, msgID: messageId });
        if(!datausr) { activeLocks.delete(globalLockKey); return; }
        
        let gdata = await game.findOne({ id: data.idstusr, msgID: messageId });
        if(!gdata) { activeLocks.delete(globalLockKey); return; }
        
        let stusrgame = client.users.cache.get(data.idstusr);
        let wthusrgame = client.users.cache.get(gdata.with);
        if(!stusrgame || !wthusrgame) { activeLocks.delete(globalLockKey); return; }
        
        gdata.time = timestamp(moment(ms("90s")) + Date.now());
        await gdata.save();
        
        let urnum;
        if(interaction.customId.startsWith(`arkam1tklimitfarshow_`)) {
            let nextNum = nextNumbersQueue.get(userId); if (nextNum && nextNum.length > 0) { urnum = nextNum.shift(); if (nextNum.length === 0) nextNumbersQueue.delete(userId); } else { urnum = getRandomNumbertakribi(parseInt(data.number_smaller1), parseInt(data.number_smaller2)); }
        } else {
            let nextNum = nextNumbersQueue.get(userId); if (nextNum && nextNum.length > 0) { urnum = nextNum.shift(); if (nextNum.length === 0) nextNumbersQueue.delete(userId); } else { urnum = getRandomNumbertakribi(parseInt(data.number_greater1), parseInt(data.number_greater2)); }
        }
        
        const currentResult = parseInt(datausr.result || 0) + urnum;
        const maxNumber = parseInt(data.max_number);
        const distanceFromMax = Math.abs(currentResult - maxNumber);
        
        
        try {
            const gameMsg = await client.channels.cache.get(interaction.channel.id).messages.fetch(messageId).catch(() => null);
            if(gameMsg) {
                const currentEmbed = gameMsg.embeds[0];
                if(currentEmbed) {
                    const quickEmbed = new Discord.MessageEmbed(currentEmbed);
                    const playerFieldIndex = userId === stusrgame.id ? 0 : 1;
                    const fields = [...currentEmbed.fields];
                    const tempNumbers = [...(datausr.numbers || []), urnum];
                    const tempNumbersText = tempNumbers.join(" + ");
                    fields[playerFieldIndex] = {
                        name: fields[playerFieldIndex].name,
                        value: `> **Playing...**\n> ${tempNumbersText} = **${currentResult}** (بُعد **${distanceFromMax}**)`,
                        inline: fields[playerFieldIndex].inline
                    };
                    quickEmbed.fields = fields;
                    let btn1 = new MessageButton().setCustomId(`arkam1tklimitfarshow_${messageId}`).setLabel(`${data.number_smaller1} - ${data.number_smaller2}`).setStyle("PRIMARY").setDisabled(false);
                    let btnF = new MessageButton().setCustomId(`finishtklimitfarshow_${messageId}`).setLabel("Finish").setStyle("SUCCESS").setDisabled(false);
                    let btn2 = new MessageButton().setCustomId(`arkam2tklimitfarshow_${messageId}`).setLabel(`${data.number_greater1} - ${data.number_greater2}`).setStyle("PRIMARY").setDisabled(false);
                    await gameMsg.edit({ embeds: [quickEmbed], components: [new MessageActionRow().setComponents(btn1, btnF, btn2)] }).catch(() => {});
                }
            }
        } catch(e) {}
        
        datausr.numbers.push(urnum);
        datausr.result = currentResult;
        await datausr.save();
        
        
        if (currentResult > maxNumber) {
            data.number_players_done = parseInt(data.number_players_done) + 1;
            if(userId === stusrgame.id) data.player1Done = true;
            else if(userId === wthusrgame.id) data.player2Done = true;
            await data.save();

            
            try {
                const gameMsg = await client.channels.cache.get(interaction.channel.id).messages.fetch(messageId).catch(() => null);
                if(gameMsg) {
                    const currentEmbed = gameMsg.embeds[0];
                    if(currentEmbed) {
                        const doneEmbed = new Discord.MessageEmbed(currentEmbed);
                        const fields = [...currentEmbed.fields];
                        const doneFieldIdx = userId === stusrgame.id ? 0 : 1;
                        fields[doneFieldIdx] = {
                            name: fields[doneFieldIdx].name,
                            value: `> Done\n> ${datausr.numbers.join(" + ")} = **${currentResult}** (بُعد **${distanceFromMax}**)`,
                            inline: fields[doneFieldIdx].inline
                        };
                        doneEmbed.fields = fields;
                        let btn1 = new MessageButton().setCustomId(`arkam1tklimitfarshow_${messageId}`).setLabel(`${data.number_smaller1} - ${data.number_smaller2}`).setStyle("PRIMARY").setDisabled(false);
                        let btnF = new MessageButton().setCustomId(`finishtklimitfarshow_${messageId}`).setLabel("Finish").setStyle("SUCCESS").setDisabled(false);
                        let btn2 = new MessageButton().setCustomId(`arkam2tklimitfarshow_${messageId}`).setLabel(`${data.number_greater1} - ${data.number_greater2}`).setStyle("PRIMARY").setDisabled(false);
                        await gameMsg.edit({ embeds: [doneEmbed], components: [new MessageActionRow().setComponents(btn1, btnF, btn2)] }).catch(() => {});
                    }
                }
            } catch(e) {}

            if(parseInt(data.number_players_done) < 2) {
                await switchTurnLimitMode(data, interaction.channel.id, gdata.msgID, stusrgame, wthusrgame);
                resetClickCount(messageId, userId);
                unlockProcessing(messageId, userId);
            } else {
                await endGameLimitMode(data, interaction.channel.id, gdata.msgID, stusrgame, wthusrgame);
                setTimeout(async () => {
                    await processGameResultsLimitFar(data, gdata, interaction);
                    unlockProcessing(messageId, userId);
                    resetClickCount(messageId, userId);
                }, 300);
            }
        }
        
    } catch (error) {
        console.error("Error in limitfar show mode button click:", error);
    } finally {
        setTimeout(() => { activeLocks.delete(globalLockKey); }, 500);
    }
}

