async function processGameResultsLimitFar(data, gdata, interaction) {
    try {
        try {
            const channel = client.channels.cache.get(data.channelID);
            if (channel) {
                const msg = await channel.messages.fetch(data.msgID);
                await msg.edit({ content: `> جاري احتساب النتائج... ⏳`, components: [] });
            }
        } catch (err) { console.error("Error removing buttons:", err); }
        
        let datausrtk1 = await tkusr.findOne({ id: data.user1, msgID: data.msgID });
        let datausrtk2 = await tkusr.findOne({ id: data.user2, msgID: data.msgID });
        if(!datausrtk1 || !datausrtk2) return;
        
        let stusrgame = client.users.cache.get(data.user1);
        let wthusrgame = client.users.cache.get(data.user2);
        if(!stusrgame || !wthusrgame) return;
        
        let embed_finish_tk_game = new Discord.MessageEmbed()
            .setColor(serverColor)
            .setTitle("نتائج التحدي")
            .setDescription(`اقصى رقم : **${data.max_number}**`)
            .addFields({
                name: `${stusrgame.tag}`,
                value: `> ${datausrtk1.numbers.join(" + ") || ""} = **${datausrtk1.result || 0}**`
            }, {
                name: `${wthusrgame.tag}`,
                value: `> ${datausrtk2.numbers.join(" + ") || ""} = **${datausrtk2.result || 0}**`
            });
        
        let gameTypeText = data.gameType === 'limitfar_show'
            ? 'الحد الأبعد (اظهار ارقام) 🔢'
            : 'الحد الأبعد الطبيعي 🎯';
        
        const player1Result = parseInt(datausrtk1.result || 0);
        const player2Result = parseInt(datausrtk2.result || 0);
        const maxNumber = parseInt(data.max_number);
        
        
        const player1Distance = Math.abs(player1Result - maxNumber);
        const player2Distance = Math.abs(player2Result - maxNumber);
        
        let resultMessage = "";
        let winner, loser, isDraw = false;
        
        if(player1Distance > player2Distance) {
            winner = stusrgame;
            loser = wthusrgame;
            resultMessage = `** نتيجة اللعبة :**\n\n الـ ** فـآئز ** : <@${winner.id}> \`-\` بـ ** مجموع ** : \`${player1Result}\`\n\nالـ ** خـآسر ** : <@${loser.id}> \`-\` بـ ** مجموع ** : \`${player2Result}\`\n\nالـ ** لعبة ** : الـ\`${gameTypeText}\` .! \`-\` الـ **💰 - مبلغ** : \`${parseInt(gdata.coins).toLocaleString()}\` .!`;
        } else if(player2Distance > player1Distance) {
            winner = wthusrgame;
            loser = stusrgame;
            resultMessage = `** نتيجة اللعبة :**\n\n الـ ** فـآئز ** : <@${winner.id}> \`-\` بـ ** مجموع ** : \`${player2Result}\`\n\nالـ ** خـآسر ** : <@${loser.id}> \`-\` بـ ** مجموع ** : \`${player1Result}\`\n\nالـ ** لعبة ** : الـ\`${gameTypeText}\` .! \`-\` الـ **💰 - مبلغ** : \`${parseInt(gdata.coins).toLocaleString()}\` .!`;
        } else {
            isDraw = true;
            resultMessage = `** نتيجة اللعبة :**\n\n الـ ** تعادل ** : <@${stusrgame.id}> & <@${wthusrgame.id}>\n\nالـ ** لعبة ** : الـ\`${gameTypeText}\` .! \`-\` الـ **💰 - مبلغ** : \`${parseInt(gdata.coins).toLocaleString()}\` .!`;
        }
        
        const channel = client.channels.cache.get(data.channelID);
        if (!channel) { console.error(`Channel not found: ${data.channelID}`); return; }
        
        let retryCount = 0;
        const maxRetries = 3;
        const fetchAndEditFinalMessage = async () => {
            try {
                const abortController = new AbortController();
                const timeoutId = setTimeout(() => abortController.abort(), 15000);
                const msg1 = await channel.messages.fetch(data.msgID, { signal: abortController.signal });
                clearTimeout(timeoutId);
                await msg1.edit({ embeds: [embed_finish_tk_game], content: resultMessage, components: [] });
            } catch (err) {
                if (err.name === 'AbortError' || err.code === 'ECONNRESET' || (err.message && err.message.includes('socket hang up'))) {
                    retryCount++;
                    if (retryCount <= maxRetries) {
                        const delay = Math.min(1000 * Math.pow(1.5, retryCount) + Math.random() * 1000, 10000);
                        setTimeout(fetchAndEditFinalMessage, delay);
                        return;
                    }
                }
                console.error("Error displaying final result after retries:", err);
            }
        };
        fetchAndEditFinalMessage();
        
        if (typeof allbetssend === 'function' && typeof allbetschannelid !== 'undefined') {
            try {
                allbetssend(gameTypeText, winner || stusrgame, loser || wthusrgame, isDraw ? 1 : 0, gdata.coins);
                if (allbetschannelid) {
                    const allBetsChannel = client.channels.cache.get(allbetschannelid);
                    if (allBetsChannel) {
                        let rc = 0;
                        const mr = 3;
                        const sendWithRetry = async (content) => {
                            try { await allBetsChannel.send(content); } catch (err) {
                                if ((err.name === 'AbortError' || err.code === 'ECONNRESET' || (err.message && err.message.includes('socket hang up'))) && rc < mr) {
                                    rc++;
                                    const delay = Math.min(1000 * Math.pow(1.5, rc) + Math.random() * 1000, 10000);
                                    setTimeout(() => sendWithRetry(content), delay);
                                }
                            }
                        };
                        sendWithRetry({ embeds: [embed_finish_tk_game] });
                        if (typeof linelineline !== 'undefined') {
                            setTimeout(() => { sendWithRetry({ files: [linelineline] }); }, 1000);
                        }
                    }
                }
            } catch (error) { console.error("Error recording to all bets channel:", error); }
        }
        
        if (isDraw) {
            await updatePlayerStatsForTie(stusrgame.id, wthusrgame.id);
        } else {
            await updatePlayerStats(loser.id, winner.id, gdata.coins);
        }
        
        await cleanupGameData(data.msgID, gdata.msgID, stusrgame.id, wthusrgame.id);
    } catch (error) {
        console.error("Error processing game results in limitfar mode:", error);
    }
}

