function getRandomNumbertakribi(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
}

client.on("messageCreate", async message => {
    if (message.channel.parentId === "1478722657661747220") return;
	if(message.channel.id == GAME_CHANNEL_ID) return;

	if(message.content.split(" ")[0] == "فرند" || message.content.split(" ")[0] == "Friend") {
		let args = message.content.split(" ");
		if(!args[1]) return message.reply({
			content: `> يرجى تحديد عضو لإضافته كصديق!`
		});
		let user = message.mentions.users.first() || message.guild.members.cache.find(s => s.id == args[1]);
		if(!user) return message.reply({
			content: `\`❎\` **لم أستطع العثور على هذا الشخص!**`
		});
		if(user.id === message.author.id) return message.reply({
			content: "بتبوظ شرع ربنا انت؟"
		});
		let data = await db.findOne({
			id: message.author.id
		});
		if(data.blocked && data.blocked.includes(user.id)) {
			let unblockPrompt = new Discord.MessageEmbed().setColor(serverColor).setDescription(`**> هذا الشخص بعطائه بلوك! لكي تتمكن من إضافته كصديق، يجب عليك فك الحظر عنه أولاً.**`);
			return message.reply({
				embeds: [unblockPrompt]
			});
		}
		if(data.friends.includes(user.id)) {
			return message.reply({
				content: `> ${user} موجود بالفعل في قائمة أصدقائك!`
			});
		}
		data.friends.push(user.id);
		await data.save();
		let embed = new Discord.MessageEmbed().setColor(serverColor).setDescription(`> تمت إضافة ${user} كصديق بنجاح!`);
		message.reply({
			embeds: [embed]
		});
	}
});

