client.on("messageCreate", async message => {
    if (message.channel.parentId === "1478722657661747220") return;
	if(message.channel.id == GAME_CHANNEL_ID) return;
	if(isBlacklisted(message.author.id)) return;
	if(message.content.toLowerCase() === "بري" || message.content.toLowerCase() === "بريميوم") {
		let data = await db.findOne({
			id: message.author.id
		});
		if(!data) {
			data = await db.create({
				id: message.author.id,
				coins: 0,
				status_playing: 'no',
				premiumExpires: null
			});
		}
		if(ispremiumed(message.author.id)) {
			let now = moment();
			let expires = moment(data.premiumExpires);
			let duration = moment.duration(expires.diff(now));
			let days = Math.floor(duration.asDays());
			let hours = duration.hours();
			let minutes = duration.minutes();
			return message.reply(`باقي من البريميوم ${days} أيام، ${hours} ساعات، و ${minutes} دقائق.`);
		}
		if(activeOperations.has(message.author.id)) {
			return message.reply('لديك عملية ترقية قيد التنفيذ بالفعل.');
		}
		
		if(data.status_playing === "yes") {
			return message.reply('⚠️ لا يمكنك الترقية أثناء اللعب! يرجى إنهاء التحدي أولاً.');
		}
		
		
		if (activeWithdrawals.has(message.author.id) || (isProcessing && currentWithdrawalUser === message.author.id) || data.isOnWithdrawal === "yes" || data.withdrawing === true) {
			return message.reply({ content: '**> لا يمكنك شراء البريميوم أثناء عملية سحب**' });
		}
		
		if(data.isontransfersure === "yes" || data.isProcessingTransfer === true) {
			return message.reply('⚠️ لديك عملية تحويل نشطة! لا يمكنك الترقية حالياً.');
		}
		
		if(activeBankOperations.has(message.author.id)) {
			return message.reply('⚠️ لديك عملية بنك نشطة! لا يمكنك الترقية حالياً.');
		}
		
		const pendingWithdrawal = await S7b.findOne({ 
			user: message.author.id,
			status: 'pending'
		});
		if(pendingWithdrawal) {
			return message.reply('⚠️ لديك طلب سحب قيد المعالجة! لا يمكنك الترقية حالياً.');
		}
		let embed = new MessageEmbed().setColor(serverColor).setTitle('ترقية إلى بريميوم').setDescription('هل تريد الترقية إلى بريميوم مقابل 1500000؟ اضغط على "تأكيد" للمتابعة أو "إلغاء" للإلغاء.');
		let buttonConfirm = new MessageButton().setCustomId('confirm_premium').setLabel('تأكيد').setStyle('SUCCESS');
		let buttonCancel = new MessageButton().setCustomId('cancel_premium').setLabel('إلغاء').setStyle('DANGER');
		let row = new MessageActionRow().addComponents(buttonConfirm, buttonCancel);
		const msg = await message.reply({
			embeds: [embed],
			components: [row]
		});
		activeOperations.add(message.author.id);
		
		await db.updateOne({ id: message.author.id }, { $set: { isPurchasingPremium: true } });
		const filter = i => (i.customId === 'confirm_premium' || i.customId === 'cancel_premium') && i.user.id === message.author.id;
		const collector = msg.createMessageComponentCollector({
			filter,
			time: 60000
		});
		collector.on('end', async collected => {
			if(!collected.size) {
				activeOperations.delete(message.author.id);
				
				await db.updateOne({ id: message.author.id }, { $set: { isPurchasingPremium: false } });
				await msg.edit({
					content: 'تم إلغاء عملية الترقية بسبب عدم التفاعل.',
					components: []
				});
			}
		});
		collector.on('collect', async i => {
			if(i.customId === 'confirm_premium') {
				const freshData = await db.findOne({ id: message.author.id });
				
				if(freshData.status_playing === "yes") {
					activeOperations.delete(message.author.id);
					return i.update({
						content: '❌ فشلت الترقية!  أنت تلعب حالياً.',
						embeds: [],
						components: []
					});
				}
				
				if(freshData.isontransfersure === "yes" || freshData.isProcessingTransfer === true) {
					activeOperations.delete(message.author.id);
					return i.update({
						content: '❌ فشلت الترقية! تم اكتشاف عملية تحويل نشطة.',
						embeds: [],
						components: []
					});
				}
				
				if(activeBankOperations.has(message.author.id)) {
					activeOperations.delete(message.author.id);
					return i.update({
						content: '❌ فشلت الترقية! تم اكتشاف عملية بنك نشطة.',
						embeds: [],
						components: []
					});
				}
				
				const pendingWithdrawal = await S7b.findOne({ 
					user: message.author.id,
					status: 'pending'
				});
				if(pendingWithdrawal) {
					activeOperations.delete(message.author.id);
					return i.update({
						content: '❌ فشلت الترقية! تم اكتشاف طلب سحب قيد المعالجة.',
						embeds: [],
						components: []
					});
				}
				
				if(freshData.coins >= 2000000) {
					freshData.coins -= 2000000;
					freshData.premiumExpires = moment().add(7, 'days').toDate();
					await freshData.save();
					addTopremium(message.author.id);
					await i.update({
						content: 'تمت الترقية إلى بريميوم بنجاح!',
						embeds: [],
						components: []
					});
				} else {
					await i.update({
						content: 'ليس لديك رصيد كافي للترقية.',
						embeds: [],
						components: []
					});
				}
			} else if(i.customId === 'cancel_premium') {
				await i.update({
					content: 'تم إلغاء الترقية.',
					embeds: [],
					components: []
				});
			}
			activeOperations.delete(message.author.id);
			
			await db.updateOne({ id: message.author.id }, { $set: { isPurchasingPremium: false } });
		});
	}
});
const claimedBoxes = new Set();
const BOX_DELAY_MS = 1000; 

client.on("messageCreate", async message => {
    
    if (message.channel.parentId === "1478722657661747220") return;
    
    
    if (message.content.startsWith("!box") && isOwnerOrGranted(message.author.id, '!box')) {
        const args = message.content.split(" ");
        let boxCount = 1;
        
        if (args[1] && !isNaN(args[1])) {
            boxCount = parseInt(args[1]);
            if (boxCount < 1) boxCount = 1;
            if (boxCount > 50) boxCount = 50;
        }

        
        for (let i = 0; i < boxCount; i++) {
            await sendBox(message.channel.id);
            if (i < boxCount - 1) await delay(BOX_DELAY_MS);
        }
    }
});

client.on("interactionCreate", async interaction => {
    if (!interaction.isButton()) return;

    const buttonId = interaction.customId;
    if (buttonId.startsWith("claim_box_")) {
        const messageId = buttonId.split("_")[2];

        if (claimedBoxes.has(messageId)) {
            return interaction.reply({ content: "❌ This box has already been claimed!", ephemeral: true });
        }

        claimedBoxes.add(messageId);
        
        const reward = Math.floor(Math.random() * (2000000 - 500000 + 1)) + 500000;
        
        const updatedRow = new MessageActionRow().addComponents(
            new MessageButton()
                .setCustomId("claimed_box")
                .setLabel("👌 Claimed")
                .setStyle("SECONDARY")
                .setDisabled(true)
        );

        await interaction.message.edit({
            content: `🎉 Done claimed the box by <@${interaction.user.id}>! 🎁`,
            components: [updatedRow]
        });

        let data = await db.findOne({ id: interaction.user.id });
        if (!data) {
            data = await db.create({ id: interaction.user.id, coins: 0, status_playing: "no" });
        }
        data.coins += reward;
        await data.save();

        interaction.reply({
            content: `> <@${interaction.user.id}> حصلت على **$${reward.toLocaleString()}** كوينز! 🎊`,
            ephemeral: true
        });
    }
});

