async function sendBox(channelId) {
    const channel = client.channels.cache.get(channelId);
    if (!channel) return;

    const row = new MessageActionRow().addComponents(
        new MessageButton()
            .setCustomId(`claim_box_${Date.now()}`)
            .setLabel("🚀 Claim")
            .setStyle("SUCCESS")
    );

    await channel.send({
        content: "🎁 To claim the box press on the button:",
        components: [row]
    });
}

