const TOP_LOG_CHANNEL_ID = "1456498498831646886";

function convertToShortNumber(number) {
  if(number >= 1e12) return (number / 1e12).toFixed(1) + 'T';
  if(number >= 1e9) return (number / 1e9).toFixed(1) + 'B';
  if(number >= 1e6) return (number / 1e6).toFixed(1) + 'M';
  if(number >= 1e3) return (number / 1e3).toFixed(1) + 'K';
  return number.toString();
}

client.on("messageCreate", async (message) => {
    if (message.channel.parentId === "1478722657661747220") return;
    if (message.author.bot || message.channel.id == GAME_CHANNEL_ID) return;

    const content = message.content.split(" ");
    const command = content[0].toLowerCase();
    if (command !== "توب" && command !== "top" && command !== "Top") return;

    const isOwner = isOwnerOrGranted(message.author.id, 'top');

    try {
        const money = await db.find({}).sort({ coins: -1 }).select("id coins").limit(30).lean();
        let totalCoins = 0;
        let num = 0;
        let finalLb = "";
        let displayedUsers = [];

        for (let i = 0; i < money.length; i++) {
            const user = client.users.cache.get(money[i].id);
            if (!user) continue;

            const isHidden = hiddenUsers.has(money[i].id);

            
            if (isHidden && !isOwner) continue;

            displayedUsers.push({
                user: user,
                coins: money[i].coins,
                isHidden: isHidden
            });
            
            if (displayedUsers.length >= 10) break;
        }

        for (let userData of displayedUsers) {
            totalCoins += parseInt(userData.coins);
        }

        for (let i = 0; i < displayedUsers.length; i++) {
            const userData = displayedUsers[i];
            
            const formattedCoins = convertToShortNumber(parseInt(userData.coins));
            const hiddenIndicator = (userData.isHidden && isOwner) ? " 🔒" : "";
            
            if (i === 0) {
                finalLb += `**👑 <@${userData.user.id}>**${hiddenIndicator} **\`-\`** **${formattedCoins}**\n`;
            } else {
                finalLb += `**#${i + 1} <@${userData.user.id}>**${hiddenIndicator} **\`-\`** **${formattedCoins}**\n`;
            }
        }
                
        try {
            
        } catch (error) {
            console.error("Error sending top command log:", error);
        }

        const embed = new Discord.MessageEmbed()
            .setAuthor({ name: `توب رصيد` })
            .setColor(serverColor)
            .setThumbnail(message.guild.iconURL())
            .setDescription(finalLb)
            .setFooter({ 
                text: isOwner ? 
                    `${message.guild.name} | ${convertToShortNumber(totalCoins)} | 🔒 = مخفي` : 
                    `${message.guild.name} | ${convertToShortNumber(totalCoins)}`
            })
            .setTimestamp();

        message.reply({ embeds: [embed] });
        
    } catch (error) {
        console.error("Error in top command:", error);
        message.reply("❌ حدث خطأ أثناء جلب البيانات");
    }
});

