function createBoardComponents(board, lastMove = null, disableAll = false) {
  const rows = [];
  
  for (let i = 0; i < 3; i++) {
    const row = new MessageActionRow();
    for (let j = 0; j < 3; j++) {
      const label = board[i][j] || '-';
      let style = label === '❌' || label === '⭕' ? 'SECONDARY' : 'PRIMARY';
      
      if (lastMove && lastMove[0] === i && lastMove[1] === j) {
        style = 'DANGER';
      }
      
      row.addComponents(
        new MessageButton()
          .setCustomId(`move_${i}_${j}`)
          .setLabel(label.toString())
          .setStyle(style)
          .setDisabled(disableAll || label !== '-') 
      );
    }
    rows.push(row);
  }
  return rows;
}

async function startGame(message, playerX, playerO, bet) {
  const board = Array(3).fill().map(() => Array(3).fill('-'));
  const embed = new MessageEmbed()
    .setTitle('لعبة أكس او')
    .setDescription(`**النتيجة:** لم تنته بعد.\n**اللاعب الحالي:** <@${playerX.id}>`)
    .addFields({
      name: 'الرهان',
      value: `${bet} عملة`
    })
    .setFooter({
      text: 'Vip Casino'
    });
    
  await message.edit({
    content: " ",
    embeds: [embed],
    components: createBoardComponents(board, null, false)
  });
  
  const gamedata = new xoGame({
    messageId: message.id,
    playerX: playerX.id,
    playerO: playerO.id,
    currentPlayer: playerX.id,
    board: board,
    bet: bet
  });
  await gamedata.save();
}

async function makeMove(user, row, col, interaction) {
  const gamedb = await xoGame.findOne({
    messageId: interaction.message.id
  });
  
  if (!gamedb) {
    await interaction.reply({
      content: 'لم يتم العثور على اللعبة.',
      ephemeral: true
    });
    return;
  }
  
  if (gamedb.currentPlayer !== user.id) {
    await interaction.reply({
      content: 'ليس دورك للعب.',
      ephemeral: true
    });
    return;
  }
  
  if (gamedb.board[row][col] !== '-') {
    await interaction.reply({
      content: 'هذا المكان مشغول بالفعل.',
      ephemeral: true
    });
    return;
  }
  
  const gamedata = await game.findOne({
    msgID: gamedb.messageId
  });
  
  if (!gamedata) {
    await interaction.reply({
      content: 'لم يتم العثور على بيانات اللعبة العامة.',
      ephemeral: true
    });
    return;
  }
  
  gamedata.time = timestamp(moment(ms("90s")) + Date.now());
  await gamedata.save();
  
  gamedb.board[row][col] = gamedb.currentPlayer === gamedb.playerX ? '❌' : '⭕';
  gamedb.currentPlayer = gamedb.currentPlayer === gamedb.playerX ? gamedb.playerO : gamedb.playerX;
  await gamedb.save();
  
  const result = checkWinner(gamedb.board);
  const disableAll = (result === "TIE" || result === "❌" || result === "⭕");
  
  const playerX = await db.findOne({
    id: gamedb.playerX
  });
  
  const playerO = await db.findOne({
    id: gamedb.playerO
  });
  
  const bet = gamedb.bet;
  
  await sendBoard(interaction.channel, gamedb.board, gamedb.messageId, result, playerX, playerO, bet, disableAll);
  
  if (result === 'TIE') {
    await interaction.reply({
      content: 'النتيجة: تعادل',
      ephemeral: true
    });
    await updatePlayerBalances(gamedb, result);
  } else if (result === "❌" || result === "⭕") {
    await interaction.reply({
      content: `النتيجة: ${result}`,
      ephemeral: true
    });
    await updatePlayerBalances(gamedb, result);
  } else {
    await interaction.reply({
      content: `الآن دور اللاعب التالي.`,
      ephemeral: true
    });
  }
}

function checkWinner(board) {
  const winningCombinations = [
    
    [[0, 0], [0, 1], [0, 2]],
    [[1, 0], [1, 1], [1, 2]],
    [[2, 0], [2, 1], [2, 2]],
    
    [[0, 0], [1, 0], [2, 0]],
    [[0, 1], [1, 1], [2, 1]],
    [[0, 2], [1, 2], [2, 2]],
    
    [[0, 0], [1, 1], [2, 2]],
    [[0, 2], [1, 1], [2, 0]]
  ];
  
  for (const combination of winningCombinations) {
    const [a, b, c] = combination;
    const cellA = board[a[0]][a[1]];
    const cellB = board[b[0]][b[1]];
    const cellC = board[c[0]][c[1]];
    
    
    if (cellA !== '-' && cellA === cellB && cellA === cellC) {
      return cellA;
    }
  }
  
  
  const isBoardFull = board.every(row => row.every(cell => cell !== '-'));
  return isBoardFull ? 'TIE' : null;
}

async function sendBoard(channel, board, messageId, result = null, playerX = null, playerO = null, bet = 'لم يتم تحديد المبلغ', disableAll = false) {
  const gamedb = await xoGame.findOne({
    messageId: messageId
  });
  
  const rows = createBoardComponents(board, null, disableAll);
  
  const embed = new MessageEmbed()
    .setTitle('لعبة XO')
    .setFooter({
      text: 'Vip Casino'
    })
    .addFields({
      name: 'الرهان',
      value: `${bet} عملة`
    });
  
  if (result === 'TIE') {
    embed.setDescription(`🤝 **تعادل!** كلاكما حصلتم على نفس النتيجة\n\n💰 **استرجاع المبلغ:** \`${bet.toLocaleString()}\` كوينز`);
    allbetssendxo("اكس او", playerX.id, playerO.id, 1, bet);
  } else if (result === '❌' || result === '⭕') {
    const winner = result === '❌' ? playerX : playerO;
    const loser = result === '❌' ? playerO : playerX;
    const winnerSymbol = result === '❌' ? '❌' : '⭕';
    const loserSymbol = result === '❌' ? '⭕' : '❌';
    
    embed.setDescription(`🎉 **الـ فائـز:** <@${winner.id}> **بـ:** \`${winnerSymbol}\`\n\n💔 **الـ خاسر:** <@${loser.id}> **بـ:** \`${loserSymbol}\`\n\n💰 **المبلغ:** \`${bet.toLocaleString()}\` كوينز`);
    allbetssendxo("اكس او", playerX.id, playerO.id, 0, bet);
  } else {
    embed.setDescription(`**النتيجة:** لم تنته بعد.\n**اللاعب الحالي:** <@${gamedb.currentPlayer === playerX.id ? playerX.id : playerO.id}>`);
  }
  
  
  let finalContent = '';
  if (result === 'TIE') {
    finalContent = `** نتيجة اللعبة :**\n\n الـ ** تعادل ** : <@${playerX.id}> & <@${playerO.id}>\n\nالـ ** لعبة ** : الـ\`اكس او\` .! \`-\` الـ **💰 - مبلغ** : \`${parseInt(bet).toLocaleString()}\` .!`;
  } else if (result === '❌' || result === '⭕') {
    const winner = result === '❌' ? playerX : playerO;
    const loser = result === '❌' ? playerO : playerX;
    finalContent = `** نتيجة اللعبة :**\n\n الـ ** فـآئز ** : <@${winner.id}> \`-\` بـ ** مجموع ** : \`${parseInt(bet).toLocaleString()}\`\n\nالـ ** خـآسر ** : <@${loser.id}> \`-\` بـ ** مجموع ** : \`${parseInt(bet).toLocaleString()}\`\n\nالـ ** لعبة ** : الـ\`اكس او\` .! \`-\` الـ **💰 - مبلغ** : \`${parseInt(bet).toLocaleString()}\` .!`;
  }
  
  try {
    const message = await channel.messages.fetch(messageId);
    await message.edit({
      content: finalContent || null,
      embeds: (result === 'TIE' || result === '❌' || result === '⭕') ? [] : [embed],
      components: rows
    });
  } catch (error) {
    console.error('Error sending board:', error);
  }
}

