function updateButtonStyles(rows, clickedButtonId, correctButtonId, disableall = false) {
	return rows.map(row => {
		const newRow = new MessageActionRow();
		row.components.forEach(button => {
			if(button.customId === clickedButtonId) {
				newRow.addComponents(new MessageButton().setCustomId('clicked' + button.customId).setEmoji(button.customId === correctButtonId ? '<:top1:1333424048910241834>' : '💥').setStyle(button.customId === correctButtonId ? 'SUCCESS' : 'DANGER').setDisabled(true));
			} else if(button.customId.startsWith("clicked")) {
				newRow.addComponents(new MessageButton().setCustomId(button.customId).setEmoji('💥').setStyle('DANGER').setDisabled(true));
			} else {
				newRow.addComponents(new MessageButton().setCustomId(button.customId).setEmoji('<:GoldenDice:1344298696166084680>').setStyle('SECONDARY').setDisabled(disableall));
			}
		});
		return newRow;
	});
}

