async function safeFetchChannel(channelId) {
	try {
		const channel = await client.channels.fetch(channelId);
		return channel;
	} catch (error) {
		if(error.code === 10003) {
			return null;
		} else {
			throw error; 
		}
	}
}
async function safeFetchMessage(channelId, messageId) {
	try {
		const channel = await client.channels.fetch(channelId);
		if(!channel.isText()) return null;
		const message = await channel.messages.fetch(messageId);
		return message;
	} catch (error) {
		if(error.code === 10008) {
			return null;
		} else {
			throw error; 
		}
	}
}

async function clearAllMessagesConsole(channel) {
	let a = 1
	do {
		try {
			fetched = await channel.messages.fetch({
				limit: 100
			});
			await channel.bulkDelete(fetched);
			fetched = await channel.messages.fetch({
				limit: 100
			});
			a = fetched.size
		} catch (error) {
			console.error('Error bulk deleting', error);
			a = 0
		}
	} while(a >= 1)
}

function determineWinner(authorChoice, opponentChoice) {
	if(authorChoice === opponentChoice) return 'draw';
	if(
		(authorChoice === 'حجرة' && opponentChoice === 'مقص') || (authorChoice === 'مقص' && opponentChoice === 'ورقة') || (authorChoice === 'ورقة' && opponentChoice === 'حجرة')) {
		return 'author';
	} else {
		return 'opponent';
	}
}

    
