    function parseTime(input) {
    const timeUnits = {
        s: 1000,           
        m: 1000 * 60,       
        h: 1000 * 60 * 60,   
        d: 1000 * 60 * 60 * 24,  
        mo: 1000 * 60 * 60 * 24 * 30, 
        y: 1000 * 60 * 60 * 24 * 365  
    };

    const regex = /^(\d+)(s|m|h|d|mo|y)$/; 
    const match = input.match(regex);

    if (!match) {
        throw new Error("صيغة الوقت غير صحيحة. استخدم: 1s, 1m, 1h, 1d, 1mo, 1y.");
    }

    const value = parseInt(match[1]);
    const unit = match[2];

    return value * timeUnits[unit]; 
}
    
    function parseMoney(input) {
    const moneyUnits = {
        k: 1000,  
        m: 1000000,     
        b: 1000000000   
    };

    const regex = /^(\d+)(k|m|b)$/; 
    const match = input.match(regex);

    if (!match) {
        throw new Error("صيغة الفلوس غير صحيحة. استخدم: 1k, 1m, 1b.");
    }

    const value = parseInt(match[1]); 
    const unit = match[2];          

    return value * moneyUnits[unit]; 
}
    
