 client.on("messageCreate", async (message) => {
    if (message.channel.parentId === "1478722657661747220") return;
    if (!message.content.startsWith("!list") || !isOwnerOrGranted(message.author.id, '!list')) return;
    if (!message.guild) return;

    const codes = JSON.parse(fs.readFileSync("./codes.json", "utf8"));

    const expiredCodes = Object.entries(codes).filter(([code, data]) => {
        return data.usesLeft <= 0 || Date.now() > data.expiry;
    });

    if (expiredCodes.length === Object.entries(codes).length) {
        return message.reply("❌ لا توجد أكواد صالحة حاليًا في النظام.");
    }

    if (Object.keys(codes).length === 0) {
        return message.reply("❌ لا توجد أكواد حاليًا في النظام.");
    }

    const embed = new Discord.MessageEmbed()
        .setColor(serverColor)
        .setTitle("📋 قائمة الأكواد المتوفرة")
        .setDescription("هذه هي الأكواد الحالية المتوفرة مع معلوماتها:")
        .setFooter({ text: message.guild.name, iconURL: message.guild.iconURL({ dynamic: true }) })
        .setTimestamp();

    for (const [code, data] of Object.entries(codes)) {
        if (data.usesLeft <= 0 || Date.now() > data.expiry) continue;

        const expiryDate = new Date(data.expiry).toLocaleString("en-US", { timeZone: "Africa/Cairo" });
        const usedBy = data.usedBy ? data.usedBy.length : 0;

        embed.addField(
            `📝 الكود: **${code}**`,
            `💰 **الكمية**: ${data.amount.toLocaleString()}  
            🕒 **ينتهي في**: ${expiryDate}  
            ✅ **الاستخدامات المتبقية**: ${data.usesLeft}  
            👥 **عدد المستخدمين الذين فعَّلوه**: ${usedBy}`,
            false
        );
    }

    message.reply({ embeds: [embed] });
});
    
    client.on("messageCreate", async (message) => {
        if (message.channel.parentId === "1478722657661747220") return;
    if (!message.content.startsWith("!resetcodes") || !isActiveOwner(message.author.id)) return;
    if (!message.guild) return;

    fs.writeFileSync("./codes.json", JSON.stringify({}, null, 2), "utf8");

    const embed = new Discord.MessageEmbed()
        .setColor(serverColor)
        .setTitle("🗑️ إعادة تعيين الأكواد")
        .setDescription("✅ تم مسح جميع الأكواد بنجاح!")
        .setFooter({ text: message.guild.name, iconURL: message.guild.iconURL({ dynamic: true }) })
        .setTimestamp();

    return message.reply({ embeds: [embed] });
});

client.on('messageCreate', async (message) => {
    if (message.content === `!teams`) {
      if (!isOwnerOrGranted(message.author.id, '!resetcodes')) return;
  
      const embed = new Discord.MessageEmbed()
        .setTitle(`قم بانشاء تيمك الخاص`)
        .setColor(serverColor)
        .setImage('https://cdn.discordapp.com/banners/1121195275315327138/c8f134da7036887f41397b080858fc35.png?size=1024')
        .setTimestamp()
        .setFooter({
          text: message.guild.name,
          iconURL: message.guild.iconURL()
        });
  
      const createTeamButton = new Discord.MessageButton()
        .setCustomId('create_teamttt')
        .setLabel('➕ إنشاء فريق')
        .setStyle("SUCCESS");
  
      const teamInfoButton = new Discord.MessageButton()
        .setCustomId('team_info')
        .setLabel('ℹ️ معلومات الفريق')
        .setStyle("PRIMARY");
  
      const row = new Discord.MessageActionRow().addComponents(createTeamButton, teamInfoButton);
  
      message.delete();
      await message.channel.send({ embeds: [embed], components: [row] });
    }
  });
  
  client.on('interactionCreate', async (interaction) => {
    if (!interaction.isButton()) return;
  
    if (interaction.customId === 'create_teamttt') {
      const existingTeam = await Team.findOne({
        $or: [
          { ownerid: interaction.user.id },
          { players: interaction.user.id }
        ]
      });
  
      if (existingTeam) {
        return interaction.reply({
          content: existingTeam.ownerid === interaction.user.id
            ? '❌ **أنت أونر فريق بالفعل، لا يمكنك إنشاء فريق جديد!**'
            : '❌ **أنت بالفعل عضو في فريق، لا يمكنك إنشاء فريق جديد!**',
          ephemeral: true
        });
      }
  
      const modal = new Discord.Modal()
        .setCustomId('create_team_modal')
        .setTitle('إنشاء فريق جديد');
  
      const teamTagInput = new Discord.TextInputComponent()
        .setCustomId('team_tag')
        .setLabel('ادخل Tag الكلان (2-4 أحرف)')
        .setStyle("SHORT")
        .setRequired(true)
        .setPlaceholder('مثال: ABC');
  
      const teamPlayersInput = new Discord.TextInputComponent()
        .setCustomId('team_players')
        .setLabel('أدخل أعضاء الفريق (اختياري)')
        .setStyle("SHORT")
        .setRequired(false)
        .setPlaceholder('ID1,ID2,ID3 (بحد أقصى 3)');
  
      const teamAdminInput = new Discord.TextInputComponent()
        .setCustomId('team_admin')
        .setLabel('أدخل ID المشرف (اختياري)')
        .setStyle("SHORT")
        .setRequired(false)
        .setPlaceholder('مثال: 123456789');
  
      const row1 = new Discord.MessageActionRow().addComponents(teamTagInput);
      const row2 = new Discord.MessageActionRow().addComponents(teamPlayersInput);
      const row3 = new Discord.MessageActionRow().addComponents(teamAdminInput);
  
      modal.addComponents(row1, row3, row2);
  
      await interaction.showModal(modal);
    }
  });
  
  client.on('interactionCreate', async (interaction) => {
    if (interaction.customId === 'create_team_modal') {
      const teamTag = interaction.fields.getTextInputValue('team_tag').toUpperCase();
      const teamPlayers = interaction.fields.getTextInputValue('team_players') || '';
      const teamAdmin = interaction.fields.getTextInputValue('team_admin') || '';
  
      if (teamTag.length < 2 || teamTag.length > 4) {
        return interaction.reply({ content: '❌ **الـTag يجب أن يكون بين 2 و 4 أحرف فقط.**', ephemeral: true });
      }
  
      const existingTag = await Team.findOne({ teamtag: teamTag });
      if (existingTag) {
        return interaction.reply({ content: '❌ **هذا الـTag محجوز بالفعل، اختر واحدًا آخر.**', ephemeral: true });
      }

      
      const creatorExistingTeam = await Team.findOne({
        $or: [{ ownerid: interaction.user.id }, { players: interaction.user.id }]
      });
      if (creatorExistingTeam) {
        return interaction.reply({
          content: creatorExistingTeam.ownerid === interaction.user.id
            ? '❌ **أنت أونر فريق بالفعل، لا يمكنك إنشاء فريق جديد!**'
            : '❌ **أنت بالفعل عضو في فريق، لا يمكنك إنشاء فريق جديد!**',
          ephemeral: true
        });
      }
  
      let playersArray = [];
      if (teamPlayers.trim() !== '') {
        playersArray = teamPlayers.split(',').map(id => id.trim());
        if (playersArray.length > 3) {
          return interaction.reply({ content: '❌ **يمكنك إضافة 3 أعضاء كحد أقصى.**', ephemeral: true });
        }
        if (!playersArray.every(id => /^\d+$/.test(id))) {
          return interaction.reply({ content: '❌ **أحد معرفات الأعضاء غير صالح.**', ephemeral: true });
        }
        
        for (const pid of playersArray) {
          const pidTeam = await Team.findOne({ $or: [{ ownerid: pid }, { players: pid }] });
          if (pidTeam) {
            return interaction.reply({ content: `❌ **<@${pid}> بالفعل عضو في فريق آخر، لا يمكن إضافته!**`, ephemeral: true });
          }
        }
      }
  
      if (teamAdmin) {
        if (!/^\d+$/.test(teamAdmin)) {
          return interaction.reply({ content: '❌ **ID المشرف غير صالح.**', ephemeral: true });
        }
        if (!playersArray.includes(teamAdmin)) {
          return interaction.reply({ content: '❌ **يجب أن يكون المشرف أحد أعضاء الفريق.**', ephemeral: true });
        }
      }
  
      const newTeam = new Team({
        teamtag: teamTag,
        ownerid: interaction.user.id,
        admins: teamAdmin ? [teamAdmin] : [],
        players: playersArray
      });
  
      await newTeam.save();
  
      interaction.reply({
        content: `✅ **تم إنشاء فريقك بنجاح!**\n\n**🔹 Tag:** \`${teamTag}\`\n**👑 الأونر:** <@${interaction.user.id}>\n**🛠 المشرف:** ${teamAdmin ? `<@${teamAdmin}>` : 'لا يوجد'}\n**👥 الأعضاء:** ${playersArray.map(id => `<@${id}>`).join(', ') || 'لا يوجد'}`,
        ephemeral: true
      });
    }
  });
  
  client.on('interactionCreate', async (interaction) => {
    if (!interaction.isButton()) return;
  
    if (interaction.customId === 'team_info') {
      const userId = interaction.user.id;
  
      const team = await Team.findOne({
        $or: [{ ownerid: userId }, { players: userId }]
      });
  
      if (!team) {
        return interaction.reply({ content: '❌ **أنت لست في أي فريق!**', ephemeral: true });
      }
  
      const ownerMention = `<@${team.ownerid}>`;
      const adminMentions = team.admins.length > 0 ? team.admins.map(id => `<@${id}>`).join(', ') : 'لا يوجد';
      const playerMentions = team.players.length > 0 ? team.players.map(id => `<@${id}>`).join(', ') : 'لا يوجد';
  
      let components = [];
  
      const embed = new Discord.MessageEmbed()
        .setTitle(`🏆 معلومات الفريق: ${team.teamtag}`)
        .setColor(serverColor)
        .addFields(
          { name: '👑 الأونر', value: ownerMention, inline: true },
          { name: '🛠 الإداريين', value: adminMentions, inline: true },
          { name: '👥 الأعضاء', value: playerMentions, inline: false }
        )
        .setTimestamp();
  
      const buttons = [];
  
      if (userId === team.ownerid) {
        const buttons1 = [
          new Discord.MessageButton().setCustomId('add_member').setLabel('➕ إضافة عضو').setStyle("PRIMARY"),
          new Discord.MessageButton().setCustomId('remove_member').setLabel('❌ إزالة عضو').setStyle("DANGER"),
          new Discord.MessageButton().setCustomId('change_tag').setLabel('🔄 تغيير التاق').setStyle("SECONDARY"),
          new Discord.MessageButton().setCustomId('add_admin').setLabel('⭐ إضافة إداري').setStyle("SUCCESS"),
          new Discord.MessageButton().setCustomId('remove_admin').setLabel('🚫 إزالة إداري').setStyle("DANGER")
        ];
  
        const buttons2 = [
          new Discord.MessageButton().setCustomId('ttttransfer_ownership').setLabel('🔄 نقل ملكية').setStyle("PRIMARY"),
          new Discord.MessageButton().setCustomId('delete_team').setLabel('🗑️ حذف الفريق').setStyle("DANGER")
        ];
        components.push(new Discord.MessageActionRow().addComponents(buttons1));
        components.push(new Discord.MessageActionRow().addComponents(buttons2));
      } else {
        const leaveButton = new Discord.MessageActionRow().addComponents(
          new Discord.MessageButton().setCustomId('leave_team').setLabel('🚪 الخروج من الفريق').setStyle("DANGER")
        );
        components.push(leaveButton);
      }
  
      await interaction.reply({ embeds: [embed], components: components, ephemeral: true });
    }
  });
  
  client.on('interactionCreate', async (interaction) => {
    if (!interaction.isButton()) return;
  
    if (interaction.customId === 'leave_team') {
      const userId = interaction.user.id;
  
      const team = await Team.findOne({ players: userId });
      if (!team) {
        return interaction.reply({ content: '❌ **أنت لست عضوًا في أي فريق!**', ephemeral: true });
      }
  
      team.players = team.players.filter(id => id !== userId);
      await team.save();
  
      const guildMember = await interaction.guild.members.fetch(userId);
      if (guildMember) {
        await guildMember.setNickname(null).catch(() => {});
      }
  
      interaction.reply({ content: '✅ **تم خروجك من الفريق بنجاح!**', ephemeral: true });
    }
  });
  
