const LEADERBOARD_CHANNEL_ID = '1502702729351532544';
const LEADERBOARD_UPDATE_INTERVAL = 30000;
const ANNOUNCEMENT_CHANNEL_ID = '1502702677036105728';

function convertToShortNumber(number) {
  if(number >= 1e12) return (number / 1e12).toFixed(1) + 'T';
  if(number >= 1e9) return (number / 1e9).toFixed(1) + 'B';
  if(number >= 1e6) return (number / 1e6).toFixed(1) + 'M';
  if(number >= 1e3) return (number / 1e3).toFixed(1) + 'K';
  return number.toString();
}

async function updateLeaderboards() {
    try {
        const activeCompetition = await Competition.findOne({ status: 'active' });
        if (!activeCompetition) return;

        const leaderboardChannel = client.channels.cache.get(LEADERBOARD_CHANNEL_ID);
        if (!leaderboardChannel) {
            console.error(`Leaderboard channel with ID ${LEADERBOARD_CHANNEL_ID} not found!`);
            return;
        }

        const participants = activeCompetition.participants.sort((a, b) => b.wageredAmount - a.wageredAmount);

        let totalPoints = 0;
        participants.slice(0, 10).forEach(p => {
            totalPoints += parseInt(p.wageredAmount);
        });
        
        let finalLb = "";
        let num = 0;

        for (let i = 0; i < Math.min(participants.length, 10); i++) {
            const participant = participants[i];
            const user = client.users.cache.get(participant.userId);
            if (!user) continue;
            
            num++;
            const formattedPoints = convertToShortNumber(parseInt(participant.wageredAmount));
            
            if (num === 1) {
                finalLb += `**🏆 <@${user.id}>** **\`-\`** **${formattedPoints}**\n`;
            } else {
                finalLb += `**#${num} <@${user.id}>** **\`-\`** **${formattedPoints}**\n`;
            }
        }

        if (finalLb === "") {
            finalLb = "**لا يوجد مشاركين في المسابقة حتى الآن!**";
        }

        const embed = new Discord.MessageEmbed()
            .setAuthor({ name: `توب المسابقة` })
            .setColor(serverColor)
            .setThumbnail(leaderboardChannel.guild.iconURL())
            .setDescription(finalLb)
            .setFooter({ text: `${leaderboardChannel.guild.name} | ${convertToShortNumber(totalPoints)}` })
            .setTimestamp();

        try {
            const messages = await leaderboardChannel.messages.fetch({ limit: 10 });
            const botMessages = messages.filter(m => m.author.id === client.user.id);
            
            if (botMessages.size > 0) {
                const mostRecentMessage = botMessages.first();
                await mostRecentMessage.edit({ embeds: [embed] });
                console.log("Leaderboard message updated:", new Date().toISOString());
            } else {
                await leaderboardChannel.send({ embeds: [embed] });
                console.log("New leaderboard message created:", new Date().toISOString());
            }
        } catch (error) {
            console.error("Error updating leaderboard message:", error);
            await leaderboardChannel.send({ embeds: [embed] });
        }

    } catch (error) {
        console.error('Error in updateLeaderboards function:', error);
    }
}

async function trackCompetitionPoints(userId, amount) {
    try {
        const activeCompetition = await Competition.findOne({ status: 'active' });
        if (!activeCompetition) return;

        const participantIndex = activeCompetition.participants.findIndex(p => p.userId === userId);
        
        if (participantIndex !== -1) {
            activeCompetition.participants[participantIndex].wageredAmount += amount;
        } else {
            activeCompetition.participants.push({
                userId: userId,
                wageredAmount: amount
            });
        }
        
        await activeCompetition.save();
    } catch (error) {
        console.error('Error tracking competition points:', error);
    }
}

client.on('messageCreate', async (message) => {

    if (message.content.startsWith('!competition')) {
        if (!isOwnerOrGranted(message.author.id, '!competition')) {
            return message.reply({ content: '❌ **هذا الأمر متاح للمالكين فقط**' });
        }

        const args = message.content.split(' ').slice(1);
        if (args.length < 5) {
            return message.reply('❌ **استخدام خاطئ!**\nاستخدم: `!competition [الأيام] [جائزة 4-10] [المركز الأول] [المركز الثاني] [المركز الثالث]`\nمثال: `!competition 2d 100m 500m 1000m 3000m`');
        }

        try {
            const days = parseInt(args[0].replace(/\D/g, ''));
            const top10Prize = parseNumberWithSuffix(args[1]);
            const firstPrize = parseNumberWithSuffix(args[2]);
            const secondPrize = parseNumberWithSuffix(args[3]);
            const thirdPrize = parseNumberWithSuffix(args[4]);

            if ([days, top10Prize, firstPrize, secondPrize, thirdPrize].some(isNaN)) {
                return message.reply('❌ **تنسيقات غير صالحة!** تأكد من استخدام أرقام مع لاحقات صحيحة (مثال: 100m, 5k)');
            }

            const startTime = new Date();
            const endTime = new Date(startTime.getTime() + days * 86400000);

            const competition = new Competition({
                startTime,
                endTime,
                top10Prize,
                top3Prize: [firstPrize, secondPrize, thirdPrize],
                entryFee: 0,
                status: 'active'
            });

            await competition.save();

            const embed = new MessageEmbed()
                .setTitle('🏆 بطولة Vip Casino')
                .setDescription(
                    `**مدة البطولة:** ${days} يوم\n` +
                    `**الجوائز:**\n` +
                    `🥇 المركز الأول: ${convertToShortNumber(firstPrize)} عملة\n` +
                    `🥈 المركز الثاني: ${convertToShortNumber(secondPrize)} عملة\n` +
                    `🥉 المركز الثالث: ${convertToShortNumber(thirdPrize)} عملة\n` +
                    `🎖 المراكز 4-10: ${convertToShortNumber(top10Prize)} عملة لكل مركز`
                )
                .setColor(serverColor)
                .setImage('')
                .setFooter({ text: `تبدأ في: ${startTime.toLocaleDateString()} | تنتهي في: ${endTime.toLocaleDateString()}` });

            const announcementChannel = client.channels.cache.get(ANNOUNCEMENT_CHANNEL_ID);
            const sentMessage = await announcementChannel.send({ embeds: [embed] });
            
            competition.messageId = sentMessage.id;
            await competition.save();

            message.reply('✅ تم إنشاء البطولة بنجاح!');
            
            await updateLeaderboards();
            
        } catch (error) {
            console.error('Competition Creation Error:', error);
            message.reply('❌ فشل إنشاء البطولة! تأكد من الصيغة الصحيحة: `!competition 2d 100m 500m 1000m 3000m`');
        }
    }
});

