async function handleCompetitionEnd(competition) {
    try {
        competition.status = 'ended';
        await competition.save();
        
        console.log("Competition marked as ended, distributing prizes...");

        const sortedParticipants = competition.participants
            .sort((a, b) => b.wageredAmount - a.wageredAmount);

        const announcementChannel = client.channels.cache.get(ANNOUNCEMENT_CHANNEL_ID);
        const winners = [];

        for (let i = 0; i < Math.min(3, sortedParticipants.length); i++) {
            const participant = sortedParticipants[i];
            const prize = competition.top3Prize[i];
            
            await db.updateOne(
                { id: participant.userId },
                { $inc: { coins: prize } }
            );
            
            winners.push({
                userId: participant.userId,
                rank: i + 1,
                prize: prize
            });
        }

        for (let i = 3; i < Math.min(10, sortedParticipants.length); i++) {
            const participant = sortedParticipants[i];
            
            await db.updateOne(
                { id: participant.userId },
                { $inc: { coins: competition.top10Prize } }
            );
            
            winners.push({
                userId: participant.userId,
                rank: i + 1,
                prize: competition.top10Prize
            });
        }

        const winnerEmbed = new MessageEmbed()
            .setTitle('🎉 انتهت البطولة - إليكم الفائزين! 🏆')
            .setColor(serverColor)
            .setImage('https://media.discordapp.net/attachments/1385603377051860992/1426973303712649247/golden_dice.png?ex=68ed2bf3&is=68ebda73&hm=759def89ebe87f8b7b85a40ba7d0d13b830aa75bddaad60af242e20cd8f117bc&=&format=webp&quality=lossless&width=1423&height=800')
            .setTimestamp();

        let description = '';
        
        if (winners.length > 0) {
            winners.forEach(winner => {
                const user = client.users.cache.get(winner.userId);
                const username = user ? user.username : 'مستخدم غير معروف';
                
                if (winner.rank === 1) {
                    description += `<:08f2c8daccf2512f9073fa7194e287fc:1458952510428676096>**المركز الأول**: ${user} - ${convertToShortNumber(winner.prize)} عملة\n`;
                } else if (winner.rank === 2) {
                    description += `🥈 **المركز الثاني**: ${user} - ${convertToShortNumber(winner.prize)} عملة\n`;
                } else if (winner.rank === 3) {
                    description += `🥉 **المركز الثالث**: ${user} - ${convertToShortNumber(winner.prize)} عملة\n`;
                } else {
                    description += `🎖 **المركز ${winner.rank}**: ${user} - ${convertToShortNumber(winner.prize)} عملة\n`;
                }
            });
        } else {
            description = 'لم يكن هناك أي مشاركين في هذه البطولة!';
        }
        
        winnerEmbed.setDescription(description);
        await announcementChannel.send({ embeds: [winnerEmbed] });
    } catch (error) {
        console.error('Error in handleCompetitionEnd:', error);
    }
}

function parseNumberWithSuffix(input) {
    const num = parseFloat(input.replace(/[^0-9.]/g, ''));
    const suffix = input.toLowerCase().replace(/[0-9.]/g, '');
    
    if (suffix.includes('m')) return num * 1000000;
    if (suffix.includes('k')) return num * 1000;
    return num;
}

