async function getLinkedPartners(userId) {
    try {
        const links = await Link.find({ userId: userId });
        return links.map(l => l.partnerId);
    } catch (error) {
        console.error('Error getting linked partners:', error);
        return [];
    }
}

async function getLinkedPartner(userId) {
    try {
        const link = await Link.findOne({ userId: userId });
        return link ? link.partnerId : null;
    } catch (error) {
        console.error('Error getting linked partner:', error);
        return null;
    }
}

async function isLinked(userId) {
    const partner = await getLinkedPartner(userId);
    return partner !== null;
}

async function createLink(user1Id, user2Id) {
    try {
        
        const user1Links = await Link.countDocuments({ userId: user1Id });
        const user2Links = await Link.countDocuments({ userId: user2Id });

        if (user1Links >= MAX_LINKS) {
            throw new Error(`وصلت للحد الأقصى من الربط! يمكنك الربط مع ${MAX_LINKS} أشخاص فقط.`);
        }
        if (user2Links >= MAX_LINKS) {
            throw new Error(`الشخص المستهدف وصل للحد الأقصى من الربط (${MAX_LINKS} أشخاص).`);
        }

        
        const existingLink = await Link.findOne({ userId: user1Id, partnerId: user2Id });
        if (existingLink) {
            throw new Error('أنتما مرتبطان بالفعل!');
        }

        
        await Link.create({
            userId: user1Id,
            partnerId: user2Id,
            linkedAt: new Date(),
            totalTransfers: 0
        });
        
        await Link.create({
            userId: user2Id,
            partnerId: user1Id,
            linkedAt: new Date(),
            totalTransfers: 0
        });
        
        return true;
    } catch (error) {
        console.error('Error creating link:', error);
        throw error;
    }
}

async function removeLink(userId, partnerId = null) {
    try {
        if (partnerId) {
            
            await Link.deleteOne({ userId: userId, partnerId: partnerId });
            await Link.deleteOne({ userId: partnerId, partnerId: userId });
        } else {
            
            const link = await Link.findOne({ userId: userId });
            if (!link) return false;
            const pId = link.partnerId;
            await Link.deleteOne({ userId: userId, partnerId: pId });
            await Link.deleteOne({ userId: pId, partnerId: userId });
        }
        return true;
    } catch (error) {
        console.error('Error removing link:', error);
        return false;
    }
}

