client.on("messageCreate", async (message) => {
    if (message.channel.parentId === "1478722657661747220") return;
    if (isBlacklisted(message.author.id)) return;
    if (message.author.bot) return;
    
    const args = message.content.split(' ');
    if (args[0].toLowerCase() !== 'ربط') return;
    
    const requesterId = message.author.id;
    
    
    const now = Date.now();
    if (linkCooldowns.has(requesterId)) {
        const cooldownEnd = linkCooldowns.get(requesterId);
        if (now < cooldownEnd) {
            const remaining = Math.ceil((cooldownEnd - now) / 1000);
            return message.reply(`⏳ يجب الانتظار ${remaining} ثانية قبل إرسال طلب ربط آخر!`);
        }
    }
    
    
    const mentioned = message.mentions.users.first();
    if (!mentioned) {
        return message.reply('❌ يجب عليك منشن الشخص الذي تريد الربط معه!\nمثال: `ربط @user`');
    }
    
    const targetId = mentioned.id;
    
    
    if (requesterId === targetId) {
        return message.reply('❌ لا يمكنك ربط حسابك مع نفسك!');
    }
    
    
    const requesterLinks = await Link.countDocuments({ userId: requesterId });
    if (requesterLinks >= MAX_LINKS) {
        return message.reply(`❌ وصلت للحد الأقصى! يمكنك الربط مع ${MAX_LINKS} أشخاص فقط.\nاستخدم أمر \`فصل @user\` لفصل أحد الأشخاص أولاً.`);
    }
    
    
    const targetLinks = await Link.countDocuments({ userId: targetId });
    if (targetLinks >= MAX_LINKS) {
        return message.reply(`❌ هذا الشخص وصل للحد الأقصى من الربط (${MAX_LINKS} أشخاص)!`);
    }
    
    
    const existingLink = await Link.findOne({ userId: requesterId, partnerId: targetId });
    if (existingLink) {
        return message.reply('❌ أنتما مرتبطان بالفعل!');
    }
    
    
    for (const [key, request] of linkRequests.entries()) {
        if (request.requesterId === requesterId && request.targetId === targetId) {
            clearTimeout(request.timeout);
            linkRequests.delete(key);
            try {
                await request.message.edit({
                    embeds: [new Discord.MessageEmbed()
                        .setColor('#FF0000')
                        .setDescription('❌ تم إلغاء الطلب بسبب إرسال طلب جديد.')],
                    components: []
                });
            } catch (e) {}
        }
    }
    
    
    const requestEmbed = new Discord.MessageEmbed()
        .setColor(serverColor)
        .setTitle('📎 طلب ربط حساب')
        .setDescription(`<@${mentioned.id}>, لديك طلب ربط من <@${requesterId}>!\n\n**ملاحظة:** يمكنك الربط مع ما يصل إلى ${MAX_LINKS} أشخاص.\nبعد الربط يمكنكما تبادل الأموال بحرية.`)
        .setFooter({ text: 'لديك 15 ثانية للرد على الطلب' })
        .setTimestamp();
    
    const row = new MessageActionRow()
        .addComponents(
            new MessageButton()
                .setCustomId('link_accept')
                .setLabel('قبول')
                .setStyle('SUCCESS')
                .setEmoji('✅'),
            new MessageButton()
                .setCustomId('link_reject')
                .setLabel('رفض')
                .setStyle('DANGER')
                .setEmoji('❌')
        );
    
    const requestMessage = await message.reply({ embeds: [requestEmbed], components: [row] });
    
    
    linkCooldowns.set(requesterId, now + LINK_COOLDOWN);
    
    
    const timeoutId = setTimeout(async () => {
        linkRequests.delete(requestMessage.id);
        try {
            await requestMessage.edit({
                embeds: [new Discord.MessageEmbed()
                    .setColor('#FF0000')
                    .setDescription('⏱️ انتهى وقت الطلب!')],
                components: []
            });
        } catch (e) {}
    }, REQUEST_TIMEOUT);
    
    
    linkRequests.set(requestMessage.id, {
        requesterId,
        targetId,
        message: requestMessage,
        timeout: timeoutId
    });
});

client.on('interactionCreate', async (interaction) => {
    if (!interaction.isButton()) return;
    if (!['link_accept', 'link_reject'].includes(interaction.customId)) return;
    
    const request = linkRequests.get(interaction.message.id);
    if (!request) {
        return interaction.reply({ content: '❌ هذا الطلب غير صالح أو منتهي!', ephemeral: true });
    }
    
    
    if (interaction.user.id !== request.targetId) {
        return interaction.reply({ content: '❌ هذا الطلب ليس موجهاً لك!', ephemeral: true });
    }
    
    
    clearTimeout(request.timeout);
    linkRequests.delete(interaction.message.id);
    
    if (interaction.customId === 'link_reject') {
        await interaction.update({
            embeds: [new Discord.MessageEmbed()
                .setColor('#FF0000')
                .setDescription(`❌ <@${request.targetId}> رفض طلب الربط.`)],
            components: []
        });
        return;
    }
    
    
    activeLinkOperations.add(request.requesterId);
    activeLinkOperations.add(request.targetId);
    
    try {
        
        const requesterLinksCount = await Link.countDocuments({ userId: request.requesterId });
        if (requesterLinksCount >= MAX_LINKS) {
            throw new Error(`المرسل وصل للحد الأقصى من الربط (${MAX_LINKS} أشخاص)!`);
        }
        
        const targetLinksCount = await Link.countDocuments({ userId: request.targetId });
        if (targetLinksCount >= MAX_LINKS) {
            throw new Error(`وصلت للحد الأقصى من الربط (${MAX_LINKS} أشخاص)!`);
        }
        
        const alreadyLinked = await Link.findOne({ userId: request.requesterId, partnerId: request.targetId });
        if (alreadyLinked) {
            throw new Error('أنتما مرتبطان بالفعل!');
        }
        
        
        const success = await createLink(request.requesterId, request.targetId);
        
        if (!success) {
            throw new Error('فشل في حفظ بيانات الربط!');
        }
        
        await interaction.update({
            embeds: [new Discord.MessageEmbed()
                .setColor('#00FF00')
                .setTitle('✅ تم الربط بنجاح!')
                .setDescription(`تم ربط <@${request.requesterId}> مع <@${request.targetId}>\n\nيمكنكما الآن:\n• استخدام \`إيداع @user <مبلغ>\` لتحويل أموال\n• استخدام \`سحب @user <مبلغ>\` لسحب أموال\n• استخدام \`فلوس\` لعرض الأرصدة\n• استخدام \`فصل @user\` لإنهاء الربط مع شخص محدد`)],
            components: []
        });
        
    } catch (error) {
        await interaction.update({
            embeds: [new Discord.MessageEmbed()
                .setColor('#FF0000')
                .setDescription(`❌ حدث خطأ: ${error.message}`)],
            components: []
        });
    } finally {
        activeLinkOperations.delete(request.requesterId);
        activeLinkOperations.delete(request.targetId);
    }
});

client.on("messageCreate", async (message) => {
    if (message.channel.parentId === "1478722657661747220") return;
    if (isBlacklisted(message.author.id)) return;
    if (message.author.bot) return;
    
    const args = message.content.trim().split(/\s+/);
    if (args[0].toLowerCase() !== 'فصل') return;
    
    const userId = message.author.id;
    
    
    const allPartners = await getLinkedPartners(userId);
    if (allPartners.length === 0) {
        return message.reply('❌ أنت غير مرتبط مع أي شخص!');
    }
    
    
    
    
    if (args[1] && args[1].toLowerCase() === 'all') {
        activeLinkOperations.add(userId);
        try {
            let failedCount = 0;
            const notifiedPartners = [];

            for (const pid of allPartners) {
                const success = await removeLink(userId, pid);
                if (success) {
                    notifiedPartners.push(pid);
                } else {
                    failedCount++;
                }
            }

            
            for (const pid of notifiedPartners) {
                try {
                    const pUser = await client.users.fetch(pid);
                    await pUser.send({
                        embeds: [new Discord.MessageEmbed()
                            .setColor('#FFA500')
                            .setDescription(`🔗 تم فصل الربط بينك وبين <@${userId}> (فصل جميع الروابط)`)]
                    });
                } catch (e) {}
            }

            const partnerMentions = notifiedPartners.map(id => `<@${id}>`).join('، ');
            const embed = new Discord.MessageEmbed()
                .setColor('#FFA500')
                .setTitle('🔗 تم فصل جميع الروابط')
                .setDescription(
                    notifiedPartners.length > 0
                        ? `تم فصل الربط مع: ${partnerMentions}` 
                        : '❌ لم يتم فصل أي ربط!'
                )
                .setFooter({ text: failedCount > 0 ? `فشل في فصل ${failedCount} ربط` : 'تمت العملية بنجاح' })
                .setTimestamp();

            return await message.reply({ embeds: [embed] });

        } catch (error) {
            await message.reply(`❌ حدث خطأ: ${error.message}`);
        } finally {
            activeLinkOperations.delete(userId);
        }
        return;
    }

    
    
    
    const mentioned = message.mentions.users.first();
    let partnerId;
    
    if (mentioned) {
        if (!allPartners.includes(mentioned.id)) {
            return message.reply(`❌ أنت غير مرتبط مع <@${mentioned.id}>!`);
        }
        partnerId = mentioned.id;
    } else if (allPartners.length === 1) {
        partnerId = allPartners[0];
    } else {
        const partnerMentions = allPartners.map(id => `<@${id}>`).join('، ');
        return message.reply(`❌ أنت مرتبط مع أكثر من شخص! حدد من تريد فصله:\nالأشخاص المرتبطون: ${partnerMentions}\nمثال: \`فصل @user\` أو \`فصل all\` لفصل الكل`);
    }
    
    activeLinkOperations.add(userId);
    
    try {
        const success = await removeLink(userId, partnerId);
        
        if (!success) {
            throw new Error('فشل في حذف بيانات الربط!');
        }
        
        const embed = new Discord.MessageEmbed()
            .setColor('#FFA500')
            .setTitle('🔗 تم فصل الربط')
            .setDescription(`تم فصل الربط بينك وبين <@${partnerId}> بنجاح!`)
            .setTimestamp();
        
        await message.reply({ embeds: [embed] });
        
        
        try {
            const partner = await client.users.fetch(partnerId);
            await partner.send({
                embeds: [new Discord.MessageEmbed()
                    .setColor('#FFA500')
                    .setDescription(`🔗 تم فصل الربط بينك وبين <@${userId}>`)]
            });
        } catch (e) {}
        
    } catch (error) {
        await message.reply(`❌ حدث خطأ: ${error.message}`);
    } finally {
        activeLinkOperations.delete(userId);
    }
});

client.on("messageCreate", async (message) => {
    if (message.channel.parentId === "1478722657661747220") return;
    if (isBlacklisted(message.author.id)) return;
    if (message.author.bot) return;
    if (message.channel.name && message.channel.name.startsWith('ticket')) return;

    const args = message.content.trim().split(/\s+/);
    if (!args[0]) return;

    if (args[0].toLowerCase() !== 'إيداع' && args[0].toLowerCase() !== 'ايداex') return;

    const userId = message.author.id;
    
    // Check if user is in an active duel
    if (await isUserInActiveDuel(userId)) {
        return message.reply('❌ | **لا يمكنك الإيداع أثناء وجود Duel نشط! انتظر انتهاء الـ Duel أولاً.**');
    }

    if (!(await isLinked(userId))) {
        return message.reply('❌ يجب أن تكون مرتبطاً مع شخص لاستخدام هذا الأمر!');
    }

    
    
    
    const now = Date.now();
    if (cooldooooown.has(userId)) {
        const cdEnd = cooldooooown.get(userId);
        if (now < cdEnd) {
            const remaining = Math.ceil((cdEnd - now) / 1000);
            return message.reply(`⏳ انتظر ${remaining} ثانية قبل استخدام هذا الأمر!`);
        }
    }

    
    
    
    const allPartners = await getLinkedPartners(userId);
    let partnerId;
    let amountArgIndex;

    const mentioned = message.mentions.users.first();
    if (mentioned) {
        if (!allPartners.includes(mentioned.id)) {
            return message.reply(`❌ أنت غير مرتبط مع <@${mentioned.id}>! استخدم \`ربط @user\` للربط معه أولاً.`);
        }
        partnerId = mentioned.id;
        amountArgIndex = 2;
    } else if (allPartners.length === 1) {
        partnerId = allPartners[0];
        amountArgIndex = 1;
    } else {
        const partnerMentions = allPartners.map(id => `<@${id}>`).join('، ');
        return message.reply(`❌ أنت مرتبط مع أكثر من شخص! حدد من تريد الإيداع إليه.\nمثال: \`إيداع @user 1000\`\nالأشخاص المرتبطون: ${partnerMentions}`);
    }

    
    if (cooldooooown.has(partnerId)) {
        const cdEnd = cooldooooown.get(partnerId);
        if (now < cdEnd) {
            const remaining = Math.ceil((cdEnd - now) / 1000);
            return message.reply(`⏳ الشخص المرتبط معك في كول داون! انتظر ${remaining} ثانية.`);
        }
    }

    
    
    

    let amountInput = args[amountArgIndex];
    if (!amountInput) {
        return message.reply('❌ يجب إدخال مبلغ!\nمثال: `إيداع @user 1000` أو `إيداع @user 1K` أو `إيداع @user كامل`');
    }

    const userData = await db.findOne({ id: userId });
    if (!userData) return message.reply('❌ حدث خطأ في جلب بياناتك!');

    let amount;
    amountInput = amountInput.replace(/,/g, '').toUpperCase();

    
    if (amountInput === 'كامل' || amountInput === 'فل') {
        amount = userData.coins;
    }

    
    else if (amountInput === 'نص') {
        amount = Math.floor(userData.coins / 2);
    }

    
    else if (amountInput.endsWith('%')) {
        const percent = parseFloat(amountInput.replace('%', ''));
        if (isNaN(percent) || percent <= 0 || percent > 100) {
            return message.reply('❌ يجب إدخال نسبة صحيحة بين 1% و 100%');
        }
        amount = Math.floor((userData.coins * percent) / 100);
    }

    
    else if (amountInput.endsWith('K')) {
        const value = parseFloat(amountInput.replace('K', ''));
        if (isNaN(value)) return message.reply('❌ صيغة K غير صحيحة!');
        amount = value * 1000;
    }

    else if (amountInput.endsWith('M')) {
        const value = parseFloat(amountInput.replace('M', ''));
        if (isNaN(value)) return message.reply('❌ صيغة M غير صحيحة!');
        amount = value * 1000000;
    }

    
    else {
        amount = parseFloat(amountInput);
    }

    if (!amount || isNaN(amount) || amount < 1) {
        return message.reply('❌ يجب إدخال مبلغ صحيح!');
    }

    amount = Math.floor(amount);

    
    
    

    
    if (activeLinkOperations.has(userId)) {
        return message.reply('❌ لديك عملية تحويل نشطة حالياً! انتظر حتى تنتهي.');
    }

    
    const pendingWithdrawal = await S7b.findOne({ 
        user: userId,
        status: 'pending'
    });
    
    if (pendingWithdrawal) {
        return message.reply("❌ لديك طلب سحب قيد المعالجة. لا يمكنك الإيداع حالياً.");
    }
    
    
    if (activeWithdrawals.has(userId) || (isProcessing && currentWithdrawalUser === userId)) {
        return message.reply({ content: '**> لديك عملية سحب قيد الاختيار**' });
    }
    
    const userDataCheck = await db.findOne({ id: userId });
    if (userDataCheck && (userDataCheck.isOnWithdrawal === "yes" || userDataCheck.withdrawing === true)) {
        return message.reply({ content: '**> لديك عملية سحب قيد الاختيار**' });
    }

    
    const partnerPendingWithdrawal = await S7b.findOne({ 
        user: partnerId,
        status: 'pending'
    });
    
    if (partnerPendingWithdrawal) {
        return message.reply("❌ الشخص المرتبط معك لديه طلب سحب قيد المعالجة. لا يمكن الإيداع حالياً.");
    }
    
    
    if (activeWithdrawals.has(partnerId) || (isProcessing && currentWithdrawalUser === partnerId)) {
        return message.reply({ content: '**> الشخص المرتبط معك لديه عملية سحب قيد الاختيار**' });
    }
    
    const partnerDataCheck = await db.findOne({ id: partnerId });
    if (partnerDataCheck && (partnerDataCheck.isOnWithdrawal === "yes" || partnerDataCheck.withdrawing === true)) {
        return message.reply({ content: '**> الشخص المرتبط معك لديه عملية سحب قيد الاختيار**' });
    }
    
    
    if (activeChallenges.has(userId) || activeChallengers.has(userId)) {
        return message.reply('❌ لا يمكنك الإيداع أثناء وجودك في تحدي!');
    }
    
    
    if (userData && userData.status_playing === 'yes') {
        return message.reply('❌ لا يمكنك الإيداع أثناء اللعب ضد البوت!');
    }
    
    
    if (userData && userData.status_challenge === 'yes') {
        return message.reply('❌ لا يمكنك الإيداع أثناء وجودك في تحدي!');
    }
    
    
    if (activeChallenges.has(partnerId) || activeChallengers.has(partnerId)) {
        return message.reply('❌ الشخص المرتبط معك في تحدي حالياً! لا يمكن الإيداع.');
    }
    
    
    if (partnerDataCheck && partnerDataCheck.status_playing === 'yes') {
        return message.reply('❌ الشخص المرتبط معك يلعب ضد البوت حالياً! لا يمكن الإيداع.');
    }
    
    
    if (partnerDataCheck && partnerDataCheck.status_challenge === 'yes') {
        return message.reply('❌ الشخص المرتبط معك في تحدي حالياً! لا يمكن الإيداع.');
    }
    
    
    if (activeLinkOperations.has(partnerId)) {
        return message.reply('❌ الشخص المرتبط معك يقوم بعملية تحويل حالياً! انتظر قليلاً.');
    }

    
    
    
    if (transferCooldowns.has(userId)) {
        const cooldownEnd = transferCooldowns.get(userId);
        if (now < cooldownEnd) {
            const remaining = Math.ceil((cooldownEnd - now) / 1000);
            return message.reply(`⏳ يجب الانتظار ${remaining} ثانية بين عمليات السحب والإيداع!`);
        }
    }

    
    if (hiddenUsers.has(userId)) {
        return message.reply('> ❌ **لا يمكنك الإيداع وأنت مخفي!**\nاكتب `unhideme` أولاً لإظهار رصيدك.');
    }
    if (hiddenUsers.has(partnerId)) {
        return message.reply('> ❌ **لا يمكنك الإيداع لهذا الشخص لأن رصيده مخفي.**');
    }

    
    
    
    activeLinkOperations.add(userId);
    activeLinkOperations.add(partnerId);

    try {
        
        if (userData.coins < amount) {
            throw new Error(`ليس لديك رصيد كافٍ!\nرصيدك الحالي: **${userData.coins.toLocaleString()}** كوين`);
        }

        
        const partnerData = await db.findOne({ id: partnerId });
        if (!partnerData) {
            throw new Error('فشل في جلب بيانات الشريك!');
        }

        
        const oldUserBalance = userData.coins;
        const oldPartnerBalance = partnerData.coins;

        
        userData.coins -= amount;
        partnerData.coins += amount;

        
        if (userData.coins < 0 || partnerData.coins < 0) {
            userData.coins = oldUserBalance;
            partnerData.coins = oldPartnerBalance;
            throw new Error('حدث خطأ في العملية!');
        }

        
        await userData.save();
        await partnerData.save();

        
        const verifyUser = await db.findOne({ id: userId });
        const verifyPartner = await db.findOne({ id: partnerId });
        
        if (verifyUser.coins !== userData.coins || verifyPartner.coins !== partnerData.coins) {
            
            userData.coins = oldUserBalance;
            partnerData.coins = oldPartnerBalance;
            await userData.save();
            await partnerData.save();
            throw new Error('فشل التحقق من العملية!');
        }

        
        await updateTransferCount(userId);
        await updateTransferCount(partnerId);

        
        transferCooldowns.set(userId, now + TRANSFER_COOLDOWN);
        transferCooldowns.set(partnerId, now + TRANSFER_COOLDOWN);
        cooldooooown.set(userId, now + LINK_CMD_COOLDOWN);
        cooldooooown.set(partnerId, now + LINK_CMD_COOLDOWN);

        const partner = await client.users.fetch(partnerId);

        
        
        
        const logChannel = await client.channels.fetch(logLinkedDepositChannelId).catch(() => null);
        if (logChannel) {
            const logEmbed = new Discord.MessageEmbed()
                .setColor('#00FF00')
                .setTitle('💰 عملية إيداع جديدة')
                .addFields(
                    { name: 'المستخدم', value: `<@${userId}>`, inline: true },
                    { name: 'الشريك', value: `<@${partnerId}>`, inline: true },
                    { name: 'المبلغ', value: `${amount.toLocaleString()} كوين`, inline: true },
                    { name: 'رصيد المستخدم قبل', value: `${oldUserBalance.toLocaleString()} كوين`, inline: true },
                    { name: 'رصيد المستخدم بعد', value: `${userData.coins.toLocaleString()} كوين`, inline: true },
                    { name: 'رصيد الشريك قبل', value: `${oldPartnerBalance.toLocaleString()} كوين`, inline: true },
                    { name: 'رصيد الشريك بعد', value: `${partnerData.coins.toLocaleString()} كوين`, inline: true }
                )
                .setTimestamp();
            logChannel.send({ embeds: [logEmbed] }).catch(console.error);
        }

        
        const embed = new Discord.MessageEmbed()
            .setColor('#00FF00')
            .setTitle('💸 عملية إيداع ناجحة')
            .setDescription(`تم إيداع **${amount.toLocaleString()}** كوين إلى <@${partnerId}>`)
            .addFields(
                { name: 'رصيدك الجديد', value: `${hiddenUsers.has(userId) ? '0' : userData.coins.toLocaleString()} كوين`, inline: true },
                { name: `رصيد ${partner.username}`, value: `${hiddenUsers.has(partnerId) ? '0' : partnerData.coins.toLocaleString()} كوين`, inline: true }
            )
            .setFooter({ text: `العملية تمت بنجاح` })
            .setTimestamp();

        await message.reply({ embeds: [embed] });

        try {
            await partner.send({
                embeds: [
                    new Discord.MessageEmbed()
                        .setColor('#00FF00')
                        .setDescription(`💰 استلمت **${amount.toLocaleString()}** كوين من <@${userId}>\nرصيدك الجديد: **${hiddenUsers.has(partnerId) ? '0' : partnerData.coins.toLocaleString()}** كوين`)
                ]
            });
        } catch (e) {}

    } catch (error) {
        await message.reply(`❌ ${error.message}`);
    } finally {
        activeLinkOperations.delete(userId);
        activeLinkOperations.delete(partnerId);
    }
});

