// ============================================
// 🔧 OWNER: TAKRIBI SHOP CONTROL COMMAND
// ============================================
// Usage:  takribishop                        → show all tools & status
//         takribishop enable  <ToolName>     → enable a tool
//         takribishop disable <ToolName>     → disable a tool
//         takribishop price   <ToolName> <amount> → change tool price
// ============================================

client.on('messageCreate', async (message) => {
    if (message.author.bot || !message.guild) return;
    const args = message.content.trim().split(/\s+/);
    if (args[0].toLowerCase() !== 'takribishop') return;
    if (!isActiveOwner(message.author.id)) return;

    const shopConfig = takribiReadShopConfig();
    const subCmd = (args[1] || '').toLowerCase();

    // ── List all tools ───────────────────────────────────────────────
    if (!subCmd) {
        const embed = new Discord.MessageEmbed()
            .setColor('#FFD700')
            .setTitle('🛍️ متجر التقريبي — لوحة التحكم')
            .setDescription('استخدم الأوامر أدناه للتحكم في الأدوات:')
            .addField('الأوامر المتاحة',
                '`takribishop enable <اسم>`\n' +
                '`takribishop disable <اسم>`\n' +
                '`takribishop price <اسم> <المبلغ>`',
                false
            );

        for (const [key, tool] of Object.entries(shopConfig)) {
            embed.addField(
                `${tool.enabled ? '✅' : '❌'} ${tool.name}`,
                `💵 السعر: \`${tool.price.toLocaleString()}\`\n📝 ${tool.description}`,
                true
            );
        }
        return message.reply({ embeds: [embed] });
    }

    const toolName = args[2];
    if (!toolName) {
        return message.reply('> ❌ **يجب تحديد اسم الأداة. مثال: `takribishop enable BackNumber`**');
    }

    // Find tool (case-insensitive)
    const matchedKey = Object.keys(shopConfig).find(k => k.toLowerCase() === toolName.toLowerCase());
    if (!matchedKey) {
        const toolList = Object.keys(shopConfig).join(', ');
        return message.reply(`> ❌ **الأداة غير موجودة!**\n> الأدوات المتاحة: \`${toolList}\``);
    }

    const tool = shopConfig[matchedKey];

    if (subCmd === 'enable') {
        tool.enabled = true;
        takribiWriteShopConfig(shopConfig);
        return message.reply(`> ✅ **تم تفعيل أداة \`${tool.name}\`** في متجر التقريبي!`);
    }

    if (subCmd === 'disable') {
        tool.enabled = false;
        takribiWriteShopConfig(shopConfig);
        return message.reply(`> ✅ **تم تعطيل أداة \`${tool.name}\`** في متجر التقريبي!`);
    }

    if (subCmd === 'price') {
        const rawPrice = args[3];
        if (!rawPrice) return message.reply('> ❌ **يجب تحديد السعر. مثال: `takribishop price BackNumber 25000000`**');
        const newPrice = parseInt(rawPrice.replace(/,/g, ''));
        if (isNaN(newPrice) || newPrice <= 0) return message.reply('> ❌ **السعر غير صحيح!**');
        tool.price = newPrice;
        takribiWriteShopConfig(shopConfig);
        return message.reply(`> ✅ **تم تغيير سعر \`${tool.name}\`** إلى \`${newPrice.toLocaleString()}\` كوينز!`);
    }

    return message.reply(
        '> ❌ **أمر غير معروف.**\n' +
        '> الأوامر: `enable` | `disable` | `price`'
    );
});

async function botolaGetOrCreateTournamentChannel(guild) {
    const rt = botolaRuntime.get(guild.id);
    if (rt && rt.tournamentChannelId) {
        const ch = guild.channels.cache.get(rt.tournamentChannelId);
        if (ch) return ch;
    }
    
    try {
        const category = guild.channels.cache.get(BOTOLA_CATEGORY_ID);
        const newChannel = await guild.channels.create('🏆・بطولة-جارية', {
            type: 'GUILD_TEXT',
            parent: category || null,
            permissionOverwrites: [
                {
                    id: guild.roles.everyone,
                    allow: ['VIEW_CHANNEL'],
                    deny: ['SEND_MESSAGES']
                }
            ]
        });
        if (rt) rt.tournamentChannelId = newChannel.id;
        
        const _tSave = botolaGet(guild.id);
        if (_tSave) { _tSave.tournamentChannelId = newChannel.id; botolaSave(guild.id, _tSave); }
        return newChannel;
    } catch (e) {
        console.error('خطأ في إنشاء روم البطولة:', e);
        return null;
    }
}

async function botolaAddPlayerToChannel(guild, channelId, playerId) {
    try {
        const ch = guild.channels.cache.get(channelId);
        if (!ch) return;
        await ch.permissionOverwrites.edit(playerId, { SEND_MESSAGES: true, VIEW_CHANNEL: true });
    } catch(e) {}
}

async function botolaRemovePlayerFromChannel(guild, channelId, playerId) {
    try {
        const ch = guild.channels.cache.get(channelId);
        if (!ch) return;
        await ch.permissionOverwrites.delete(playerId);
    } catch(e) {}
}

async function botolaHideTournamentChannel(guild) {
    const rt = botolaRuntime.get(guild.id);
    if (!rt || !rt.tournamentChannelId) return;
    try {
        const ch = guild.channels.cache.get(rt.tournamentChannelId);
        if (ch) await ch.permissionOverwrites.edit(guild.roles.everyone, { VIEW_CHANNEL: false, SEND_MESSAGES: false });
    } catch(e) {}
}

const BOTOLA_FILE = './botola.json';

function botolaRead() {
    try {
        if (!fs.existsSync(BOTOLA_FILE)) {
            fs.writeFileSync(BOTOLA_FILE, '{}', 'utf8');
            return {};
        }
        return JSON.parse(fs.readFileSync(BOTOLA_FILE, 'utf8'));
    } catch (e) {
        console.error('❌ خطأ في قراءة botola.json:', e);
        return {};
    }
}

function botolaWrite(data) {
    try {
        fs.writeFileSync(BOTOLA_FILE, JSON.stringify(data, null, 2), 'utf8');
    } catch (e) {
        console.error('❌ خطأ في حفظ botola.json:', e);
    }
}

function botolaGet(guildId) {
    return botolaRead()[guildId] || null;
}

function botolaSave(guildId, tournament) {
    const all = botolaRead();
    all[guildId] = tournament;
    botolaWrite(all);
}

function botolaRemove(guildId) {
    const all = botolaRead();
    delete all[guildId];
    
    delete all[`${guildId}_activegames`];
    botolaWrite(all);
}

const botolaRuntime = new Map();

const botolaActiveGames = new Map();

const botolaGameResults = new Map(); // Store game results: mid -> {winner, loser}

const botolaResumingMsgIds = new Set();

const botolaCooldown = new Map();
function botolaCheckCooldown(userId) {
    const t = botolaCooldown.get(userId);
    return t && Date.now() - t < 1000;
}
function botolaSetCooldown(userId) {
    botolaCooldown.set(userId, Date.now());
    setTimeout(() => botolaCooldown.delete(userId), 1000);
}

