const BOTOLA_TICKETS_FILE = './botola_tickets.json';

function botolaTicketsLoad() {
    try {
        if (fs.existsSync(BOTOLA_TICKETS_FILE)) {
            return JSON.parse(fs.readFileSync(BOTOLA_TICKETS_FILE, 'utf8'));
        }
    } catch(e) { console.error('خطأ تحميل botola_tickets.json:', e); }
    return {};
}

function botolaTicketsSave(data) {
    try {
        fs.writeFileSync(BOTOLA_TICKETS_FILE, JSON.stringify(data, null, 2), 'utf8');
    } catch(e) { console.error('خطأ حفظ botola_tickets.json:', e); }
}

function botolaTicketsGet(userId, entryFee) {
    const data = botolaTicketsLoad();
    return (data[userId] && data[userId][entryFee]) ? data[userId][entryFee] : 0;
}

function botolaTicketsAdd(userId, entryFee, count) {
    const data = botolaTicketsLoad();
    if (!data[userId]) data[userId] = {};
    data[userId][entryFee] = (data[userId][entryFee] || 0) + count;
    botolaTicketsSave(data);
}

function botolaTicketsUse(userId, entryFee) {
    const data = botolaTicketsLoad();
    if (!data[userId] || !data[userId][entryFee] || data[userId][entryFee] <= 0) return false;
    data[userId][entryFee]--;
    if (data[userId][entryFee] === 0) delete data[userId][entryFee];
    if (Object.keys(data[userId]).length === 0) delete data[userId];
    botolaTicketsSave(data);
    return true;
}

const botolaPlayerLock = new Map(); 
function botolaAcquireLock(userId) {
    const existing = botolaPlayerLock.get(userId);
    if (existing && existing.locked) return false;
    
    const timer = setTimeout(() => {
        const entry = botolaPlayerLock.get(userId);
        if (entry) {
            botolaPlayerLock.delete(userId);
            console.log(`🔓 botola: تحرير قفل عالق للمستخدم ${userId}`);
        }
    }, 8000);
    botolaPlayerLock.set(userId, { locked: true, timer });
    return true;
}
function botolaReleaseLock(userId) {
    const entry = botolaPlayerLock.get(userId);
    if (entry && entry.timer) clearTimeout(entry.timer);
    botolaPlayerLock.delete(userId);
}

setInterval(() => {
    
    
    for (const [userId, entry] of botolaPlayerLock.entries()) {
        if (!entry || !entry.timer) {
            botolaPlayerLock.delete(userId);
        }
    }
}, 30000);

function botolaParseAmount(str) {
    if (!str) return 0;
    str = str.toString().toLowerCase().trim();
    let mul = 1;
    if (str.endsWith('m') || str.endsWith('م')) { mul = 1_000_000; str = str.slice(0, -1); }
    else if (str.endsWith('k') || str.endsWith('ك')) { mul = 1_000; str = str.slice(0, -1); }
    return Math.floor(parseFloat(str) * mul) || 0;
}

function botolaParseTime(str) {
    if (!str) return null;
    str = str.toLowerCase().trim();
    if (str.endsWith('h')) return parseFloat(str) * 3_600_000;
    if (str.endsWith('m')) return parseFloat(str) * 60_000;
    if (str.endsWith('s')) return parseFloat(str) * 1_000;
    return null;
}

function botolaRoundName(n) {
    if (n === 2)  return '🏆 النهائي';
    if (n === 4)  return 'نصف النهائي';
    if (n === 8)  return 'ربع النهائي';
    if (n === 16) return 'دور الـ16';
    if (n === 32) return 'دور الـ32';
    if (n === 64) return 'دور الـ64';
    return `دور الـ${n}`;
}

function botolaShuffle(arr) {
    const a = [...arr];
    for (let i = a.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
}

function botolaAnnounceEmbed(t) {
    const list = t.participants.length > 0
        ? t.participants.map((p, i) => `**${i + 1}.** <@${p.id}>`).join('\n')
        : '*لا يوجد مشاركين بعد*';

    return new MessageEmbed()
        .setColor('#FFD700')
        .setTitle('🏆 بطولة Vip Casino')
        .addField('💰 رسوم المشاركة', `\`${t.entryFee.toLocaleString()}\` كوين`, true)
        .addField('🎁 الجائزة الكبرى', `\`${t.prize.toLocaleString()}\` كوين`, true)
        .addField('👥 المشاركون', `\`${t.participants.length}/${t.maxPlayers}\``, true)
        .addField('📐 النظام', t.format === '1vall' ? '1vall (فائز ضد التالي)' : 'عادية (جولات ثنائية)', true)
        .addField('🎮 اللعبة', {
            nard: 'نرد 🎲',
            cond: 'تقريبي شروط 🎯',
            norm: 'تقريبي بدون شروط 🎲',
            lim:  'حد تقريبي طبيعي 🏁',
            limshow: 'حد تقريبي اظهار ارقام 🔢',
            limitfar: 'حد أبعد طبيعي 🎯',
            limitfarshow: 'حد أبعد اظهار ارقام 🔢'
        }[t.gameType] || 'تقريبي شروط 🎯', true)
        .addField('📋 قائمة المشاركين', list)
        .setFooter({ text: 'اضغط زر المشاركة للانضمام! | الأدمن يبدأ البطولة يدوياً' })
        .setTimestamp();
}

client.once('ready', async () => {
    const all = botolaRead();
    for (const [guildId, t] of Object.entries(all)) {
        const guild = client.guilds.cache.get(guildId);
        const ch    = client.channels.cache.get(t.channelId);
        if (!guild || !ch) { botolaRemove(guildId); continue; }

        if (t.status === 'open') {
            
            ch.send('> 🔄 **البطولة استُعيدت بعد الريستارت. تنتظر بدء يدوي من الأدمن.**').catch(() => {});
        } else if (t.status === 'running') {
            botolaRemove(guildId);
            ch.send('> ⚠️ **انقطعت البطولة أثناء جولة جارية بسبب الريستارت وتم إلغاؤها.**').catch(() => {});
        }
    }
    console.log('✅ نظام البطولة (botola) نشط');
});

async function botolaRefund(t) {
    for (const p of t.participants) {
        try {
            const u = await db.findOne({ id: p.id });
            if (u) { u.coins += t.entryFee; await u.save(); invalidateMoneyCache(p.id); }
        } catch (e) { console.error('botola refund error:', e); }
    }
}

client.on('messageCreate', async (message) => {
    if (message.author.bot) return;
    const args = message.content.trim().split(/\s+/);
    if (args[0].toLowerCase() !== 'rmvusr') return;

    const isAdmin = isOwnerOrGranted(message.author.id, 'rmvusr');
    if (!isAdmin) return message.reply('> ❌ **هذا الأمر للأوناروز فقط!**');

    const t = botolaGet(message.guild.id);
    if (!t) return message.reply('> ❌ **لا توجد بطولة نشطة!**');

    if (t.status !== 'open')
        return message.reply('> ❌ **لا يمكن إزالة مشارك بعد بدء البطولة!**');

    
    const target = message.mentions.users.first();
    if (!target) return message.reply('> ❌ **حدد المستخدم! المثال: `rmvusr @user`**');

    const idx = t.participants.findIndex(p => p.id === target.id);
    if (idx === -1)
        return message.reply(`> ❌ **<@${target.id}> ليس مشاركاً في البطولة!**`);

    
    t.participants.splice(idx, 1);

    
    try {
        const userData = await db.findOne({ id: target.id });
        if (userData) {
            userData.coins += t.entryFee;
            await userData.save();
            invalidateMoneyCache(target.id);
        }
    } catch(e) { console.error('rmvusr refund error:', e); }

    botolaSave(message.guild.id, t);

    
    try {
        const announceChannel = message.guild.channels.cache.get(t.channelId);
        if (announceChannel && t.announceMessageId) {
            const announceMsg = await announceChannel.messages.fetch(t.announceMessageId).catch(() => null);
            if (announceMsg) {
                const isFull = t.participants.length >= t.maxPlayers;
                await announceMsg.edit({
                    embeds: [botolaAnnounceEmbed(t)],
                    components: [new MessageActionRow().addComponents(
                        new MessageButton()
                            .setCustomId(`botola_join_${message.guild.id}`)
                            .setLabel(isFull ? '🔒 ممتلئة' : '🏆 مشاركة')
                            .setStyle(isFull ? 'SECONDARY' : 'SUCCESS')
                            .setDisabled(isFull),
                        new MessageButton()
                            .setCustomId(`botola_start_${message.guild.id}`)
                            .setLabel('🚀 بدء البطولة')
                            .setStyle('DANGER')
                    )]
                }).catch(() => {});
            }
        }
    } catch(e) { console.error('rmvusr embed update error:', e); }

    
    try {
        const logCh = message.guild.channels.cache.get(BOTOLA_LOG_CHANNEL);
        if (logCh) await logCh.send({ embeds: [new MessageEmbed()
            .setColor('#FF6600')
            .setTitle('🗑️ تمت إزالة مشارك من البطولة')
            .addField('المُزال', `<@${target.id}>`, true)
            .addField('بواسطة', `<@${message.author.id}>`, true)
            .addField('الرسوم المُرجعة', `\`${t.entryFee.toLocaleString()}\` كوين`, true)
            .addField('المشاركون الآن', `${t.participants.length}/${t.maxPlayers}`, true)
            .setTimestamp()
        ]}).catch(() => {});
    } catch(e) {}

    return message.reply(`> ✅ **تم إزالة <@${target.id}> من البطولة وإرجاع \`${t.entryFee.toLocaleString()}\` كوين له. المشاركون: ${t.participants.length}/${t.maxPlayers}**`);
});

