const setPermSessions = new Map();

const setPermAllowedUsers = new Set();

client.on('messageCreate', async (message) => {
    if (message.author.bot) return;
    if (!message.guild) return;
    if (!isOwnerOrGranted(message.author.id, '!setpermission')) return;

    const parts = message.content.trim().split(/\s+/);
    if (parts[0].toLowerCase() !== '!setpermission') return;
    if (parts[1]?.toLowerCase() !== 'access') return;

    const targetId = parts[2]?.replace(/[<@!>]/g, '');
    if (!targetId) return message.reply('> ❌ **الاستخدام:** `!setpermission access @user`');

    const member = await message.guild.members.fetch(targetId).catch(() => null);
    if (!member) return message.reply('> ❌ **المستخدم مو موجود في السيرفر!**');

    if (setPermAllowedUsers.has(targetId)) {
        setPermAllowedUsers.delete(targetId);
        return message.reply(`> 🚫 **تم سحب صلاحية \`!setpermission\` من <@${targetId}>**`);
    } else {
        setPermAllowedUsers.add(targetId);
        return message.reply(`> ✅ **تم منح <@${targetId}> صلاحية استخدام \`!setpermission\`**`);
    }
});

client.on('messageCreate', async (message) => {
    if (message.author.bot) return;
    if (!message.guild) return;

    
    const hasAccess = isOwnerOrGranted(message.author.id, '!setpermission') || setPermAllowedUsers.has(message.author.id);
    if (!hasAccess) return;

    const content = message.content.trim();
    if (!content.toLowerCase().startsWith('!setpermission')) return;

    const parts = content.split(/\s+/);

    
    if (parts[1]?.toLowerCase() === 'access') return;

    const roleRaw = parts[1];
    const targetRaw = parts[2];

    if (!roleRaw || !targetRaw) {
        return message.reply(
            '> ❌ **الاستخدام الصحيح:**\n' +
            '> `!setpermission @role #channel`\n' +
            '> `!setpermission @role category:ID`\n' +
            '> `!setpermission @role all`\n' +
            '> *(للأوناروز)* `!setpermission access @user` — لمنح صلاحية الأمر'
        );
    }

    
    const roleId = roleRaw.replace(/[<@&>]/g, '');
    const role = message.guild.roles.cache.get(roleId);
    if (!role) return message.reply('> ❌ **الرول مو موجود!**');

    
    let targetChannels = [];
    let targetLabel = '';

    
    if (targetRaw.toLowerCase() === 'all') {
        
        targetChannels = message.guild.channels.cache.filter(c => c.type !== 'GUILD_CATEGORY').map(c => c);
        targetLabel = '**كل الرومات** (' + targetChannels.length + ' روم)';
    } else {
        
        const rawId = targetRaw.toLowerCase().startsWith('category:')
            ? targetRaw.split(':')[1]
            : targetRaw.replace(/[<#>]/g, '');

        const ch = message.guild.channels.cache.get(rawId);
        if (!ch) return message.reply('> ❌ **الروم أو الكاتجوري مو موجود!** تأكد من الـ ID أو المنشن');

        if (ch.type === 'GUILD_CATEGORY') {
            
            targetChannels = message.guild.channels.cache.filter(c => c.parentId === ch.id && c.type !== 'GUILD_CATEGORY').map(c => c);
            if (targetChannels.length === 0) return message.reply('> ⚠️ **ما فيه رومات داخل هذا الكاتجوري!**');
            targetLabel = 'كاتجوري **' + ch.name + '** (' + targetChannels.length + ' روم)';
        } else {
            
            targetChannels = [ch];
            targetLabel = 'روم <#' + ch.id + '>';
        }
    }

    
    const buildPermEmbed = (selected) => {
        const lines = ALL_PERMISSIONS.map(p => {
            const state = selected[p.key];
            let stateIcon = '⬜'; 
            if (state === true) stateIcon = '✅';
            if (state === false) stateIcon = '❌';
            return `${stateIcon} ${p.emoji} \`${p.label}\``;
        });

        
        const col1 = lines.slice(0, Math.ceil(lines.length / 2)).join('\n');
        const col2 = lines.slice(Math.ceil(lines.length / 2)).join('\n');

        return new MessageEmbed()
            .setColor(serverColor)
            .setTitle(`⚙️ إعداد صلاحيات الرول`)
            .setDescription(
                `**الرول:** <@&${role.id}>\n**الهدف:** ${targetLabel}\n\n` +
                `**اختر نوع التطبيق ثم اضغط الصلاحية:**\n` +
                `✅ = تفعيل | ❌ = تعطيل | ⬜ = محايد`
            )
            .addFields(
                { name: 'الصلاحيات (١)', value: col1, inline: true },
                { name: 'الصلاحيات (٢)', value: col2, inline: true }
            )
            .setFooter({ text: 'اضغط الصلاحية من القائمة المنسدلة ثم اضغط "تطبيق" عند الانتهاء' });
    };

    
    const buildComponents = (mode, selected) => {
        
        const modeRow = new MessageActionRow().addComponents(
            new MessageButton().setCustomId(`sp_mode_allow_${message.id}`).setLabel('✅ تفعيل').setStyle(mode === 'allow' ? 'SUCCESS' : 'SECONDARY'),
            new MessageButton().setCustomId(`sp_mode_deny_${message.id}`).setLabel('❌ تعطيل').setStyle(mode === 'deny' ? 'DANGER' : 'SECONDARY'),
            new MessageButton().setCustomId(`sp_mode_neutral_${message.id}`).setLabel('⬜ محايد').setStyle(mode === 'neutral' ? 'PRIMARY' : 'SECONDARY'),
        );

        
        const options = ALL_PERMISSIONS.map(p => {
            const state = selected[p.key];
            let desc = 'محايد';
            if (state === true) desc = '✅ مفعّل';
            if (state === false) desc = '❌ معطّل';
            return {
                label: `${p.emoji} ${p.label}`,
                value: p.key,
                description: desc,
                default: false,
            };
        });

        const selectRow = new MessageActionRow().addComponents(
            new (require('discord.js').MessageSelectMenu)()
                .setCustomId(`sp_select_${message.id}`)
                .setPlaceholder('اختر صلاحية لتعديلها...')
                .addOptions(options.slice(0, 25)) 
                .setMinValues(1)
                .setMaxValues(1)
        );

        
        const actionRow = new MessageActionRow().addComponents(
            new MessageButton().setCustomId(`sp_apply_${message.id}`).setLabel('✔️ تطبيق').setStyle('SUCCESS'),
            new MessageButton().setCustomId(`sp_reset_${message.id}`).setLabel('🔄 مسح الكل').setStyle('SECONDARY'),
            new MessageButton().setCustomId(`sp_cancel_${message.id}`).setLabel('✖️ إلغاء').setStyle('DANGER'),
        );

        return [modeRow, selectRow, actionRow];
    };

    
    const session = {
        roleId: role.id,
        targetChannels: targetChannels.map(c => c.id),
        selected: {}, 
        mode: 'allow',
        authorId: message.author.id,
    };

    const sentMsg = await message.channel.send({
        embeds: [buildPermEmbed(session.selected)],
        components: buildComponents(session.mode, session.selected),
    });

    session.msgId = sentMsg.id;
    setPermSessions.set(sentMsg.id, session);

    
    const spCollector = sentMsg.createMessageComponentCollector({
        filter: i => i.user.id === message.author.id && (
            i.customId.endsWith(`_${message.id}`)
        ),
        time: 120000,
    });

    spCollector.on('collect', async i => {
        const sess = setPermSessions.get(sentMsg.id);
        if (!sess) return i.deferUpdate().catch(() => {});

        await i.deferUpdate().catch(() => {});

        if (i.customId.startsWith('sp_mode_allow_')) {
            sess.mode = 'allow';
        } else if (i.customId.startsWith('sp_mode_deny_')) {
            sess.mode = 'deny';
        } else if (i.customId.startsWith('sp_mode_neutral_')) {
            sess.mode = 'neutral';
        } else if (i.customId.startsWith('sp_select_')) {
            const permKey = i.values[0];
            if (sess.mode === 'allow') sess.selected[permKey] = true;
            else if (sess.mode === 'deny') sess.selected[permKey] = false;
            else delete sess.selected[permKey]; 
        } else if (i.customId.startsWith('sp_reset_')) {
            sess.selected = {};
        } else if (i.customId.startsWith('sp_cancel_')) {
            setPermSessions.delete(sentMsg.id);
            spCollector.stop('cancelled');
            await sentMsg.edit({ embeds: [new MessageEmbed().setColor('RED').setDescription('> ❌ **تم الإلغاء.**')], components: [] }).catch(() => {});
            return;
        } else if (i.customId.startsWith('sp_apply_')) {
            
            const permCount = Object.keys(sess.selected).length;
            if (permCount === 0) {
                await sentMsg.edit({
                    embeds: [buildPermEmbed(sess.selected).setFooter({ text: '⚠️ ما اخترت أي صلاحية!' })],
                    components: buildComponents(sess.mode, sess.selected),
                }).catch(() => {});
                return;
            }

            await sentMsg.edit({
                embeds: [new MessageEmbed().setColor(serverColor).setDescription(`> ⏳ **جاري تطبيق الصلاحيات على ${sess.targetChannels.length} روم...**`)],
                components: [],
            }).catch(() => {});

            spCollector.stop('applied');
            setPermSessions.delete(sentMsg.id);

            
            const permObj = {};
            for (const [key, val] of Object.entries(sess.selected)) {
                permObj[key] = val; 
            }
            

            let successCount = 0;
            let failCount = 0;
            const targetRole = message.guild.roles.cache.get(sess.roleId);

            for (const chId of sess.targetChannels) {
                try {
                    const ch = message.guild.channels.cache.get(chId);
                    if (!ch) { failCount++; continue; }
                    await ch.permissionOverwrites.edit(targetRole, permObj);
                    successCount++;
                } catch(e) {
                    failCount++;
                }
            }

            
            const appliedLines = ALL_PERMISSIONS
                .filter(p => sess.selected[p.key] !== undefined)
                .map(p => {
                    const val = sess.selected[p.key];
                    return `${val ? '✅' : '❌'} ${p.emoji} \`${p.label}\``;
                }).join(' | ');

            await sentMsg.edit({
                embeds: [
                    new MessageEmbed()
                        .setColor(successCount > 0 ? 'GREEN' : 'RED')
                        .setTitle('✅ تم تطبيق الصلاحيات')
                        .setDescription(
                            `**الرول:** <@&${sess.roleId}>\n` +
                            `**الهدف:** ${targetLabel}\n\n` +
                            `**الصلاحيات المطبقة:**\n${appliedLines}`
                        )
                        .addFields(
                            { name: '✅ نجح', value: `${successCount} روم`, inline: true },
                            { name: '❌ فشل', value: `${failCount} روم`, inline: true },
                        )
                        .setTimestamp()
                ],
                components: [],
            }).catch(() => {});
            return;
        }

        
        await sentMsg.edit({
            embeds: [buildPermEmbed(sess.selected)],
            components: buildComponents(sess.mode, sess.selected),
        }).catch(() => {});
    });

    spCollector.on('end', (_, reason) => {
        if (reason !== 'applied' && reason !== 'cancelled') {
            sentMsg.edit({
                embeds: [new MessageEmbed().setColor('GREY').setDescription('> ⏱️ **انتهى الوقت — تم الإلغاء تلقائياً.**')],
                components: [],
            }).catch(() => {});
            setPermSessions.delete(sentMsg.id);
        }
    });
});

const GRANTED_ACCESS_FILE = './grantedAccess.json';

function loadGrantedAccess() {
    try {
        if (fs.existsSync(GRANTED_ACCESS_FILE)) {
            const raw = fs.readFileSync(GRANTED_ACCESS_FILE, 'utf8');
            const obj = JSON.parse(raw);
            const map = new Map();
            for (const [userId, cmds] of Object.entries(obj)) {
                const cmdMap = new Map();
                for (const [cmd, entry] of Object.entries(cmds)) {
                    cmdMap.set(cmd, entry);
                }
                map.set(userId, cmdMap);
            }
            console.log(`✅ تم تحميل الصلاحيات المفوضة: ${map.size} مستخدم`);
            return map;
        }
    } catch (e) {
        console.error('❌ خطأ في تحميل grantedAccess.json:', e);
    }
    return new Map();
}

function saveGrantedAccess() {
    try {
        const obj = {};
        for (const [userId, cmdMap] of grantedAccess.entries()) {
            obj[userId] = {};
            for (const [cmd, entry] of cmdMap.entries()) {
                obj[userId][cmd] = entry;
            }
        }
        fs.writeFileSync(GRANTED_ACCESS_FILE, JSON.stringify(obj, null, 2), 'utf8');
    } catch (e) {
        console.error('❌ خطأ في حفظ grantedAccess.json:', e);
    }
}

const grantedAccess = loadGrantedAccess();

function parseAccessLimit(raw) {
    if (!raw) return null;

    
    if (raw.toLowerCase() === 'inf') {
        return { type: 'infinite', label: '♾️ لانهائي' };
    }

    
    const timeMatch = raw.match(/^(\d+)(s|m|h|d|w)$/i);
    if (timeMatch) {
        const num = parseInt(timeMatch[1]);
        const unit = timeMatch[2].toLowerCase();
        const msMap = { s: 1000, m: 60000, h: 3600000, d: 86400000, w: 604800000 };
        const labels = { s: 'ثانية', m: 'دقيقة', h: 'ساعة', d: 'يوم', w: 'أسبوع' };
        return { type: 'time', expiresAt: Date.now() + num * msMap[unit], label: `${num} ${labels[unit]}` };
    }

    
    const countMatch = raw.match(/^(\d+)$/);
    if (countMatch) {
        const n = parseInt(countMatch[1]);
        return { type: 'count', times: n, label: `${n} مرة` };
    }

    return null;
}

function checkGrantedAccess(userId, cmd) {
    const userMap = grantedAccess.get(userId);
    if (!userMap) return false;

    const access = userMap.get(cmd);
    if (!access) return false;

    
    if (access.infinite) return true;

    
    if (access.expiresAt !== undefined) {
        if (Date.now() > access.expiresAt) {
            userMap.delete(cmd);
            if (userMap.size === 0) grantedAccess.delete(userId);
            saveGrantedAccess();
            return false;
        }
        return true;
    }

    
    if (access.times !== undefined) {
        if (access.times <= 0) {
            userMap.delete(cmd);
            if (userMap.size === 0) grantedAccess.delete(userId);
            saveGrantedAccess();
            return false;
        }
        access.times--;
        
        if (access.times <= 0) {
            userMap.delete(cmd);
            if (userMap.size === 0) grantedAccess.delete(userId);
        }
        saveGrantedAccess();
        return true;
    }

    return false;
}

function isOwnerOrGranted(userId, cmd) {
    return isActiveOwner(userId) || checkGrantedAccess(userId, cmd);
}

/** لون آمن للإيمبد — قيمة serverColor خاطئة تكسر الإرسال بدون رسالة */
function resolveEmbedColor(input) {
    const fallback = '#c8ae03';
    if (input == null || typeof input !== 'string') return fallback;
    const s = input.trim();
    if (/^#[0-9A-Fa-f]{6}$/i.test(s)) return s;
    if (/^#[0-9A-Fa-f]{3}$/i.test(s)) return s;
    if (/^[0-9A-Fa-f]{6}$/i.test(s)) return '#' + s;
    return fallback;
}

