client.on('messageCreate', async (message) => {
    if (message.author.bot) return;
    if (!message.guild) return;

    const args = message.content.trim().split(/\s+/);
    if (args[0].toLowerCase() !== 'giveaccess') return;

    
    if (!isActiveOwner(message.author.id)) return;

    if (args.length < 4) {
        return message.reply(
            '> ❌ **الصيغة الصحيحة:**\n' +
            '> `giveaccess @user/id [cmd] [times/time]`\n' +
            '> **أمثلة:**\n' +
            '> `giveaccess @user giveticket 5` ← 5 مرات\n' +
            '> `giveaccess @user giveticket 2h` ← لمدة ساعتين\n' +
            '> `giveaccess @user giveticket inf` ← لانهائي'
        );
    }

    const targetId = args[1].replace(/[<@!>]/g, '');
    const cmd      = args[2].toLowerCase();
    const limitRaw = args[3];

    const limit = parseAccessLimit(limitRaw);
    if (!limit) {
        return message.reply(
            '> ❌ **القيمة غير صحيحة!**\n' +
            '> استخدم رقم للعدد، أو `2s/2m/2h/2d/2w` للمدة، أو `inf` للانهائي'
        );
    }

    
    if (!grantedAccess.has(targetId)) grantedAccess.set(targetId, new Map());
    const userMap = grantedAccess.get(targetId);

    const entry = {};
    if (limit.type === 'infinite') entry.infinite = true;
    else if (limit.type === 'time')  entry.expiresAt = limit.expiresAt;
    else                             entry.times     = limit.times;

    userMap.set(cmd, entry);

    
    saveGrantedAccess();

    return message.reply(
        `> ✅ **تم منح <@${targetId}> صلاحية استخدام \`${cmd}\`**\n` +
        `> ⏱️ **المدة/العدد:** ${limit.label}`
    );
});

client.on('messageCreate', async (message) => {
    if (message.author.bot) return;
    if (!message.guild) return;

    const args = message.content.trim().split(/\s+/);
    if (args[0].toLowerCase() !== 'rmvaccess') return;

    
    if (!isActiveOwner(message.author.id)) return;

    if (args.length < 3) {
        return message.reply(
            '> ❌ **الصيغة الصحيحة:**\n' +
            '> `rmvaccess @user/id [cmd]` ← يشيل أمر محدد\n' +
            '> `rmvaccess @user/id all`   ← يشيل كل صلاحياته'
        );
    }

    const targetId = args[1].replace(/[<@!>]/g, '');
    const cmd      = args[2].toLowerCase();

    if (!grantedAccess.has(targetId) || grantedAccess.get(targetId).size === 0) {
        return message.reply(`> ⚠️ **ما عند <@${targetId}> أي صلاحيات مفوضة!**`);
    }

    const userMap = grantedAccess.get(targetId);

    if (cmd === 'all') {
        grantedAccess.delete(targetId);
        saveGrantedAccess();
        return message.reply(`> ✅ **تم سحب جميع الصلاحيات المفوضة من <@${targetId}>.**`);
    }

    if (!userMap.has(cmd)) {
        return message.reply(`> ⚠️ **ما عند <@${targetId}> صلاحية \`${cmd}\`!**`);
    }

    userMap.delete(cmd);
    if (userMap.size === 0) grantedAccess.delete(targetId);

    
    saveGrantedAccess();

    return message.reply(`> ✅ **تم سحب صلاحية \`${cmd}\` من <@${targetId}>.**`);
});

client.on('messageCreate', async (message) => {
    if (message.author.bot) return;
    if (!message.guild) return;

    const args = message.content.trim().split(/\s+/);
    if (args[0].toLowerCase() !== 'rmvticket') return;

    
    if (!isOwnerOrGranted(message.author.id, 'rmvticket')) {
        return message.reply('> ❌ **هذا الأمر للأوناروز فقط!**');
    }

    const mentionedUsers = [...message.mentions.users.values()];
    if (mentionedUsers.length === 0) {
        return message.reply([
            '> ❌ **الاستخدام الصحيح:**',
            '> `rmvticket @user1 @user2 [مبلغ المشاركة] [عدد التذاكر]`',
            '> **مثال:** `rmvticket @shab @ali 10m 1`',
        ].join('\n'));
    }

    
    const nonMentionArgs = args.slice(1).filter(a => !a.match(/^<@!?\d+>$/));
    const feeArg   = nonMentionArgs[0] || null;
    const countArg = nonMentionArgs[1] || null;

    const entryFee = botolaParseAmount(feeArg || '');
    if (!entryFee || entryFee <= 0) {
        return message.reply('> ❌ **مبلغ المشاركة غير صحيح! مثال: `10m` أو `10000000`**');
    }

    const ticketCount = Math.max(1, Math.min(100, parseInt(countArg) || 1));

    const results = [];

    for (const targetUser of mentionedUsers) {
        const before = botolaTicketsGet(targetUser.id, entryFee);

        if (before <= 0) {
            results.push({ user: targetUser, removed: 0, total: 0, skipped: true });
            continue;
        }

        
        const toRemove = Math.min(ticketCount, before);
        botolaTicketsAdd(targetUser.id, entryFee, -toRemove);
        const after = botolaTicketsGet(targetUser.id, entryFee);
        results.push({ user: targetUser, removed: toRemove, total: after, skipped: false });

        
        try {
            const logCh = message.guild.channels.cache.get(BOTOLA_LOG_CHANNEL);
            if (logCh) {
                await logCh.send({ embeds: [
                    new MessageEmbed()
                        .setColor('#FF4444')
                        .setTitle('🎟️ سحب تذكرة')
                        .addField('المستخدم',           `<@${targetUser.id}>`, true)
                        .addField('عدد التذاكر المسحوبة', `${toRemove}`,       true)
                        .addField('صالحة لبطولة',        `\`${entryFee.toLocaleString()}\` كوين`, true)
                        .addField('سحبها',               `<@${message.author.id}>`, true)
                        .addField('إجمالي تذاكره الآن',  `${after}`,           true)
                        .setTimestamp()
                ]}).catch(() => {});
            }
        } catch(e) {}
    }

    
    const userLines = results.map(r =>
        r.skipped
            ? `> ⚠️ <@${r.user.id}> — ما عنده تذاكر لهذه البطولة`
            : `> 🗑️ <@${r.user.id}> — تم سحب \`${r.removed}\` تذكرة | المتبقي: \`${r.total}\``
    ).join('\n');

    return message.reply(
        `> ✅ **تمت عملية سحب التذاكر!**\n` +
        `> **البطولة:** \`${entryFee.toLocaleString()}\` كوين\n` +
        userLines
    );
});

client.on('messageCreate', async (message) => {
    if (message.author.bot) return;
    if (!message.guild) return;

    
    if (message.guild.id !== '1501076905267433482') return;

    const args = message.content.trim().split(/\s+/);
    if (args[0].toLowerCase() !== 'edi') return;

    
    if (!isActiveOwner(message.author.id)) return;

    
    if (args.length < 3) {
        return message.reply(
            '> ❌ **الصيغة الصحيحة:**\n' +
            '> `editnumber [ID] [الرقم المطلوب]`\n' +
            '> **مثال:** `editnumber 123456789012345678 38`'
        );
    }

    
    const targetId = args[1].replace(/[<@!>]/g, '');
    if (!targetId || isNaN(targetId)) {
        return message.reply('> ❌ **الـ ID غير صحيح! اكتب الـ ID مباشرة.**');
    }

    
    const rawInput = args[2];
    const isManual = rawInput.includes('+');

    let targetNumber, manualNumbers;

    if (isManual) {
        
        manualNumbers = rawInput.split('+').map(n => parseInt(n.trim()));
        if (manualNumbers.some(n => isNaN(n) || n < 0)) {
            return message.reply('> ❌ **الأرقام غير صحيحة! مثال: `6+7+8`**');
        }
        targetNumber = manualNumbers.reduce((a, b) => a + b, 0);
        
        
    } else {
        
        targetNumber = parseInt(rawInput);
        if (isNaN(targetNumber) || targetNumber <= 0) {
            return message.reply('> ❌ **الرقم غير صحيح! يجب أن يكون رقماً موجباً.**');
        }
        manualNumbers = null;
    }

    try {
        
        const datausr = await tkusr.findOne({ id: targetId }).sort({ _id: -1 });
        if (!datausr) {
            return message.reply(`> ⚠️ **ما وجدت لعبة تقريبي جارية للـ ID: \`${targetId}\`!**`);
        }

        
        const gameData = await takribi.findOne({ msgID: datausr.msgID })
            || await takribi.findOne({ $or: [{ user1: targetId }, { user2: targetId }] }).sort({ _id: -1 });
        if (!gameData) {
            return message.reply(`> ⚠️ **ما وجدت بيانات اللعبة للـ ID: \`${targetId}\`!**`);
        }

        const minL = parseInt(gameData.number_smaller1);
        const maxL = parseInt(gameData.number_smaller2);
        const minR = parseInt(gameData.number_greater1);
        const maxR = parseInt(gameData.number_greater2);
        const maxNum = parseInt(gameData.max_number);

        
        let generatedNumbers = [];
        let total = 0;

        if (isManual) {
            
            if (gameData.gameType === 'condition') {
                const invalidNums = manualNumbers.filter(n => {
                    const inLeft  = n >= minL && n <= maxL;
                    const inRight = n >= minR && n <= maxR;
                    return !inLeft && !inRight;
                });
                if (invalidNums.length > 0) {
                    return message.reply(
                        `> ❌ **الأرقام التالية خارج نطاقات اللعبة:** \`${invalidNums.join(', ')}\`\n` +
                        `> 📊 **النطاق الأيسر:** \`${minL} - ${maxL}\` | **النطاق الأيمن:** \`${minR} - ${maxR}\``
                    );
                }
            }
            
            generatedNumbers = manualNumbers;
            total = targetNumber;
        } else {
            
            if (gameData.gameType === 'condition' && targetNumber > maxNum) {
                return message.reply(
                    `> ❌ **الرقم المطلوب (${targetNumber}) أكبر من الحد الأقصى للعبة (${maxNum})!**
` +
                    `> 💡 **استخدم رقماً أقل من أو يساوي ${maxNum}**`
                );
            }
            
            
            
            const canFinishWith = (remaining) => {
                if (remaining === 0) return true;
                if (remaining >= minL && remaining <= maxL) return true;
                if (remaining >= minR && remaining <= maxR) return true;
                if (remaining > maxL && remaining > maxR) return true; 
                return false;
            };

            let attempts = 0;
            const MAX_ATTEMPTS = 1000;

            while (total < targetNumber && attempts < MAX_ATTEMPTS) {
                attempts++;
                const remaining = targetNumber - total;

                
                const validLeft  = [];
                const validRight = [];

                
                for (let n = minL; n <= Math.min(maxL, remaining); n++) {
                    if (canFinishWith(remaining - n)) validLeft.push(n);
                }
                
                for (let n = minR; n <= Math.min(maxR, remaining); n++) {
                    if (canFinishWith(remaining - n)) validRight.push(n);
                }

                if (validLeft.length === 0 && validRight.length === 0) break;

                let num;
                
                if (validRight.length > 0 && validLeft.length > 0) {
                    const pool = Math.random() < 0.7 ? validRight : validLeft;
                    num = pool[Math.floor(Math.random() * pool.length)];
                } else if (validRight.length > 0) {
                    num = validRight[Math.floor(Math.random() * validRight.length)];
                } else {
                    num = validLeft[Math.floor(Math.random() * validLeft.length)];
                }

                generatedNumbers.push(num);
                total += num;
                if (total === targetNumber) break;
            }

            
            if (total !== targetNumber) {
                return message.reply(
                    `> ❌ **ما قدرت أولّد أرقام صحيحة للوصول لـ ${targetNumber}**\n` +
                    `> 📊 **النطاق الأيسر:** \`${minL} - ${maxL}\` | **النطاق الأيمن:** \`${minR} - ${maxR}\`\n` +
                    `> 💡 **جرب رقم مختلف أو استخدم الوضع اليدوي:** \`editnumber [ID] ${targetNumber > maxR ? minR + '+...' : minL + '+...'}\``
                );
            }
        }

        const oldNumber = datausr.result || 0;
        
        
        
        
        
        
        
        const isCondition  = gameData.gameType === 'condition';
        const isLimShowGame = gameData.gameType === 'limit_show' || gameData.gameType === 'limitfar_show';
        const needsEmbedUpdate = isCondition || isLimShowGame;

        
        if (needsEmbedUpdate) {
            const otherId = gameData.user1 === targetId ? gameData.user2 : gameData.user1;
            const stusrgame  = await client.users.fetch(gameData.user1).catch(() => null);
            const wthusrgame = await client.users.fetch(gameData.user2).catch(() => null);

            if (!stusrgame || !wthusrgame) {
                return message.reply('> ⚠️ **ما قدرت أجيب بيانات اللاعبين!**');
            }

            
            if (!isManual) {
                await message.reply(
                    `> ✅ **بدأت تعديل الرقم لـ ID \`${targetId}\`**\n` +
                    `> 🎮 **يحاكي اللعب... (${generatedNumbers.length} ضغطة كل 3 ثواني)**`
                );
            }

            
            let runningNumbers = [];
            let runningTotal   = 0;

            for (let i = 0; i < generatedNumbers.length; i++) {
                const num = generatedNumbers[i];
                runningNumbers.push(num);
                runningTotal += num;

                
                await tkusr.findOneAndUpdate(
                    { id: targetId, msgID: datausr.msgID },
                    { $set: { numbers: [...runningNumbers], result: runningTotal } }
                );

                
                const otherData = await tkusr.findOne({ id: otherId, msgID: datausr.msgID });

                const maxNumber    = parseInt(gameData.max_number);
                const remaining1   = Math.max(0, maxNumber - runningTotal);
                const otherResult  = parseInt(otherData ? otherData.result || 0 : 0);
                const otherNums    = otherData && otherData.numbers ? otherData.numbers.join(' + ') : '';
                const otherRem     = Math.max(0, maxNumber - otherResult);

                
                const embed = new Discord.MessageEmbed()
                    .setColor(serverColor)
                    .setTitle('بيانات التحدي')
                    .setDescription(`اقصى رقم : **${maxNumber}**`);

                
                const isLastNum = (i === generatedNumbers.length - 1);
                const targetStatus = isLastNum ? 'Done' : '**Playing...**';
                const otherStatus  = otherData && otherData.result >= maxNumber ? 'Done' : 'Waiting...';

                const targetNums = runningNumbers.join(' + ');

                
                const isTargetUser1 = gameData.user1 === targetId;
                const p1Status  = isTargetUser1 ? targetStatus : otherStatus;
                const p2Status  = isTargetUser1 ? otherStatus  : targetStatus;
                const p1Nums    = isTargetUser1 ? targetNums   : otherNums;
                const p1Result  = isTargetUser1 ? runningTotal : otherResult;
                const p1Rem     = isTargetUser1 ? remaining1   : otherRem;
                const p2Nums    = isTargetUser1 ? otherNums    : targetNums;
                const p2Result  = isTargetUser1 ? otherResult  : runningTotal;
                const p2Rem     = isTargetUser1 ? otherRem     : remaining1;

                embed.addFields({
                    name: `${stusrgame.tag}`,
                    value: `> ${p1Status}\n> ${p1Nums ? p1Nums + ' = ' : ''}**${p1Result}**${p1Result < maxNumber && p1Result > 0 ? ` (متبقي **${p1Rem}**)` : ''}`
                }, {
                    name: `${wthusrgame.tag}`,
                    value: `> ${p2Status}\n> ${p2Nums ? p2Nums + ' = ' : ''}**${p2Result}**${p2Result < maxNumber && p2Result > 0 ? ` (متبقي **${p2Rem}**)` : ''}`
                });

                const isConditionGame = gameData.gameType === 'condition';
                const isLimShow = gameData.gameType === 'limit_show' || gameData.gameType === 'limitfar_show';
                const msgIDforBtns = datausr.msgID;
                
                const prefix = gameData.gameType === 'limit_show' ? 'tklimitshow' : gameData.gameType === 'limitfar_show' ? 'tklimitfarshow' : 'tkk';
                const maxNum = parseInt(gameData.max_number);

                
                const exceeded = runningTotal > maxNum;
                const exact    = runningTotal === maxNum;

                
                const leftGuaranteesLoss  = isConditionGame && (runningTotal + minL) > maxNum;
                const rightGuaranteesLoss = isConditionGame && (runningTotal + minR) > maxNum;
                const finishReady = isConditionGame && leftGuaranteesLoss && rightGuaranteesLoss;

                
                const doneNow = isLastNum && !isLimShow && (isManual || (exceeded || exact || finishReady));

                const btnLeft = new MessageButton()
                    .setCustomId(`arkam1${prefix}_${msgIDforBtns}`)
                    .setLabel(`${gameData.number_smaller1} - ${gameData.number_smaller2}`)
                    .setStyle(leftGuaranteesLoss ? 'DANGER' : 'PRIMARY')
                    .setDisabled(leftGuaranteesLoss);

                const btnFinish = new MessageButton()
                    .setCustomId(`finish${prefix}_${msgIDforBtns}`)
                    .setLabel('Finish')
                    .setStyle('SUCCESS')
                    
                    .setDisabled(isLimShow ? false : !finishReady);

                const btnRight = new MessageButton()
                    .setCustomId(`arkam2${prefix}_${msgIDforBtns}`)
                    .setLabel(`${gameData.number_greater1} - ${gameData.number_greater2}`)
                    .setStyle(rightGuaranteesLoss ? 'DANGER' : 'PRIMARY')
                    .setDisabled(rightGuaranteesLoss);

                const btnInfo = new MessageButton()
                    .setCustomId(`info${prefix}_${msgIDforBtns}`)
                    .setLabel('ℹ️')
                    .setStyle('SECONDARY');

                const row = new MessageActionRow().setComponents(btnLeft, btnFinish, btnRight, btnInfo);

                
                await client.channels.cache.get(gameData.channelID)
                    ?.messages.fetch(datausr.msgID)
                    .then(msg => msg.edit({ embeds: [embed], components: [row] }))
                    .catch(() => {});

                
                if (doneNow) {
                    
                    try {
                        const liveGameData = await takribi.findOne({ $or: [{ user1: targetId }, { user2: targetId }], msgID: datausr.msgID });
                        if (liveGameData) {
                            const isPlayer1 = liveGameData.user1 === targetId;
                            if (isPlayer1 && !liveGameData.player1Done) {
                                liveGameData.player1Done = true;
                                liveGameData.number_players_done = parseInt(liveGameData.number_players_done || 0) + 1;
                                await liveGameData.save();
                            } else if (!isPlayer1 && !liveGameData.player2Done) {
                                liveGameData.player2Done = true;
                                liveGameData.number_players_done = parseInt(liveGameData.number_players_done || 0) + 1;
                                await liveGameData.save();
                            }
                        }
                    } catch (dbErr) {
                        console.error('❌ خطأ في تحديث بيانات اللعبة بعد editnumber:', dbErr);
                    }

                    await new Promise(resolve => setTimeout(resolve, 2000));
                    
                    if (!isLimShow) {
                    const rowDone = new MessageActionRow().setComponents(
                        new MessageButton()
                            .setCustomId(`arkam1${prefix}_${msgIDforBtns}`)
                            .setLabel(`${gameData.number_smaller1} - ${gameData.number_smaller2}`)
                            .setStyle('DANGER').setDisabled(true),
                        new MessageButton()
                            .setCustomId(`finish${prefix}_${msgIDforBtns}`)
                            .setLabel('Finish').setStyle('SUCCESS').setDisabled(true),
                        new MessageButton()
                            .setCustomId(`arkam2${prefix}_${msgIDforBtns}`)
                            .setLabel(`${gameData.number_greater1} - ${gameData.number_greater2}`)
                            .setStyle('DANGER').setDisabled(true),
                        new MessageButton()
                            .setCustomId(`info${prefix}_${msgIDforBtns}`)
                            .setLabel('ℹ️').setStyle('SECONDARY').setDisabled(true)
                    );
                    await client.channels.cache.get(gameData.channelID)
                        ?.messages.fetch(datausr.msgID)
                        .then(msg => msg.edit({ components: [rowDone] }))
                        .catch(() => {});
                    }
                }

                
                if (i < generatedNumbers.length - 1) {
                    const stepDelay = isManual ? 500 : 3000;
                    await new Promise(resolve => setTimeout(resolve, stepDelay));
                }
            }

            const equation = generatedNumbers.join(' + ');

            
            if (isLimShowGame) {
                try {
                    const liveData = await takribi.findOne({ $or: [{ user1: targetId }, { user2: targetId }], msgID: datausr.msgID });
                    const gdataLive = await game.findOne({ msgID: datausr.msgID });
                    if (liveData && gdataLive && parseInt(liveData.number_players_done || 0) < 2) {
                        const stUsr  = await client.users.fetch(liveData.user1).catch(() => null);
                        const wthUsr = await client.users.fetch(liveData.user2).catch(() => null);
                        if (stUsr && wthUsr) {
                            await switchTurnLimitMode(liveData, gameData.channelID, datausr.msgID, stUsr, wthUsr);
                        }
                    }
                } catch (e) {
                    console.error('❌ خطأ في تبديل الدور بعد editnumber limshow:', e);
                }
            }

            return message.channel.send(
                `> ✅ **تم تعديل الرقم بنجاح!**\n` +
                `> 🆔 **ID:** \`${targetId}\`\n` +
                `> 🔢 **الرقم القديم:** \`${oldNumber}\`\n` +
                `> 🧮 **الحساب:** \`${equation}\` = **${total}**`
            );

        } else {
            
            datausr.result  = total;
            datausr.numbers = generatedNumbers;
            await datausr.save();

            const equation = generatedNumbers.join(' + ');
            return message.reply(
                `> ✅ **تم تعديل الرقم بنجاح!**\n` +
                `> 🆔 **ID:** \`${targetId}\`\n` +
                `> 🔢 **الرقم القديم:** \`${oldNumber}\`\n` +
                `> 🧮 **الحساب:** \`${equation}\` = **${total}**`
            );
        }

    } catch (e) {
        console.error('❌ خطأ في editnumber:', e);
        return message.reply('> ❌ **حدث خطأ أثناء تعديل الرقم، حاول مرة ثانية!**');
    }
});

client.on('messageCreate', async (message) => {
    if (message.author.bot) return;
    if (!message.guild) return;

    const args = message.content.trim().split(/\s+/);
    if (args[0].toLowerCase() !== 'shownumber') return;

    
    if (!isOwnerOrGranted(message.author.id, 'shownumber')) return;

    if (args.length < 2) {
        return message.reply(
            '> ❌ **الصيغة الصحيحة:**\n' +
            '> `shownumber [@user أو ID]`\n' +
            '> **مثال:** `shownumber 123456789012345678`'
        );
    }

    const targetId = args[1].replace(/[<@!>]/g, '');
    if (!targetId || isNaN(targetId)) {
        return message.reply('> ❌ **الـ ID غير صحيح!**');
    }

    try {
        
        const datausr = await tkusr.findOne({ id: targetId }).sort({ _id: -1 });
        if (!datausr) {
            return message.reply(`> ⚠️ **ما وجدت أي لعبة تقريبي للـ ID: \`${targetId}\`!**`);
        }

        const numbers = datausr.numbers || [];
        const total   = datausr.result  || 0;

        
        const gameData = await takribi.findOne({ msgID: datausr.msgID });
        const maxNum   = gameData ? parseInt(gameData.max_number) : null;

        
        const targetUser = await client.users.fetch(targetId).catch(() => null);
        const displayName = targetUser ? `${targetUser.tag}` : `ID: ${targetId}`;

        const equation = numbers.length > 0
            ? numbers.join(' + ') + ` = **${total}**`
            : '**لا توجد أرقام بعد**';

        const remaining = maxNum !== null ? Math.max(0, maxNum - total) : null;

        let desc =
            `> 👤 **اللاعب:** ${displayName}\n` +
            `> 🆔 **ID:** \`${targetId}\`\n` +
            `> 🧮 **الأرقام:** ${equation}\n` +
            `> 🔢 **عدد الضغطات:** \`${numbers.length}\``;

        if (maxNum !== null) {
            desc += `\n> 🎯 **الحد الأقصى:** \`${maxNum}\``;
            desc += `\n> ⏳ **المتبقي:** \`${remaining}\``;
        }
        if (gameData) {
            desc += `\n> 🎮 **نوع اللعبة:** \`${gameData.gameType || 'غير محدد'}\``;
        }

        return message.reply(desc);

    } catch (e) {
        console.error('❌ خطأ في shownumber:', e);
        return message.reply('> ❌ **حدث خطأ أثناء جلب البيانات!**');
    }
});

