async function startDuelNRDGame(channel, player1Id, player2Id, betAmount, duelId) {
    try {
        const msg = await channel.send(`🎮 | **جاري بدء لعبة النرد بين <@${player1Id}> و <@${player2Id}>**`);
        
        // Simplified version - roll dice for both
        const p1Roll = Math.floor(Math.random() * 6) + 1;
        const p2Roll = Math.floor(Math.random() * 6) + 1;
        const winner = p1Roll > p2Roll ? player1Id : p2Roll > p1Roll ? player2Id : (Math.random() > 0.5 ? player1Id : player2Id);
        
        const duelRecord = await duel.findById(duelId);
        if (duelRecord) {
            duelRecord.rounds.push({
                round_number: duelRecord.rounds.length + 1,
                winner: winner,
                game_message_id: msg.id,
                timestamp: new Date()
            });
            await duelRecord.save();
        }
        
        await new Promise(r => setTimeout(r, 2000));
        await msg.edit({ content: `🎲 نتائج النرد:\n<@${player1Id}>: **${p1Roll}**\n<@${player2Id}>: **${p2Roll}**\n\n🎉 الفائز: <@${winner}>` });
        
        return msg;
    } catch (error) {
        console.error('Error in startDuelNRDGame:', error);
        return null;
    }
}

// ═══════════════════════════════════════════════════════════════════════════════════════════
// DUEL INTERACTION HANDLERS
// ═══════════════════════════════════════════════════════════════════════════════════════════

client.on('interactionCreate', async (interaction) => {
    if (!interaction.isButton()) return;
    
    // Duel start panel button
    if (interaction.customId === 'duel_start_panel') {
        const modal = new Modal()
            .setCustomId(`duel_modal_${interaction.user.id}`)
            .setTitle('⚔️ بدء Duel')
            .addComponents(
                new MessageActionRow().addComponents(
                    new TextInputComponent()
                        .setCustomId('duel_opponent_id')
                        .setLabel('معرف الخصم (User ID)')
                        .setStyle('SHORT')
                        .setRequired(true)
                ),
                new MessageActionRow().addComponents(
                    new TextInputComponent()
                        .setCustomId('duel_amount')
                        .setLabel('المبلغ لكل جولة')
                        .setStyle('SHORT')
                        .setRequired(true)
                ),
                new MessageActionRow().addComponents(
                    new TextInputComponent()
                        .setCustomId('duel_game_type')
                        .setLabel('نوع اللعبة (takribi, dice, xo, nrd)')
                        .setStyle('SHORT')
                        .setRequired(true)
                )
            );
        
        await interaction.showModal(modal);
        return;
    }
    
    // Duel accept button
    if (interaction.customId.startsWith('duel_accept_')) {
        const duelId = interaction.customId.split('_')[2];
        const duelRecord = await duel.findById(duelId);
        
        if (!duelRecord) {
            return interaction.reply({ content: '❌ | **الـ Duel غير موجود.**', ephemeral: true });
        }
        
        if (duelRecord.challenger_id) {
            return interaction.reply({ content: '❌ | **لقد قبلها شخص آخر بالفعل!**', ephemeral: true });
        }
        
        if (interaction.user.id === duelRecord.initiator_id) {
            return interaction.reply({ content: '❌ | **لا يمكنك قبول تحديك الخاص!**', ephemeral: true });
        }
        
        // Set challenger
        duelRecord.challenger_id = interaction.user.id;
        duelRecord.status = 'active';
        duelRecord.channel_id = interaction.channel.id;
        await duelRecord.save();
        
        await interaction.reply({ content: '✅ | **قبلت الـ Duel! جاري بدء الجولة الأولى...**', ephemeral: false });
        
        // Start first round
        setTimeout(() => {
            startDuelRound(duelId, duelRecord.initiator_id, interaction.user.id);
        }, 2000);
        
        return;
    }
    
    // Duel decline button
    if (interaction.customId.startsWith('duel_decline_')) {
        const duelId = interaction.customId.split('_')[2];
        const duelRecord = await duel.findById(duelId);
        
        if (duelRecord) {
            duelRecord.status = 'cancelled';
            duelRecord.reason = 'declined';
            await duelRecord.save();
        }
        
        await interaction.reply({ content: '❌ | **تم رفض الـ Duel.**', ephemeral: true });
        return;
    }
});

// Handle modal submissions
client.on('interactionCreate', async (interaction) => {
    if (!interaction.isModalSubmit()) return;
    
    if (interaction.customId.startsWith('duel_modal_')) {
        const userId = interaction.customId.split('_')[2];
        
        if (interaction.user.id !== userId) return;
        
        const opponentId = interaction.fields.getTextInputValue('duel_opponent_id');
        const amountStr = interaction.fields.getTextInputValue('duel_amount');
        const gameType = interaction.fields.getTextInputValue('duel_game_type').toLowerCase();
        
        const amount = parseInt(amountStr);
        
        if (isNaN(amount) || amount <= 0 || amount > 10000000) {
            return interaction.reply({ content: '❌ | **المبلغ غير صحيح! يجب أن يكون بين 1 و 10,000,000**', ephemeral: true });
        }
        
        const validGameTypes = ['takribi', 'dice', 'xo', 'nrd', 'tictactoe', 'blackjack', 'coinflip', 'towers'];
        if (!validGameTypes.includes(gameType)) {
            return interaction.reply({ content: `❌ | **نوع اللعبة غير صحيح! أنواع صحيحة: ${validGameTypes.join(', ')}**`, ephemeral: true });
        }
        
        await interaction.deferReply({ ephemeral: true });
        
        // Create message to fetch user
        const targetUser = await client.users.fetch(opponentId).catch(() => null);
        if (!targetUser) {
            return interaction.followUp({ content: '❌ | **معرف الخصم غير صحيح!**' });
        }
        
        // Initiate duel using temporary message
        const tempMsg = await interaction.followUp({ content: '⏳ | **جاري معالجة الـ Duel...**' });
        await initiateDuel(tempMsg, opponentId, amount, gameType);
    }
});

