client.on('messageCreate', async (message) => {
    if (message.author.bot) return;
    const args = message.content.trim().split(/\s+/);
    if (args[0].toLowerCase() !== 'deleteteamdatauser') return;

    if (!isActiveOwner(message.author.id))
        return message.reply('> ❌ **أنت لست أونر!**');

    const targetId = message.mentions.users.first()?.id || args[1]?.replace(/[<@!>]/g, '');
    if (!targetId || isNaN(targetId))
        return message.reply('> ❌ **يرجى منشن اليوزر أو ذكر الـ ID الصحيح!**\n> **الصيغة:** `deleteteamdatauser @user`');

    try {
        let removed = false;

        
        const ownedTeam = await Team.findOne({ ownerid: targetId });
        if (ownedTeam) {
            await Team.deleteOne({ ownerid: targetId });
            removed = true;
        }

        
        const memberTeams = await Team.find({ $or: [{ players: targetId }, { admins: targetId }] });
        for (const team of memberTeams) {
            team.players = team.players.filter(id => id !== targetId);
            team.admins = team.admins.filter(id => id !== targetId);
            await team.save();
            removed = true;
        }

        if (!removed) {
            return message.reply(`> ⚠️ **<@${targetId}> غير موجود في أي فريق!**`);
        }

        return message.reply(
            `> ✅ **تم مسح بيانات <@${targetId}> من جميع الفرق بنجاح!**\n` +
            `> ${ownedTeam ? `🗑️ تم حذف فريقه \`${ownedTeam.teamtag}\` لأنه كان الأونر.\n> ` : ''}` +
            `${memberTeams.length > 0 ? `👥 تمت إزالته من ${memberTeams.length} فريق/فرق.` : ''}`
        );
    } catch (err) {
        console.error('deleteteamdatauser error:', err);
        return message.reply('> ❌ **حدث خطأ أثناء المسح، تحقق من الـ console.**');
    }
});

client.on('messageCreate', async (message) => {
    if (message.author.bot || !message.guild) return;

    const args = message.content.trim().split(/\s+/);
    if (args[0].toLowerCase() !== 'showbuttons') return;

    
    if (!isActiveOwner(message.author.id)) return;

    const msgID = args[1];
    if (!msgID) {
        return message.reply(
            `> ❌ **يرجى تحديد msgID!**\n` +
            `> \`showbuttons [msgID]\`\n` +
            `> **مثال:** \`showbuttons 1234567890123456789\``
        );
    }

    try {
        
        let bcData = await BombChips.findOne({ msgID });
        if (!bcData) {
            bcData = await BombChips.findOne({ $or: [{ p1: msgID }, { p2: msgID }] });
        }
        if (!bcData) {
            
            const recent = await BombChips.find().sort({ _id: -1 }).limit(5);
            const recentList = recent.length > 0
                ? recent.map(r => `\`${r.msgID}\` — <@${r.p1}> vs <@${r.p2}> | \`${r.phase}\``).join('\n> ')
                : 'لا توجد ألعاب حالية في الداتابيس';
            return message.reply(
                `> ❌ **ما لقيت لعبة بهذا الـ ID:** \`${msgID}\`\n` +
                `> *(جرب msgID أو user ID أحد اللاعبين)*\n> \n` +
                `> 📋 **آخر ألعاب Bomb Chips في الداتابيس:**\n> ${recentList}`
            );
        }

        const p1Bombs = new Set(bcData.p1Bombs || []);
        const p2Bombs = new Set(bcData.p2Bombs || []);
        const TOTAL_CHIPS = 9;

        
        const buildRevealRows = (bombSet, label) => {
            const rows = [];
            for (let r = 0; r < 3; r++) {
                const rowComp = new MessageActionRow();
                for (let c = 0; c < 3; c++) {
                    const idx = r * 3 + c;
                    const isBomb = bombSet.has(idx);
                    rowComp.addComponents(
                        new MessageButton()
                            .setCustomId(`showbtns_reveal_${label}_${idx}_${msgID}`)
                            .setLabel(isBomb ? '💣' : '🍟')
                            .setStyle(isBomb ? 'DANGER' : 'SUCCESS')
                            .setDisabled(true)
                    );
                }
                rows.push(rowComp);
            }
            return rows;
        };

        const p1user = await client.users.fetch(bcData.p1).catch(() => null);
        const p2user = await client.users.fetch(bcData.p2).catch(() => null);
        const p1tag = p1user ? p1user.tag : bcData.p1;
        const p2tag = p2user ? p2user.tag : bcData.p2;

        const embedP1 = new MessageEmbed()
            .setColor('#FF4444')
            .setTitle(`💣 قنابل P1 — ${p1tag}`)
            .setDescription(
                `> 🆔 **msgID:** \`${msgID}\`\n` +
                `> 👤 **P1:** <@${bcData.p1}>\n` +
                `> 👤 **P2:** <@${bcData.p2}>\n` +
                `> 💰 **الرهان:** \`${bcData.coins}\`\n` +
                `> 🔄 **المرحلة:** \`${bcData.phase}\`\n\n` +
                `> 💣 = قنبلة | 🍟 = آمن`
            )
            .setFooter({ text: `قنابل ${p1tag} (هي اللي P2 يخمن عليها)` });

        const embedP2 = new MessageEmbed()
            .setColor('#4444FF')
            .setTitle(`💣 قنابل P2 — ${p2tag}`)
            .setDescription(
                `> 💣 = قنبلة | 🍟 = آمن\n` +
                `> *(هذه قنابل ${p2tag} اللي P1 يخمن عليها)*`
            )
            .setFooter({ text: `قنابل ${p2tag} (هي اللي P1 يخمن عليها)` });

        
        await message.channel.send({
            embeds: [embedP1],
            components: buildRevealRows(p1Bombs, 'p1')
        });

        
        await message.channel.send({
            embeds: [embedP2],
            components: buildRevealRows(p2Bombs, 'p2')
        });

    } catch (e) {
        console.error('❌ خطأ في showbuttons:', e);
        return message.reply('> ❌ **حدث خطأ أثناء جلب البيانات، تحقق من الـ console.**');
    }
});

function formatCoins(coins, coinsLabel) {
    if (coins === -1 && coinsLabel) return coinsLabel;
    if (coins === -1) return '∞';
    return (coins || 0).toLocaleString();
}

